INSERT INTO `machine_machines` (`id`, `machine_name`, `slug`, `description`, `image_url`, `meta_title`, `meta_description`, `category_id`, `subcategory_id`, `specifications`, `created_at`, `updated_at`) VALUES
(2, 'MECHANICAL CUP FILLER POUCH PACKING MACHINE', 'item-1778476912', 'Semi Automatic Packaging Machine with electric driven system and single-phase operation. Supports 60–350 mm film width and 40–200 mm film length with 30 kg hopper capacity. Built with SS 304/202 structure, mechanical sealing system, and movable castor wheel base without air requirement.', '/uploads/machines/mechanical-cup-filler-pouch-packing-machine-1778668915.jpg', 'MECHANICAL CUP FILLER POUCH PACKING MACHINE', '', 2, 10, '{\"meta\":[],\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"0.5 HP\",\"Speed\":\"20 TO 80 BAGS PER MIN.\",\"Feeding\":\"CUP FILLER(4X1)\"},\"data\":[]}', '2026-05-11 05:21:52', '2026-05-14 06:58:38'),
(3, 'MECHANICAL POUCH PACKING MACHINE - CENTER SEAL', 'item-1778478133', 'Semi Automatic Packaging Machine with electric driven system and single-phase operation. Machine supports 60–350 mm film width and 40–200 mm film length, equipped with 4 ft to 12 ft conveyor length and 30 kg hopper capacity. Built with SS 304/202 structure, mechanical sealing system, castor wheel base, and operates without air requirement.', '/uploads/machines/mechanical-pouch-packing-machine-center-seal-1778669289.jpg', 'Semi Automatic Conveyor Cup Filler Packing Machine', '', 2, 10, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Semi Automatic Conveyor Cup Filler Packing Machine\"},\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"1 HP\",\"Speed\":\"20 TO 80 BAGS PER MIN.\",\"Feeding\":\"CUP FILLER(4X1)\"},\"data\":[]}', '2026-05-11 05:42:13', '2026-05-14 06:59:19'),
(4, 'PLC PNEUMATIC POUCH PACKING MACHINE', 'item-1778478476', 'Semi Automatic Packaging Machine with electric driven system and single-phase operation. Equipped with level sensor working elevator, 30 kg hopper capacity, and supports 60–350 mm film width with 40–200 mm film length. Built with SS 304/202 structure, mechanical sealing system, castor wheel base, and operates without air requirement.', '/uploads/machines/plc-pneumatic-pouch-packing-machine-1778670170.jpg', 'BRAND', 'SALVIN', 2, 10, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Semi Automatic Auger Filling Packing Machine\"},\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"0.5 HP\",\"Speed\":\"20 TO 80 BAGS PER MIN.\",\"Feeding\":\"AUGER FILLING\"},\"data\":[]}', '2026-05-11 05:47:56', '2026-05-14 06:59:50'),
(5, 'WEIGHT LOADER CELL POUCH PACKING MACHINE', 'item-1778478704', 'Semi Automatic Packaging Machine with electric driven system and single-phase operation. Machine features 4 ft to 12 ft conveyor length with AC drive control, level sensor working elevator, and 30 kg hopper capacity. Built with SS 304/202 structure, mechanical sealing system, castor wheel base, and supports 250 kg material capacity without air requirement.', '/uploads/machines/weight-loader-cell-pouch-packing-machine-1778913599.jpg', 'Semi Automatic Conveyor Auger Filling Packing Machine', '', 2, 10, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Semi Automatic Conveyor Auger Filling Packing Machine\"},\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"1 HP\",\"Speed\":\"20 TO 80 BAGS PER MIN.\",\"Feeding\":\"AUGER\"},\"data\":[]}', '2026-05-11 05:51:44', '2026-05-16 06:39:59'),
(6, 'HORIZONTAL POUCH MACHINE', 'item-1778478987', 'Automatic Packaging Machine with PLC based control system and PID temperature controller for accurate operation. Machine supports maximum 380 mm roll width and produces pillow type / center seal pouches with dimensions ranging from 60–140 mm length and 35–150 mm width. Requires 6 CFM air at 6 bar pressure and has machine dimensions of 3600 × 1500 × 2000 mm with 650 kg net weight.', '/uploads/machines/horizontal-pouch-machine-1778478987.png', 'BRAND', 'SALVIN', 2, 10, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Pillow Pouch Packing Machine\"},\"specifications\":{\"Voltage\":\"220 V, AC, Single Phase, 50 Hz\",\"Power\":\"3 kW\",\"Speed\":\"30-140 Pouch \\/ Min (Depends on laminate, Products size and shape)\",\"Feeding\":\"Manual, Auto Feeder (Conveyor, Trolley etc.)\"},\"data\":[]}', '2026-05-11 05:56:27', '2026-05-14 07:01:22'),
(7, 'HEAD SEMI AUTOMATIC LIQUID FILLING MACHINE', 'item-1778479260', 'Semi Automatic Liquid Filling Machine with electric driven system and single-phase operation. Equipped with 200-liter tank capacity and built using SS 304/316 structure for liquid applications. Machine features castor wheel base, operates without air requirement, and has a net weight of 70 kg.', '/uploads/machines/head-semi-automatic-liquid-filling-machine-1778913170.jpg', 'BRAND', 'SALVIN', 2, 17, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Semi Automatic Liquid Filling Machine\"},\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"0.5 HP\",\"Speed\":\"20 TO 80 PRODUCTS PER MIN.\",\"Feeding\":\"AUTOMATIC\"},\"data\":[]}', '2026-05-11 06:01:00', '2026-05-16 06:32:50'),
(9, 'HEAD AUTOMATIC VOLUMETRIC LIQUID FILLING MACHINE', 'item-1778479794', 'Automatic Liquid Filling Machine with 200-liter tank capacity and 8 ft conveyor system. Built with SS 304/316 structure, push button / PLC control, and requires 4 kg air pressure for operation. Machine comes with leg bolt base and net weight ranging from 300 to 400 kg.', '/uploads/machines/head-automatic-volumetric-liquid-filling-machine-1778479794.png', 'BRAND', 'SALVIN', 2, 17, '[{\"title\":\"AUTOMATION GRADE\",\"value\":\"AUTOMATIC\"},{\"title\":\"VOLTAGE\",\"value\":\"220 V\"},{\"title\":\"POWER\",\"value\":\"0.5 HP\"},{\"title\":\"SPEED\",\"value\":\"20 TO 80 PRODUCTS PER MIN\"},{\"title\":\"PHASE\",\"value\":\"Single \"}]', '2026-05-11 06:09:54', '2026-05-14 07:02:46'),
(11, 'HEAD VOLUMETRIC AUTOMATIC LIQUID FILLING MACHINE', 'item-1778480105', 'Automatic Liquid Filling Machine with electric driven system and three-phase operation. Equipped with 300-liter tank capacity and built using SS 304/316 structure for liquid filling applications. Machine requires 5 kg air pressure, features leg bolt base, and has a net weight of 650 kg.', '/uploads/machines/head-volumetric-automatic-liquid-filling-machine-1778480105.png', 'BRAND', 'SALVIN', 2, 17, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Liquid Filling Machine\"},\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"3 HP\",\"Speed\":\"20 TO 45 PRODUCTS PER MIN.\",\"Feeding\":\"AUTOMATIC\"},\"data\":[]}', '2026-05-11 06:15:05', '2026-05-14 07:03:27'),
(12, 'HEAD AUTOMATIC GEAR PUMP / SERVO FILLING MACHINE', 'head-automatic-gear-pump-servo-filling-machine', 'Automatic Liquid Filling Machine with electric driven system and three-phase operation. Machine features 10 ft conveyor with AC drive control, PLC system, and no bottle no filling sensor for accurate operation. Built with SS 304/316 structure, 200-liter tank capacity, acrylic cabinet, and requires 6 kg air pressure.', '/uploads/machines/head-automatic-gear-pump-servo-filling-machine-1778576065.jpg', 'BRAND', 'SALVIN', 2, 17, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Gear Pump Filling Machine\"},\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"1 HP\",\"Speed\":\"20 TO 40 BAGS PER MIN.\",\"Feeding\":\"GEAR PUMP\"},\"data\":[]}', '2026-05-12 08:54:25', '2026-05-14 07:04:10'),
(13, 'HEAD AUTOMATIC VOLUMETRIC LIQUID FILLING MACHINE', 'head-automatic-volumetric-liquid-filling-machine', 'Automatic Liquid Filling Machine with electric driven system and three-phase operation. Equipped with 500-liter tank capacity and built using SS 304/316 structure for liquid filling applications. Machine requires 5 kg air pressure, features leg bolt base, and has a net weight of 750 kg.', '/uploads/machines/head-automatic-volumetric-liquid-filling-machine-1778576542.jpg', 'BRAND', 'SALVIN', 2, 17, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Liquid Filling Machine\"},\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"3 HP\",\"Speed\":\"30 TO 65 PRODUCTS PER MIN.\",\"Feeding\":\"AUTOMATIC\"},\"data\":[]}', '2026-05-12 09:01:09', '2026-05-14 07:04:36'),
(14, 'SINGLE HEAD SCREW / ROPP CAPPING MACHINE', 'single-head-screw-ropp-capping-machine', 'Manual Type Capping Machine with electric driven system suitable for screw and ROPP caps. Built with durable SS 304/316 structure and operates without air requirement. Machine features leg bolt base and has a net weight of 70 kg.', '/uploads/machines/single-head-screw-ropp-capping-machine-1778576808.jpg', 'BRAND', 'SALVIN', 2, 18, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Manual Screw ROPP Capping Machine\"},\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"0.5 HP\",\"Speed\":\"20 TO 45 PRODUCTS PER MIN.\",\"Feeding\":\"MANUAL\"},\"data\":[]}', '2026-05-12 09:06:48', '2026-05-14 07:05:04'),
(15, 'LINEAR SCREW / ROPP CAPPING MACHINE', 'linear-screw-ropp-capping-machine', 'SALVIN Automatic Screw / ROPP Cap Feeding Machine is designed for smooth and efficient cap feeding operations. Built with durable SS 304/316 structure, the machine supports both screw and ROPP caps with automatic functionality. It requires 4 kg air pressure, features a sturdy leg bolt base, and has a net weight of 150 kg.', '/uploads/machines/linear-screw-ropp-capping-machine-1778665302.jpg', 'LINEAR SCREW / ROPP CAPPING MACHINE', '', 2, 18, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"\"},\"specifications\":{\"Automation Grade\":\"Automatic\",\"Voltage\":\"220 V\",\"Power\":\"1 HP\",\"Speed\":\"20 to 45 products per minute\"},\"data\":[]}', '2026-05-13 09:41:42', '2026-05-14 07:07:17'),
(16, 'STEPPER / SERVO LABELING MACHINE', 'stepper-servo-labeling-machine', 'Automatic Labeling Machine with PLC/Stepper based control system and electric driven operation. Machine supports both round and square labeling applications and is built with durable SS 304/316 structure. Requires 4 kg air pressure, features leg bolt base, and has a net weight of 120 kg.', '/uploads/machines/stepper-servo-labeling-machine-1778665912.jpg', 'Automatic PLC Stepper Labeling Machine', '', 2, 19, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic PLC Sticker Labeling Machine\"},\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"1 HP\",\"Speed\":\"20 TO 45 PRODUCTS PER MIN.\",\"Feeding\":\"AUTOMATIC\"},\"data\":[]}', '2026-05-13 09:51:52', '2026-05-14 07:06:13'),
(17, 'SINGLE HEAD GEL / CREAM FILLING MACHINE', 'single-head-gel-cream-filling-machine', 'Manual Type Filling Machine with electric driven system suitable for viscous material applications. Built with durable SS 304/316 structure, the machine requires 2 kg air pressure for operation. It features a sturdy leg bolt base and has a compact net weight of 30 kg.', '/uploads/machines/single-head-gel-cream-filling-machine-1778667068.jpg', 'Manual Viscous Filling Machine', '', 2, 8, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Manual Viscous Filling Machine\"},\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"0.5 HP\",\"Speed\":\"20 TO 45 PRODUCTS PER MIN.\",\"Feeding\":\"MANUAL\"},\"data\":[]}', '2026-05-13 10:11:08', '2026-05-14 07:08:07'),
(18, 'CARTAGE FILLING MACHINE', 'cartage-filling-machine', 'Automatic Cartage Machine with electric driven system for efficient packaging operations. Built with durable SS 304/316 structure, the machine requires 4 kg air pressure for smooth performance. It features a sturdy leg bolt base and has a net weight of 150 kg.', '/uploads/machines/cartage-filling-machine-1778667228.jpg', 'Automatic Cartage Machine', '', 2, 8, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Cartage Machine\"},\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"2 HP\",\"Speed\":\"20 TO 45 PRODUCTS PER MIN.\",\"Feeding\":\"AUTOMATIC\"},\"data\":[]}', '2026-05-13 10:13:48', '2026-05-14 07:08:30'),
(19, 'AUTOMATIC TUBE FILLING & SEALING MACHINE', 'automatic-tube-filling-sealing-machine', 'Automatic Tube Filling Machine with electric driven system suitable for LAMI and ALU tubes. Built with durable SS 304/316 structure, the machine requires 4 kg air pressure for smooth operation. It features a sturdy leg bolt base and has a net weight of 150 kg.', '/uploads/machines/automatic-tube-filling-sealing-machine-1778667846.jpg', 'Automatic Tube Filling Machine', '', 2, 17, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Tube Filling Machine\"},\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"2 HP\",\"Speed\":\"20 TO 85 PRODUCTS PER MIN.\",\"Feeding\":\"AUTOMATIC\"},\"data\":[]}', '2026-05-13 10:24:06', '2026-05-14 07:08:53'),
(20, 'ADHESIVE FILLING MACHINE', 'adhesive-filling-machine', 'Automatic PLC/Stepper Based Filling Machine suitable for rubber solution applications. Built with durable SS 304/316 structure, the machine operates with electric driven system and requires 4 kg air pressure. It features a sturdy leg bolt base and has a net weight of 120 kg.', '/uploads/machines/adhesive-filling-machine-1778667988.jpg', 'Automatic Rubber Solution Filling Machine', '', 2, 8, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Rubber Solution Filling Machine\"},\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"1 HP\",\"Speed\":\"20 TO 45 PRODUCTS PER MIN.\",\"Feeding\":\"AUTOMATIC\"},\"data\":[]}', '2026-05-13 10:26:28', '2026-05-14 07:09:22'),
(21, 'ELECTRIC STIRRER', 'electric-stirrer', 'Manual Type Filling Machine suitable for viscous and gel material applications. Built with durable SS 304/316 structure, the machine operates with electric driven system and does not require air supply. It features wheel base design for easy movement and has a net weight of 80 kg.', '/uploads/machines/electric-stirrer-1778668097.jpg', 'Manual Viscous Gel Mixing Machine', '', 1, 20, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Manual Viscous Gel Mixing Machine\"},\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"3 HP\",\"Speed\":\"AS PER REQUIRE\",\"Feeding\":\"MANUAL\"},\"data\":[]}', '2026-05-13 10:28:17', '2026-05-14 07:09:45'),
(22, 'MASS MIXER', 'mass-mixer', 'Automatic Mixing Machine with electric driven system and 500 kg capacity for efficient mixing operations. Built with durable SS 304/316 structure, the machine operates without air requirement. It features a sturdy leg bolt base and has a net weight of 250 kg.', '/uploads/machines/mass-mixer-1778668321.jpg', 'Automatic Mixing Machine', '', 1, 21, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Mixing Machine\"},\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"2 HP\",\"Speed\":\"AS PER REQUIRE\",\"Feeding\":\"N\\/A\"},\"data\":[]}', '2026-05-13 10:32:01', '2026-05-14 07:10:07'),
(23, 'REACTORS', 'reactors', 'Automatic Processing Tank with electric driven system and 10 KL capacity for industrial processing applications. Suitable for coil, glass, and metal type processing, the machine is built with durable SS 304/316 structure. Equipped with stirrer arrangement as per design and strong structural support for reliable operation.', '/uploads/machines/reactors-1778668538.jpg', 'Automatic Processing Vessel', '', 1, 22, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Processing Vessel\"},\"specifications\":{\"Voltage\":\"220 V\",\"Power\":\"2 HP\"},\"data\":[]}', '2026-05-13 10:35:38', '2026-05-14 07:10:30'),
(24, 'TREY / FBD DRYER', 'trey-fbd-dryer', 'Automatic PLC/Stepper Based Machine suitable for tray and FBD applications. Built with electric driven system and durable SS 304/316 structure for reliable industrial performance. Designed for efficient automated operation in processing and handling applications.', '/uploads/machines/trey-fbd-dryer-1778668658.jpg', 'Automatic Tray FBD Dryer Machine', '', 1, 23, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Tray FBD Dryer Machine\"},\"specifications\":{\"Feeding\":\"STEAM or ELECTRIC\"},\"data\":[]}', '2026-05-13 10:37:38', '2026-05-14 07:10:54'),
(25, 'SEMI AUTOMATIC WEIGHT LOAD CELL MACHINE', 'semi-automatic-weight-load-cell-machine', 'Semi-Automatic Load Cell Filling Machine suitable for free flow powder and granuals packaging. Machine supports 1 Grams to 1000 Kg filling capacity with pneumatic operation and electric-air driven system. Compatible with any type of packaging materials and designed for 400-700 pouch per hour production capacity.', '/uploads/machines/semi-automatic-weight-load-cell-machine-1778740726.jpg', 'SEMI AUTOMATIC WEIGHT LOAD CELL MACHINE', '', 2, 10, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Semi Automatic Load Cell Filling Machine\"},\"specifications\":{\"Power\":\"1 H.P. \\/ PLC \\/ CONTROLLER\",\"Speed\":\"400- 700\",\"Feeding\":\"Pneumatic\"},\"data\":[]}', '2026-05-14 06:38:46', '2026-05-14 06:40:33'),
(26, 'HEAD POUCH PACKING MACHINE', 'head-pouch-packing-machine', 'Automatic packaging machine designed for Powder, Granules, and Frymus packaging applications. Suitable for Powder & Granules processing with pouch filling capacity of 50-200 grams.', '/uploads/machines/head-pouch-packing-machine-1778741014.jpg', 'Automatic Powder Granules Packaging Machine', '', 2, 10, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Powder Granules Packaging Machine\"},\"specifications\":{\"Voltage\":\"N\\/A\",\"Power\":\"N\\/A\",\"Speed\":\"N\\/A\",\"Feeding\":\"N\\/A\"},\"data\":[]}', '2026-05-14 06:43:34', '2026-05-14 06:43:34'),
(27, 'MULTI HEAD POUCH PACKING MACHINE', 'multi-head-pouch-packing-machine', 'Automatic Multihead Weigher Packaging Machine with PLC-controlled operation and electric driven system for efficient packaging performance.Machine supports 100–500mm film width and 80–300mm film length, with optional features like Batch Coding, Nitrogen Flushing, Batch Cutting, and Air Compressor attachment.', '/uploads/machines/multi-head-pouch-packing-machine-1778741410.jpg', 'Automatic Multihead Weigher Packaging Machine', '', 2, 10, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Multihead Weigher Packaging Machine\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"Power\":\"4 to 5 kW\",\"Speed\":\"30 TO 60 Bag\\/min (Varies with the nature of Product and Filling Range)\",\"Feeding\":\"Weigher Filler 10 Head & 14 Head\"},\"data\":[]}', '2026-05-14 06:45:41', '2026-05-14 06:53:05'),
(28, 'oil bottle filling machine', 'oil-bottle-filling-machine', 'Automatic Oil Bottle Filling Machine designed for accurate and high-speed liquid filling applications.\r\nMachine is suitable for edible oil, mustard oil, coconut oil, and lubricant oil filling in PET, plastic, and glass bottles.Equipped with PLC controlled automation, stainless steel body, and multi-head volumetric filling system for efficient production.', '/uploads/machines/oil-bottle-filling-machine-1778757037.jpg', 'Automatic Oil Bottle Filling Machine', '', 2, 17, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Oil Bottle Filling Machine\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"Power\":\"2 to 4 kW\",\"Automation Grade\":\"Automatic\",\"Filling Capacity\":\"100ml To 5 Litre\",\"Filling Accuracy\":\"+\\/-1%\",\"Production Speed\":\"20 To 60 Bottles\\/min\",\"Driven Type\":\"Electric\",\"Filling Type\":\"Volumetric Filling\",\"Bottle Type\":\"PET \\/ Plastic \\/ Glass Bottles\",\"Material\":\"S.S. 304 \\/ 316\",\"Control System\":\"PLC Controlled\",\"Nozzle Type\":\"2 \\/ 4 \\/ 6 \\/ 8 Head Filling\",\"Application\":\"Edible Oil, Mustard Oil, Coconut Oil, Lubricant Oil\"},\"data\":[]}', '2026-05-14 11:10:37', '2026-05-14 11:10:37'),
(29, 'paste filling machine', 'paste-filling-machine', 'Automatic Paste Filling Machine designed for accurate filling of thick and viscous machine_products like cream, gel, sauce, honey, and cosmetic paste.Machine is built with stainless steel construction and supports pneumatic or electric piston filling for hygienic and efficient operation.', '/uploads/machines/paste-filling-machine-1778757214.jpg', 'Automatic Paste Filling Machine', '', 2, 17, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Paste Filling Machine\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"Power\":\"1 to 3 kW\",\"Automation Grade\":\"Automatic \\/ Semi Automatic\",\"Filling Capacity\":\"10ml To 5000ml\",\"Filling Accuracy\":\"+\\/-1%\",\"Production Speed\":\"10 To 60 Bottles\\/min\",\"Driven Type\":\"Pneumatic \\/ Electric\",\"Filling Type\":\"Piston Filling\",\"Nozzle Type\":\"Single \\/ Double \\/ Multi Head\",\"Material\":\"S.S. 304 \\/ 316\",\"Control System\":\"PLC Controlled\",\"Application\":\"Cream, Gel, Honey, Sauce, Paste, Cosmetic, Shampoo\",\"Container Type\":\"Bottle \\/ Jar \\/ Tube \\/ Pouch\"},\"data\":[]}', '2026-05-14 11:13:34', '2026-05-14 11:13:34'),
(30, 'shampoo bottle filling machine', 'shampoo-bottle-filling-machine', 'Automatic Shampoo Bottle Filling Machine designed for accurate filling of shampoo, conditioner, lotion, and liquid soap machine_products. Machine is equipped with PLC touch screen control, servo driven filling system, and stainless steel body for hygienic operation.', '/uploads/machines/shampoo-bottle-filling-machine-1778998329.jpg', 'Automatic Shampoo Bottle Filling Machine', '', 2, 17, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Shampoo Bottle Filling Machine\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"Power\":\"3 to 5 kW\",\"Automation Grade\":\"Automatic\",\"Filling Capacity\":\"50ml To 5000ml\",\"Filling Accuracy\":\"+\\/-0.5% to +\\/-1%\",\"Production Speed\":\"30 To 100 Bottles\\/min\",\"Driven Type\":\"Servo \\/ Electric\",\"Filling Type\":\"Piston \\/ Volumetric Filling\",\"Nozzle Type\":\"2 \\/ 4 \\/ 6 \\/ 8 \\/ 12 Head\",\"Material\":\"S.S. 304 \\/ 316\",\"Control System\":\"PLC & Touch Screen\",\"Bottle Type\":\"PET \\/ Plastic \\/ Glass Bottles\",\"Application\":\"Shampoo, Conditioner, Lotion, Liquid Soap, Cosmetic Products\",\"Air Pressure\":\"0.6 to 0.8 MPa\"},\"data\":[]}', '2026-05-14 11:16:37', '2026-05-17 06:12:09'),
(31, 'spices pouch packing machine', 'spices-pouch-packing-machine', 'Automatic Spices Pouch Packing Machine suitable for accurate and high-speed packing of spice powders and masala machine_products. Machine is equipped with auger filler system, PLC touch screen control, and stainless steel body for hygienic and continuous operation.', '/uploads/machines/spices-pouch-packing-machine-1778757624.jpg', 'Automatic Spices Pouch Packing Machine', '', 2, 10, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Spices Pouch Packing Machine\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"Power Consumption\":\"4 to 6 kW\",\"Automation Grade\":\"Automatic\",\"Packaging Capacity\":\"10gm To 1Kg\",\"Machine Speed\":\"40 To 90 Pouch\\/min\",\"Filling Accuracy\":\"+\\/-1%\",\"Driven Type\":\"Electric\",\"Filling System\":\"Auger Filler\",\"Sealing Type\":\"Center Seal \\/ 3 Side Seal \\/ 4 Side Seal\",\"Pouch Type\":\"Laminated Pouch\",\"Film Material\":\"Polyester \\/ PE \\/ PP Laminated Film\",\"Control System\":\"PLC Controlled With Touch Screen\",\"Material\":\"S.S. 304 \\/ 316\",\"Application\":\"Spices Powder, Masala Powder, Turmeric Powder, Chilli Powder, Coriander Powder\"},\"data\":[]}', '2026-05-14 11:20:24', '2026-05-14 11:20:24'),
(32, 'flour pouch packing machine', 'flour-pouch-packing-machine', 'Automatic Flour Pouch Packing Machine designed for accurate and hygienic packing of flour and powder machine_products. Machine is equipped with auger filling system, PLC touch screen control, and stainless steel body for continuous industrial operation.', '/uploads/machines/flour-pouch-packing-machine-1778758215.jpg', 'Automatic Flour Pouch Packing Machine', '', 2, 10, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Flour Pouch Packing Machine\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"Power Consumption\":\"3 to 5 kW\",\"Automation Grade\":\"Automatic\",\"Packaging Capacity\":\"100gm To 5Kg\",\"Machine Speed\":\"20 To 60 Pouch\\/min\",\"Filling Accuracy\":\"+\\/-1%\",\"Driven Type\":\"Electric\",\"Filling System\":\"Auger Filler\",\"Sealing Type\":\"Center Seal \\/ 3 Side Seal\",\"Pouch Type\":\"Laminated Pouch\",\"Film Material\":\"PE \\/ PP \\/ Laminated Film\",\"Control System\":\"PLC Controlled With Touch Screen\",\"Material\":\"S.S. 304 \\/ 316\",\"Application\":\"Wheat Flour, Maida, Besan, Atta, Powder Products\"},\"data\":[]}', '2026-05-14 11:30:15', '2026-05-14 11:30:15'),
(33, 'Milk powder filling machine', 'milk-powder-filling-machine', 'Automatic Milk Powder Filling Machine designed for accurate and dust-free filling of milk powder and dairy machine_products.Machine is equipped with auger filler system, PLC touch screen control, and stainless steel construction for hygienic operation.', '/uploads/machines/milk-powder-filling-machine-1778837191.jpg', 'Automatic Milk Powder Filling Machine', '', 2, 17, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Milk Powder Filling Machine\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"Power Consumption\":\"3 to 5 kW\",\"Automation Grade\":\"Automatic\",\"Filling Capacity\":\"50gm To 5Kg\",\"Filling Accuracy\":\"+\\/-1%\",\"Production Speed\":\"20 To 70 Containers\\/min\",\"Driven Type\":\"Electric\",\"Filling System\":\"Auger Filler\",\"Container Type\":\"Bottle \\/ Jar \\/ Pouch \\/ Tin\",\"Material\":\"S.S. 304 \\/ 316\",\"Control System\":\"PLC Controlled With Touch Screen\",\"Nozzle Type\":\"Single \\/ Double Head\",\"Application\":\"Milk Powder, Dairy Powder, Protein Powder, Nutritional Powder\"},\"data\":[]}', '2026-05-15 09:26:31', '2026-05-15 09:26:31'),
