(93, 'Automatic Mineral Water Bottling Plant', 'automatic-mineral-water-bottling-plant', 'Automatic Mineral Water Bottling Plant designed for high-speed and hygienic production of packaged drinking water bottles.Machine is equipped with rinsing, filling, and capping system along with PLC touch screen control for continuous industrial operation.', '/uploads/machines/automatic-mineral-water-bottling-plant-1779253048.jpg', 'Automatic Mineral Water Bottling Plant', '', 2, 17, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Mineral Water Bottling Plant\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"Power Consumption\":\"10 to 30 kW\",\"Automation Grade\":\"Automatic\",\"Production Capacity\":\"500 To 10000 Bottles\\/hour\",\"Bottle Capacity\":\"200ml To 2 Litre\",\"Filling Accuracy\":\"+\\/-0.5%\",\"Driven Type\":\"Servo \\/ Electric\",\"Filling System\":\"Gravity \\/ Volumetric Filling\",\"Bottle Type\":\"PET Bottles\",\"Machine Functions\":\"Rinsing, Filling & Capping\",\"Material\":\"S.S. 304 \\/ 316\",\"Control System\":\"PLC Controlled With Touch Screen\",\"Cap Type\":\"ROPP \\/ Plastic Cap\",\"Application\":\"Mineral Water, Drinking Water, Packaged Water Products\"},\"data\":[]}', '2026-05-20 04:57:28', '2026-05-20 04:57:28'),
(94, 'High-Speed Rotary Water Bottle Filling Line', 'high-speed-rotary-water-bottle-filling-line', 'High-Speed Rotary Water Bottle Filling Line designed for continuous and high-capacity production of bottled drinking water.Machine is equipped with rotary rinsing, filling, and capping system along with PLC touch screen control for efficient industrial operation.', '/uploads/machines/high-speed-rotary-water-bottle-filling-line-1779253138.jpg', 'High-Speed Rotary Water Bottle Filling Line', '', 2, 17, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"High-Speed Rotary Water Bottle Filling Line\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"Power Consumption\":\"15 to 40 kW\",\"Automation Grade\":\"Automatic\",\"Production Capacity\":\"2000 To 24000 Bottles\\/hour\",\"Bottle Capacity\":\"200ml To 2 Litre\",\"Filling Accuracy\":\"+\\/-0.5%\",\"Driven Type\":\"Servo \\/ Electric\",\"Filling System\":\"Rotary Gravity Filling\",\"Bottle Type\":\"PET Bottles\",\"Machine Functions\":\"Bottle Rinsing, Filling & Capping\",\"Material\":\"S.S. 304 \\/ 316\",\"Control System\":\"PLC Controlled With Touch Screen\",\"Cap Type\":\"Plastic Screw Cap\",\"Application\":\"Mineral Water, Drinking Water, Packaged Water Products\"},\"data\":[]}', '2026-05-20 04:58:58', '2026-05-20 04:58:58');
