(95, '20 Liter Jar Washing, Filling & Capping Machine', '20-liter-jar-washing-filling-capping-machine', '20 Liter Jar Washing, Filling & Capping Machine designed for hygienic and efficient processing of large water jars.Machine is equipped with multi stage jar washing, precision filling, and automatic capping system with PLC touch screen control for continuous industrial operation.', '/uploads/machines/20-liter-jar-washing-filling-capping-machine-1779253220.jpg', '20 Liter Jar Washing, Filling & Capping Machine', '', 2, 17, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"20 Liter Jar Washing, Filling & Capping Machine\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 12 kW\",\"AutomationGrade\":\"Automatic\",\"ProductionCapacity\":\"60 To 300 Jar\\/hour\",\"JarCapacity\":\"20 Liter\",\"FillingAccuracy\":\"+\\/-0.5%\",\"DrivenType\":\"Electric \\/ Pneumatic\",\"MachineFunctions\":\"Jar Washing, Filling & Capping\",\"JarType\":\"PC \\/ PET Water Jars\",\"WashingStages\":\"Inside & Outside Multi Stage Washing\",\"Material\":\"S.S. 304 \\/ 316\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"CapType\":\"Press Fit \\/ Screw Cap\",\"Application\":\"Mineral Water, Drinking Water, Packaged Water Jar Products\"},\"data\":[]}', '2026-05-20 05:00:20', '2026-05-20 05:00:20'),
(96, 'RO Water Purification & Mineral Dosing System', 'ro-water-purification-mineral-dosing-system', 'RO Water Purification & Mineral Dosing System designed for high-quality purification and mineral balancing of drinking water.System is equipped with multi-stage filtration, reverse osmosis technology, UV sterilization, and automatic mineral dosing for hygienic water treatment operation.', '/uploads/machines/ro-water-purification-mineral-dosing-system-1779253311.jpg', 'RO Water Purification & Mineral Dosing System', '', 2, 17, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"RO Water Purification & Mineral Dosing System\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"3 to 15 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"PurificationCapacity\":\"500 LPH To 10000 LPH\",\"ROType\":\"Reverse Osmosis Water Treatment System\",\"FiltrationStages\":\"Sand Filter, Carbon Filter, Micron Filter, RO Membrane, UV & Ozone\",\"MineralDosing\":\"Automatic Mineral Dosing System\",\"WaterRecovery\":\"50% To 75%\",\"Material\":\"S.S. 304 \\/ FRP\",\"ControlSystem\":\"PLC Controlled With Digital Display\",\"OperatingPressure\":\"High Pressure Pump System\",\"Application\":\"Mineral Water, Drinking Water, Food & Beverage Water Treatment\"},\"data\":[]}', '2026-05-20 05:01:51', '2026-05-20 05:01:51'),
(97, 'Automatic Water Bottling Line With Labeling Machine', 'automatic-water-bottling-line-with-labeling-machine', 'Automatic Water Bottling Line With Labeling Machine designed for high-speed and hygienic production of packaged drinking water bottles.Machine line is equipped with rinsing, filling, capping, and automatic labeling system along with PLC touch screen control for continuous industrial operation', '/uploads/machines/automatic-water-bottling-line-with-labeling-machine-1779253401.jpg', 'Automatic Water Bottling Line With Labeling Machine', '', 2, 17, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Water Bottling Line With Labeling Machine\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"12 to 35 kW\",\"AutomationGrade\":\"Automatic\",\"ProductionCapacity\":\"1000 To 24000 Bottles\\/hour\",\"BottleCapacity\":\"200ml To 2 Litre\",\"FillingAccuracy\":\"+\\/-0.5%\",\"DrivenType\":\"Servo \\/ Electric\",\"MachineFunctions\":\"Bottle Rinsing, Filling, Capping & Labeling\",\"BottleType\":\"PET Bottles\",\"LabelType\":\"Sticker Label \\/ Sleeve Label\",\"Material\":\"S.S. 304 \\/ 316\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"CapType\":\"Plastic Screw Cap\",\"Application\":\"Mineral Water, Drinking Water, Packaged Water Bottles\"},\"data\":[]}', '2026-05-20 05:03:21', '2026-05-20 05:03:21'),
(98, 'Water Bottling Machine With Inline Bottle Conveyor & Air Dryer System', 'water-bottling-machine-with-inline-bottle-conveyor-air-dryer-system', 'Water Bottling Machine With Inline Bottle Conveyor & Air Dryer System designed for high-speed and hygienic bottled water production.Machine is equipped with rinsing, filling, capping, inline conveyor, and air dryer system along with PLC touch screen control for continuous industrial operation.', '/uploads/machines/water-bottling-machine-with-inline-bottle-conveyor-air-dryer-system-1779340957.jpg', 'Water Bottling Machine With Inline Bottle Conveyor & Air Dryer System', '', 2, 17, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Water Bottling Machine With Inline Bottle Conveyor & Air Dryer System\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"15 to 40 kW\",\"AutomationGrade\":\"Automatic\",\"ProductionCapacity\":\"1000 To 24000 Bottles\\/hour\",\"BottleCapacity\":\"200ml To 2 Litre\",\"FillingAccuracy\":\"+\\/-0.5%\",\"DrivenType\":\"Servo \\/ Electric\",\"MachineFunctions\":\"Bottle Rinsing, Filling, Capping, Conveying & Air Drying\",\"BottleType\":\"PET Bottles\",\"ConveyorSystem\":\"Inline SS Conveyor System\",\"AirDryerSystem\":\"High Pressure Air Blower Dryer\",\"Material\":\"S.S. 304 \\/ 316\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"CapType\":\"Plastic Screw Cap\",\"Application\":\"Mineral Water, Drinking Water, Packaged Water Bottles\"},\"data\":[]}', '2026-05-21 05:22:37', '2026-05-21 05:22:37'),
(99, 'Standy Zipper Spices Powder Pouch Packing Machine', 'standy-zipper-spices-powder-pouch-packing-machine', 'Automatic Standy Zipper Spices Powder Pouch Packing Machine designed for accurate and hygienic packing of spice powder machine_products in zipper pouches.Machine is equipped with auger filling system, PLC touch screen control, and stainless steel construction for continuous industrial packaging operation.', '/uploads/machines/standy-zipper-spices-powder-pouch-packing-machine-1779351970.jpg', 'Automatic Standy Zipper Spices Powder Pouch Packing Machine', '', 2, 10, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Standy Zipper Spices Powder Pouch Packing Machine\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"PowerConsumption\":\"4 to 7 kW\",\"AutomationGrade\":\"Automatic\",\"PackagingCapacity\":\"50gm To 5Kg\",\"MachineSpeed\":\"15 To 50 Pouch\\/min\",\"FillingAccuracy\":\"+\\/-1%\",\"DrivenType\":\"Servo \\/ Electric\",\"FillingSystem\":\"Auger Filler\",\"PouchType\":\"Standy Zipper Pouch\",\"SealingType\":\"Zipper Sealing & Heat Sealing\",\"FilmMaterial\":\"Laminated Film \\/ PE \\/ PP\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"Material\":\"S.S. 304 \\/ 316\",\"Application\":\"Spices Powder, Masala Powder, Turmeric Powder, Chilli Powder, Food Powder Products\"},\"data\":[]}', '2026-05-21 08:26:10', '2026-05-21 08:26:10'),
(100, 'Pick Fill Seal Standy Zipper Pouch Namkeen Packing Machine', 'pick-fill-seal-standy-zipper-pouch-namkeen-packing-machine', 'Automatic Pick Fill Seal Standy Zipper Pouch Namkeen Packing Machine designed for high-speed and hygienic packing of namkeen and snack machine_products in zipper pouches.Machine is equipped with multihead weigher system, PLC touch screen control, and servo driven pick fill seal mechanism for continuous industrial operation.', '/uploads/machines/pick-fill-seal-standy-zipper-pouch-namkeen-packing-machine-1779352075.jpg', 'Automatic Pick Fill Seal Standy Zipper Pouch Namkeen Packing Machine', '', 2, 10, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Pick Fill Seal Standy Zipper Pouch Namkeen Packing Machine\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"PowerConsumption\":\"5 to 8 kW\",\"AutomationGrade\":\"Automatic\",\"PackagingCapacity\":\"20gm To 2Kg\",\"MachineSpeed\":\"15 To 60 Pouch\\/min\",\"FillingAccuracy\":\"+\\/-0.5 to 1%\",\"DrivenType\":\"Servo \\/ Pneumatic\",\"FillingSystem\":\"Multihead Weigher\",\"PouchType\":\"Standy Zipper Pouch\",\"MachineType\":\"Pick Fill Seal System\",\"SealingType\":\"Zipper Sealing & Heat Sealing\",\"FilmMaterial\":\"Laminated Preformed Pouch\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"Material\":\"S.S. 304\",\"Application\":\"Namkeen, Snacks, Chips, Dry Fruits, Food Products\"},\"data\":[]}', '2026-05-21 08:27:55', '2026-05-21 08:27:55'),
