(127, 'Infrared Dryer', 'infrared-dryer', 'Industrial Infrared Dryer designed for rapid and energy-efficient drying using infrared radiation heating technology.Machine is equipped with infrared heating system, conveyor based material movement, and PLC temperature control for continuous industrial operation.', '/uploads/machines/infrared-dryer-1779515286.jpg', 'Industrial Infrared Dryer', '', 1, 23, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Infrared Dryer\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"PowerConsumption\":\"3 to 50 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"DryingCapacity\":\"10Kg To 3000Kg\\/hour\",\"DryingMethod\":\"Infrared Radiation Drying\",\"HeatingType\":\"Infrared Electric Heaters\",\"TemperatureRange\":\"50\\u00b0C To 350\\u00b0C\",\"ConveyorType\":\"Mesh Belt \\/ Roller Conveyor\",\"Material\":\"S.S. 304 \\/ MS Body\",\"ControlSystem\":\"PLC Controlled With Digital Temperature Control\",\"DryingSystem\":\"Rapid Surface Heating & Moisture Removal\",\"EnergyEfficiency\":\"Fast Drying With Reduced Energy Consumption\",\"Application\":\"Food Products, Paint, Textile, Paper, Chemicals, Pharmaceuticals\"},\"data\":[]}', '2026-05-23 05:48:06', '2026-05-23 05:48:06'),
(128, 'Ribbon Blender', 'ribbon-blender', 'Industrial Ribbon Blender designed for uniform and efficient mixing of powders, granules, and dry materials.Machine is equipped with double helical ribbon mixing system, heavy duty gear motor, and stainless steel construction for continuous industrial operation.', '/uploads/machines/ribbon-blender-1779515327.jpg', 'Industrial Ribbon Blender', '', 1, 21, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Ribbon Blender\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"3 to 30 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"MixingCapacity\":\"50Kg To 5000Kg\\/batch\",\"MixingType\":\"Horizontal Ribbon Mixing\",\"BlenderType\":\"Double Helical Ribbon Blender\",\"Material\":\"S.S. 304 \\/ 316 \\/ MS Body\",\"DischargeType\":\"Bottom Pneumatic \\/ Manual Valve Discharge\",\"DriveType\":\"Gear Motor Driven System\",\"ControlSystem\":\"PLC Controlled \\/ Digital Control Panel\",\"MixingEfficiency\":\"Uniform & Fast Powder Mixing\",\"ConstructionType\":\"U Shape Mixing Chamber\",\"Application\":\"Spices, Powder, Chemicals, Food Products, Pharmaceutical Products\"},\"data\":[]}', '2026-05-23 05:48:47', '2026-05-23 05:48:47'),
(129, 'Paddle Mixer', 'paddle-mixer', 'Industrial Paddle Mixer designed for uniform and gentle mixing of powders, granules, and bulk materials.Machine is equipped with paddle mixing system, heavy duty gear motor, and stainless steel construction for continuous industrial operation.', '/uploads/machines/paddle-mixer-1779515384.jpg', 'Industrial Paddle Mixer', '', 1, 21, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Paddle Mixer\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"3 to 35 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"MixingCapacity\":\"50Kg To 5000Kg\\/batch\",\"MixingType\":\"Horizontal Paddle Mixing\",\"MixerType\":\"Single Shaft \\/ Double Shaft Paddle Mixer\",\"Material\":\"S.S. 304 \\/ 316 \\/ MS Body\",\"DischargeType\":\"Bottom Pneumatic \\/ Manual Valve Discharge\",\"DriveType\":\"Gear Motor Driven System\",\"ControlSystem\":\"PLC Controlled \\/ Digital Control Panel\",\"MixingEfficiency\":\"Uniform & Gentle Material Mixing\",\"ConstructionType\":\"Horizontal Mixing Chamber\",\"Application\":\"Powder, Granules, Animal Feed, Chemicals, Food Products\"},\"data\":[]}', '2026-05-23 05:49:44', '2026-05-23 05:49:44'),
(130, 'Planetary Mixer', 'planetary-mixer', 'Industrial Planetary Mixer designed for efficient and uniform mixing of high viscosity materials and paste machine_products.Machine is equipped with planetary agitator system, variable speed control, and stainless steel construction for hygienic industrial operation.', '/uploads/machines/planetary-mixer-1779515418.jpg', 'Industrial Planetary Mixer', '', 1, 21, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Planetary Mixer\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"PowerConsumption\":\"2 to 25 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"MixingCapacity\":\"5 Litre To 500 Litre\",\"MixingType\":\"Planetary Mixing\",\"MixerType\":\"Single \\/ Double Planetary Agitator\",\"Material\":\"S.S. 304 \\/ 316\",\"BowlType\":\"Removable Stainless Steel Bowl\",\"DriveType\":\"Gear Motor Driven System\",\"ControlSystem\":\"PLC Controlled \\/ Digital Control Panel\",\"MixingEfficiency\":\"High Viscosity Uniform Mixing\",\"SpeedControl\":\"Variable Speed Control System\",\"Application\":\"Cream, Paste, Pharmaceutical, Cosmetic, Food & Chemical Products\"},\"data\":[]}', '2026-05-23 05:50:18', '2026-05-23 05:50:18'),
(131, 'Double Cone Blender', 'double-cone-blender', 'Industrial Double Cone Blender designed for uniform and gentle blending of dry powders and granule materials.Machine is equipped with rotating double cone vessel, gear motor drive system, and stainless steel construction for hygienic industrial operation.', '/uploads/machines/double-cone-blender-1779515461.jpg', 'Industrial Double Cone Blender', '', 1, 21, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Double Cone Blender\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"2 to 20 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"MixingCapacity\":\"25Kg To 3000Kg\\/batch\",\"MixingType\":\"Tumbling Dry Powder Mixing\",\"BlenderType\":\"Double Cone Rotating Blender\",\"Material\":\"S.S. 304 \\/ 316\",\"DischargeType\":\"Butterfly Valve \\/ Pneumatic Valve Discharge\",\"DriveType\":\"Gear Motor Driven Rotation System\",\"ControlSystem\":\"PLC Controlled \\/ Digital Control Panel\",\"MixingEfficiency\":\"Uniform & Gentle Powder Blending\",\"ConstructionType\":\"Double Cone Vessel Design\",\"Application\":\"Pharmaceuticals, Chemicals, Food Powder, Granules & Cosmetic Products\"},\"data\":[]}', '2026-05-23 05:51:01', '2026-05-23 05:51:01');
INSERT INTO `machine_machines` (`id`, `machine_name`, `slug`, `description`, `image_url`, `meta_title`, `meta_description`, `category_id`, `subcategory_id`, `specifications`, `created_at`, `updated_at`) VALUES
(132, 'High-Shear Mixer', 'high-shear-mixer', 'Industrial High-Shear Mixer designed for rapid emulsification and homogeneous mixing of liquid, cream, and viscous machine_products.Machine is equipped with high speed rotor stator system, stainless steel mixing vessel, and PLC touch screen control for efficient industrial operation.', '/uploads/machines/high-shear-mixer-1779515493.jpg', 'Industrial High-Shear Mixer', '', 1, 21, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial High-Shear Mixer\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 50 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"MixingCapacity\":\"10 Litre To 5000 Litre\",\"MixingType\":\"High Shear Rapid Mixing\",\"MixerType\":\"Rotor Stator High-Shear Mixer\",\"Material\":\"S.S. 304 \\/ 316\",\"DriveType\":\"High Speed Motor Driven System\",\"SpeedRange\":\"1000 To 3000 RPM\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"MixingEfficiency\":\"Fast Emulsification & Homogeneous Mixing\",\"ConstructionType\":\"Closed Hygienic Mixing Vessel\",\"Application\":\"Cream, Lotion, Emulsion, Pharmaceutical, Cosmetic & Food Products\"},\"data\":[]}', '2026-05-23 05:51:33', '2026-05-23 05:51:33'),
(133, 'Tumbler Mixer', 'tumbler-mixer', 'Industrial Tumbler Mixer designed for gentle and uniform blending of powders and granule materials through rotary tumbling action.Machine is equipped with rotating drum mixing system, gear motor drive, and stainless steel construction for hygienic industrial operation.', '/uploads/machines/tumbler-mixer-1779515530.jpg', 'Industrial Tumbler Mixer', '', 1, 21, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Tumbler Mixer\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"2 to 15 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"MixingCapacity\":\"25Kg To 2000Kg\\/batch\",\"MixingType\":\"Rotary Tumbling Mixing\",\"MixerType\":\"Drum \\/ Bin Tumbler Mixer\",\"Material\":\"S.S. 304 \\/ 316\",\"DischargeType\":\"Manual \\/ Pneumatic Discharge\",\"DriveType\":\"Gear Motor Driven Rotation System\",\"ControlSystem\":\"PLC Controlled \\/ Digital Control Panel\",\"MixingEfficiency\":\"Gentle & Uniform Powder Blending\",\"ConstructionType\":\"Rotating Drum Mixing System\",\"Application\":\"Powder, Granules, Food Products, Pharmaceuticals & Chemical Products\"},\"data\":[]}', '2026-05-23 05:52:10', '2026-05-23 05:52:10'),
(134, 'Vacuum Mixer', 'vacuum-mixer', 'Industrial Vacuum Mixer designed for bubble-free and homogeneous mixing of creams, lotions, and viscous machine_products under vacuum conditions.Machine is equipped with vacuum homogenizing system, stainless steel mixing vessel, and PLC touch screen control for hygienic industrial operation.', '/uploads/machines/vacuum-mixer-1779515933.jpg', 'Industrial Vacuum Mixer', '', 1, 21, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Vacuum Mixer\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 45 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"MixingCapacity\":\"10 Litre To 5000 Litre\",\"MixingType\":\"Vacuum Homogenizing Mixing\",\"MixerType\":\"Vacuum Emulsifying Mixer\",\"Material\":\"S.S. 304 \\/ 316\",\"VacuumSystem\":\"High Vacuum Pump System\",\"HeatingType\":\"Electric \\/ Steam Jacket Heating\",\"DriveType\":\"High Speed Homogenizer & Agitator System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"MixingEfficiency\":\"Bubble Free & Uniform Mixing\",\"ConstructionType\":\"Closed Vacuum Mixing Vessel\",\"Application\":\"Cream, Lotion, Ointment, Cosmetic, Pharmaceutical & Food Products\"},\"data\":[]}', '2026-05-23 05:53:50', '2026-05-23 05:58:53'),
(135, 'inline Mixer', 'inline-mixer', 'Industrial Inline Mixer designed for continuous and high-speed mixing of liquid and semi-liquid machine_products directly in processing pipelines.Machine is equipped with rotor stator mixing system, stainless steel construction, and PLC touch screen control for efficient industrial operation.', '/uploads/machines/inline-mixer-1779515676.jpg', 'Industrial Inline Mixer', '', 1, 21, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Inline Mixer\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"3 to 40 kW\",\"AutomationGrade\":\"Automatic\",\"MixingCapacity\":\"100 LPH To 20000 LPH\",\"MixingType\":\"Continuous Inline Mixing\",\"MixerType\":\"Rotor Stator Inline Mixer\",\"Material\":\"S.S. 304 \\/ 316\",\"DriveType\":\"High Speed Motor Driven System\",\"FlowType\":\"Continuous Flow Processing\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"MixingEfficiency\":\"Rapid Emulsification & Uniform Mixing\",\"InstallationType\":\"Pipeline Mounted System\",\"Application\":\"Beverages, Chemicals, Dairy, Pharmaceutical, Cosmetic & Food Products\"},\"data\":[]}', '2026-05-23 05:54:36', '2026-05-23 05:54:36'),
(136, 'Sigma Blade Mixer', 'sigma-blade-mixer', 'Industrial Sigma Blade Mixer designed for heavy-duty kneading and mixing of high viscosity materials and paste machine_products.Machine is equipped with double sigma blade system, robust gear motor drive, and stainless steel construction for continuous industrial operation.', '/uploads/machines/sigma-blade-mixer-1779515710.jpg', 'Industrial Sigma Blade Mixer', '', 1, 21, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Sigma Blade Mixer\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 60 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"MixingCapacity\":\"10Kg To 2000Kg\\/batch\",\"MixingType\":\"Heavy Duty Kneading & Mixing\",\"MixerType\":\"Double Sigma Blade Mixer\",\"Material\":\"S.S. 304 \\/ 316 \\/ MS Body\",\"DriveType\":\"Gear Motor Driven System\",\"DischargeType\":\"Hydraulic Tilting \\/ Bottom Discharge\",\"ControlSystem\":\"PLC Controlled \\/ Digital Control Panel\",\"MixingEfficiency\":\"Uniform Mixing Of High Viscosity Materials\",\"ConstructionType\":\"U Shape Mixing Trough\",\"Application\":\"Dough, Rubber, Adhesive, Putty, Pharmaceutical & Chemical Products\"},\"data\":[]}', '2026-05-23 05:55:10', '2026-05-23 05:55:10'),
(137, 'V-Blender', 'v-blender', 'Industrial V-Blender designed for uniform and gentle blending of dry powders and granule materials using tumbling mixing action.Machine is equipped with V shape rotating vessel, gear motor drive system, and stainless steel construction for hygienic industrial operation.', '/uploads/machines/v-blender-1779687773.jpg', 'Industrial V-Blender', '', 1, 21, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial V-Blender\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"2 to 20 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"MixingCapacity\":\"25Kg To 3000Kg\\/batch\",\"MixingType\":\"Tumbling Dry Powder Mixing\",\"BlenderType\":\"V Shape Rotating Blender\",\"Material\":\"S.S. 304 \\/ 316\",\"DischargeType\":\"Butterfly Valve \\/ Pneumatic Valve Discharge\",\"DriveType\":\"Gear Motor Driven Rotation System\",\"ControlSystem\":\"PLC Controlled \\/ Digital Control Panel\",\"MixingEfficiency\":\"Uniform & Gentle Powder Blending\",\"ConstructionType\":\"V Shape Twin Shell Vessel\",\"Application\":\"Pharmaceuticals, Chemicals, Food Powder, Granules & Cosmetic Products\"},\"data\":[]}', '2026-05-25 05:42:53', '2026-05-25 05:42:53'),
(138, 'Bin Blender', 'bin-blender', 'Industrial Bin Blender designed for dust-free and uniform blending of powders and granule materials in hygienic industrial environments.Machine is equipped with interchangeable stainless steel bins, hydraulic lifting system, and PLC touch screen control for efficient batch processing operation.', '/uploads/machines/bin-blender-1779687815.jpg', 'Industrial Bin Blender', '', 1, 21, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Bin Blender\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"3 to 25 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"MixingCapacity\":\"50Kg To 5000Kg\\/batch\",\"MixingType\":\"Bin Tumbling Mixing\",\"BlenderType\":\"Conta Bin Blender\",\"Material\":\"S.S. 304 \\/ 316\",\"BinType\":\"Interchangeable Stainless Steel Bin\",\"DriveType\":\"Gear Motor Driven Rotation System\",\"LiftingSystem\":\"Hydraulic \\/ Electric Bin Lifting\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"MixingEfficiency\":\"Dust Free & Uniform Powder Blending\",\"ConstructionType\":\"Closed Hygienic Blending System\",\"Application\":\"Pharmaceuticals, Food Powder, Chemicals, Nutraceutical & Cosmetic Products\"},\"data\":[]}', '2026-05-25 05:43:35', '2026-05-25 05:43:35'),
(139, 'High-Speed Disperser', 'high-speed-disperser', 'Industrial High-Speed Disperser designed for rapid dispersion and uniform mixing of liquid, paste, and high viscosity materials.Machine is equipped with high speed Cowles blade system, hydraulic lifting arrangement, and PLC or VFD based control for efficient industrial operation.', '/uploads/machines/high-speed-disperser-1779687863.jpg', 'Industrial High-Speed Disperser', '', 1, 21, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial High-Speed Disperser\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 75 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"MixingCapacity\":\"20 Litre To 10000 Litre\",\"MixingType\":\"High Speed Dispersion Mixing\",\"DisperserType\":\"Cowles Blade High-Speed Disperser\",\"Material\":\"S.S. 304 \\/ 316 \\/ MS Body\",\"DriveType\":\"High Speed Motor Driven System\",\"SpeedRange\":\"500 To 3000 RPM\",\"LiftingSystem\":\"Hydraulic \\/ Pneumatic Lifting\",\"ControlSystem\":\"PLC Controlled \\/ VFD Control Panel\",\"MixingEfficiency\":\"Rapid Dispersion & Homogeneous Mixing\",\"Application\":\"Paint, Ink, Chemicals, Adhesives, Cosmetic & Pharmaceutical Products\"},\"data\":[]}', '2026-05-25 05:44:23', '2026-05-25 05:44:23'),
(140, 'Vacuum Emulsifier Mixer', 'vacuum-emulsifier-mixer', 'Industrial Vacuum Emulsifier Mixer designed for bubble-free emulsification and homogeneous mixing of cream, lotion, and viscous machine_products under vacuum conditions.Machine is equipped with high speed homogenizer system, stainless steel vacuum vessel, and PLC touch screen control for hygienic industrial operation.', '/uploads/machines/vacuum-emulsifier-mixer-1779687903.jpg', 'Industrial Vacuum Emulsifier Mixer', '', 1, 21, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Vacuum Emulsifier Mixer\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"8 to 60 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"MixingCapacity\":\"20 Litre To 5000 Litre\",\"MixingType\":\"Vacuum Emulsifying & Homogenizing Mixing\",\"MixerType\":\"Vacuum Emulsifier Mixer\",\"Material\":\"S.S. 304 \\/ 316\",\"VacuumSystem\":\"High Vacuum Pump System\",\"HeatingType\":\"Electric \\/ Steam Jacket Heating\",\"DriveType\":\"High Speed Homogenizer & Agitator System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"MixingEfficiency\":\"Bubble Free Emulsification & Uniform Mixing\",\"ConstructionType\":\"Closed Hygienic Vacuum Mixing Vessel\",\"Application\":\"Cream, Lotion, Ointment, Cosmetic, Pharmaceutical & Food Products\"},\"data\":[]}', '2026-05-25 05:45:03', '2026-05-25 05:45:03'),
(141, 'Rotor-Stator Mixer', 'rotor-stator-mixer', 'Industrial Rotor-Stator Mixer designed for high shear emulsification and fine particle dispersion of liquid and semi-liquid machine_products.Machine is equipped with high speed rotor-stator system, stainless steel construction, and PLC or VFD based control for efficient industrial operation.', '/uploads/machines/rotor-stator-mixer-1779687939.jpg', 'Industrial Rotor-Stator Mixer', '', 1, 21, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Rotor-Stator Mixer\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"3 to 50 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"MixingCapacity\":\"10 Litre To 10000 Litre\",\"MixingType\":\"High Shear Rotor-Stator Mixing\",\"MixerType\":\"Rotor-Stator Homogenizer Mixer\",\"Material\":\"S.S. 304 \\/ 316\",\"DriveType\":\"High Speed Motor Driven System\",\"SpeedRange\":\"1000 To 3600 RPM\",\"ControlSystem\":\"PLC Controlled \\/ VFD Control Panel\",\"MixingEfficiency\":\"Rapid Emulsification & Fine Particle Dispersion\",\"ConstructionType\":\"Inline \\/ Batch Mixing System\",\"Application\":\"Cosmetics, Pharmaceuticals, Dairy, Chemicals & Food Products\"},\"data\":[]}', '2026-05-25 05:45:39', '2026-05-25 05:45:39'),
(142, 'Agitator', 'agitator', 'Industrial Agitator designed for continuous and uniform mixing of liquids, slurry, and semi-liquid machine_products in industrial processing systems.Machine is equipped with heavy duty motor drive, multiple blade options, and stainless steel construction for reliable industrial operation.', '/uploads/machines/agitator-1779687987.jpg', 'Industrial Agitator', '', 1, 20, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Agitator\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"PowerConsumption\":\"1 to 30 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"MixingCapacity\":\"50 Litre To 20000 Litre\",\"MixingType\":\"Liquid & Slurry Agitation\",\"AgitatorType\":\"Top Mount \\/ Side Mount Agitator\",\"Material\":\"S.S. 304 \\/ 316 \\/ MS Body\",\"DriveType\":\"Gear Motor Driven System\",\"SpeedRange\":\"50 To 1500 RPM\",\"BladeType\":\"Propeller \\/ Turbine \\/ Paddle Blade\",\"ControlSystem\":\"PLC Controlled \\/ VFD Control Panel\",\"MixingEfficiency\":\"Continuous Uniform Agitation\",\"Application\":\"Chemicals, Water Treatment, Food, Pharmaceutical & Industrial Liquid Products\"},\"data\":[]}', '2026-05-25 05:46:27', '2026-05-25 05:46:27'),
(143, 'Magnetic Stirrer', 'magnetic-stirrer', 'Industrial Magnetic Stirrer designed for uniform and controlled mixing of liquid samples in laboratory and industrial applications.Machine is equipped with magnetic drive system, digital speed control, and optional hot plate heating for precise mixing operation.', '/uploads/machines/magnetic-stirrer-1779688024.jpg', 'Industrial Magnetic Stirrer', '', 1, 20, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Magnetic Stirrer\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase\",\"PowerConsumption\":\"0.1 to 2 kW\",\"AutomationGrade\":\"Automatic\",\"MixingCapacity\":\"100ml To 50 Litre\",\"MixingType\":\"Magnetic Stirring\",\"StirrerType\":\"Hot Plate \\/ Non Heating Magnetic Stirrer\",\"Material\":\"S.S. 304 \\/ Powder Coated Body\",\"DriveType\":\"Magnetic Motor Driven System\",\"SpeedRange\":\"100 To 2000 RPM\",\"TemperatureRange\":\"Ambient To 350\\u00b0C\",\"ControlSystem\":\"Digital Speed & Temperature Controller\",\"MixingEfficiency\":\"Uniform & Bubble Free Mixing\",\"Application\":\"Laboratory, Chemical, Pharmaceutical, Food & Research Applications\"},\"data\":[]}', '2026-05-25 05:47:04', '2026-05-25 05:47:04'),
(144, 'Overhead Stirrer', 'overhead-stirrer', 'Industrial Overhead Stirrer designed for efficient mixing of low and high viscosity liquid machine_products in laboratory and industrial applications.Machine is equipped with motor driven stirring system, variable speed control, and multiple blade options for reliable mixing performance', '/uploads/machines/overhead-stirrer-1779688057.jpg', 'Industrial Overhead Stirrer', '', 1, 20, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Overhead Stirrer\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"PowerConsumption\":\"0.5 to 5 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"MixingCapacity\":\"1 Litre To 500 Litre\",\"MixingType\":\"Mechanical Overhead Stirring\",\"StirrerType\":\"Laboratory & Industrial Overhead Stirrer\",\"Material\":\"S.S. 304 \\/ Powder Coated Body\",\"DriveType\":\"Motor Driven Stirring System\",\"SpeedRange\":\"50 To 3000 RPM\",\"BladeType\":\"Propeller \\/ Paddle \\/ Turbine Blade\",\"ControlSystem\":\"Digital Speed Controller\",\"MixingEfficiency\":\"Uniform Mixing Of Low & High Viscosity Liquids\",\"Application\":\"Chemical, Pharmaceutical, Laboratory, Cosmetic & Food Applications\"},\"data\":[]}', '2026-05-25 05:47:37', '2026-05-25 05:47:37'),
(145, 'Batch Reactor', 'batch-reactor', 'Industrial Batch Reactor designed for controlled chemical reaction, mixing, heating, and cooling processes in industrial production systems.Machine is equipped with jacketed reactor vessel, agitator system, and PLC touch screen control for efficient batch processing operation.', '/uploads/machines/batch-reactor-1779688244.jpg', 'Industrial Batch Reactor', '', 1, 22, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Batch Reactor\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 80 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"ReactorCapacity\":\"50 Litre To 20000 Litre\",\"ProcessingType\":\"Batch Chemical & Liquid Processing\",\"ReactorType\":\"Jacketed Batch Reactor\",\"Material\":\"S.S. 304 \\/ 316 \\/ Glass Lined Steel\",\"HeatingType\":\"Steam \\/ Thermic Fluid \\/ Electric Heating\",\"CoolingType\":\"Water \\/ Chilled Water Cooling Jacket\",\"AgitationSystem\":\"Motor Driven Agitator System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"PressureRange\":\"Vacuum To High Pressure Operation\",\"Application\":\"Chemicals, Pharmaceuticals, Resin, Adhesives, Cosmetic & Food Products\"},\"data\":[]}', '2026-05-25 05:48:18', '2026-05-25 05:50:44'),
(146, 'Continuous Stirred Tank Reactor (CSTR)', 'continuous-stirred-tank-reactor-cstr', 'Continuous Stirred Tank Reactor (CSTR) designed for continuous mixing and chemical processing with controlled reaction conditions.Machine is equipped with continuous agitation system, jacketed reactor vessel, and PLC touch screen control for efficient industrial operation.', '/uploads/machines/continuous-stirred-tank-reactor-cstr-1779688148.jpg', 'Continuous Stirred Tank Reactor (CSTR)', '', 1, 22, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Continuous Stirred Tank Reactor (CSTR)\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 100 kW\",\"AutomationGrade\":\"Automatic\",\"ReactorCapacity\":\"100 Litre To 50000 Litre\",\"ProcessingType\":\"Continuous Chemical Processing\",\"ReactorType\":\"Continuous Stirred Tank Reactor\",\"Material\":\"S.S. 304 \\/ 316 \\/ Glass Lined Steel\",\"HeatingType\":\"Steam \\/ Thermic Fluid \\/ Electric Heating\",\"CoolingType\":\"Water \\/ Chilled Water Cooling Jacket\",\"AgitationSystem\":\"Continuous Motor Driven Agitator\",\"FlowType\":\"Continuous Feed & Discharge System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"PressureRange\":\"Atmospheric \\/ Vacuum \\/ Pressurized Operation\",\"Application\":\"Chemicals, Pharmaceuticals, Petrochemicals, Food & Industrial Liquid Processing\"},\"data\":[]}', '2026-05-25 05:49:08', '2026-05-25 05:49:08'),
(147, 'Plug Flow Reactor (PFR)', 'plug-flow-reactor-pfr', 'Plug Flow Reactor (PFR) designed for continuous chemical reaction processing with high conversion efficiency and controlled flow characteristics.Machine is equipped with tubular reactor system, heating and cooling arrangement, and PLC touch screen control for reliable industrial operation.', '/uploads/machines/plug-flow-reactor-pfr-1779771347.jpg', 'Plug Flow Reactor (PFR)', '', 1, 22, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Plug Flow Reactor (PFR)\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 80 kW\",\"AutomationGrade\":\"Automatic\",\"ReactorCapacity\":\"100 Litre To 50000 Litre\",\"ProcessingType\":\"Continuous Flow Chemical Processing\",\"ReactorType\":\"Tubular Plug Flow Reactor\",\"Material\":\"S.S. 304 \\/ 316 \\/ Alloy Steel\",\"HeatingType\":\"Steam \\/ Electric \\/ Thermic Fluid Heating\",\"CoolingType\":\"Water \\/ Chilled Water Cooling System\",\"FlowSystem\":\"Continuous Plug Flow Operation\",\"PressureRange\":\"Atmospheric \\/ High Pressure Operation\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"ReactionEfficiency\":\"High Conversion Continuous Reaction Processing\",\"Application\":\"Petrochemicals, Chemicals, Pharmaceuticals, Polymer & Industrial Processing\"},\"data\":[]}', '2026-05-26 04:55:47', '2026-05-26 04:55:47'),
(148, 'Jacketed Reactor', 'jacketed-reactor', 'Industrial Jacketed Reactor designed for controlled heating, cooling, mixing, and chemical reaction processing in industrial applications.Machine is equipped with double wall jacketed vessel, agitator system, and PLC touch screen control for efficient batch processing operation.', '/uploads/machines/jacketed-reactor-1779771384.jpg', 'Industrial Jacketed Reactor', '', 1, 22, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Jacketed Reactor\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 75 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"ReactorCapacity\":\"50 Litre To 20000 Litre\",\"ProcessingType\":\"Heating, Cooling & Chemical Reaction Processing\",\"ReactorType\":\"Jacketed Mixing Reactor\",\"Material\":\"S.S. 304 \\/ 316 \\/ Glass Lined Steel\",\"HeatingType\":\"Steam \\/ Thermic Fluid \\/ Electric Heating\",\"CoolingType\":\"Water \\/ Chilled Water Cooling Jacket\",\"AgitationSystem\":\"Motor Driven Agitator System\",\"PressureRange\":\"Vacuum To Pressurized Operation\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"ConstructionType\":\"Double Wall Jacketed Vessel\",\"Application\":\"Chemicals, Pharmaceuticals, Cosmetic, Resin & Food Products\"},\"data\":[]}', '2026-05-26 04:56:24', '2026-05-26 04:56:24'),
(149, 'Glass-Lined Reactor', 'glass-lined-reactor', 'Industrial Glass-Lined Reactor designed for corrosion resistant chemical processing and controlled reaction applications.Machine is equipped with glass coated reactor vessel, agitation system, and PLC touch screen control for safe and efficient industrial operation.', '/uploads/machines/glass-lined-reactor-1779771432.jpg', 'Industrial Glass-Lined Reactor', '', 1, 22, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Glass-Lined Reactor\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 80 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"ReactorCapacity\":\"50 Litre To 30000 Litre\",\"ProcessingType\":\"Chemical Reaction & Corrosion Resistant Processing\",\"ReactorType\":\"Glass-Lined Jacketed Reactor\",\"Material\":\"Glass Lined Steel\",\"HeatingType\":\"Steam \\/ Thermic Fluid \\/ Electric Heating\",\"CoolingType\":\"Water \\/ Chilled Water Cooling Jacket\",\"AgitationSystem\":\"Motor Driven Agitator System\",\"PressureRange\":\"Vacuum To High Pressure Operation\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"ConstructionType\":\"Corrosion Resistant Glass Coated Vessel\",\"Application\":\"Chemical, Pharmaceutical, Acid, Solvent & Corrosive Product Processing\"},\"data\":[]}', '2026-05-26 04:57:12', '2026-05-26 04:57:12'),
(150, 'Pressure Reactor', 'pressure-reactor', 'Industrial Pressure Reactor designed for high pressure chemical reaction and industrial processing applications.Machine is equipped with pressurized jacketed vessel, heavy duty agitation system, and PLC touch screen control for safe and efficient operation.', '/uploads/machines/pressure-reactor-1779771542.jpg', 'Industrial Pressure Reactor', '', 1, 22, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Pressure Reactor\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 100 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"ReactorCapacity\":\"25 Litre To 20000 Litre\",\"ProcessingType\":\"High Pressure Chemical Reaction Processing\",\"ReactorType\":\"Pressurized Jacketed Reactor\",\"Material\":\"S.S. 304 \\/ 316 \\/ Alloy Steel\",\"HeatingType\":\"Steam \\/ Thermic Fluid \\/ Electric Heating\",\"CoolingType\":\"Water \\/ Chilled Water Cooling Jacket\",\"PressureRange\":\"1 Bar To 100 Bar\",\"AgitationSystem\":\"Heavy Duty Motor Driven Agitator\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"SafetyFeatures\":\"Pressure Relief Valve & Safety Interlocks\",\"Application\":\"Chemical, Petrochemical, Pharmaceutical & Industrial Processing\"},\"data\":[]}', '2026-05-26 04:59:02', '2026-05-26 04:59:02'),
(151, 'Hydrogenation Reactor', 'hydrogenation-reactor', 'Industrial Hydrogenation Reactor designed for controlled hydrogenation reactions under high pressure and temperature conditions.Machine is equipped with high pressure reactor vessel, gas dispersion agitation system, and PLC touch screen control for safe and efficient industrial operation.', '/uploads/machines/hydrogenation-reactor-1779771582.jpg', 'Industrial Hydrogenation Reactor', '', 1, 22, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Hydrogenation Reactor\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"10 to 120 kW\",\"AutomationGrade\":\"Automatic\",\"ReactorCapacity\":\"50 Litre To 25000 Litre\",\"ProcessingType\":\"Hydrogenation Chemical Reaction Processing\",\"ReactorType\":\"High Pressure Hydrogenation Reactor\",\"Material\":\"S.S. 316 \\/ Alloy Steel\",\"HeatingType\":\"Steam \\/ Thermic Fluid \\/ Electric Heating\",\"CoolingType\":\"Water \\/ Chilled Water Cooling Jacket\",\"PressureRange\":\"5 Bar To 150 Bar\",\"AgitationSystem\":\"High Efficiency Gas Dispersion Agitator\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"SafetyFeatures\":\"Pressure Relief System, Gas Safety Interlocks & Explosion Proof Design\",\"Application\":\"Edible Oil, Chemicals, Pharmaceuticals, Petrochemicals & Specialty Chemical Processing\"},\"data\":[]}', '2026-05-26 04:59:42', '2026-05-26 04:59:42'),
(152, 'Crystallizer', 'crystallizer', 'Industrial Crystallizer designed for controlled crystal formation and separation in chemical and industrial processing applications.Machine is equipped with heating and cooling system, agitator arrangement, and PLC touch screen control for efficient crystallization operation.', '/uploads/machines/crystallizer-1779771634.jpg', 'Industrial Crystallizer', '', 1, 22, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Crystallizer\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 60 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"ProcessingCapacity\":\"50 Litre To 20000 Litre\",\"ProcessingType\":\"Crystal Formation & Separation Processing\",\"CrystallizerType\":\"Cooling \\/ Evaporative Crystallizer\",\"Material\":\"S.S. 304 \\/ 316 \\/ Alloy Steel\",\"HeatingType\":\"Steam \\/ Electric Heating\",\"CoolingType\":\"Water \\/ Chilled Water Cooling System\",\"AgitationSystem\":\"Motor Driven Agitator System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"OperationType\":\"Batch \\/ Continuous Processing\",\"Application\":\"Chemicals, Pharmaceuticals, Sugar, Salt & Food Processing Industries\"},\"data\":[]}', '2026-05-26 05:00:34', '2026-05-26 05:00:34'),
(153, 'Fermentation Reactor', 'fermentation-reactor', 'Industrial Fermentation Reactor designed for controlled biological and microbial fermentation processing in industrial applications.Machine is equipped with sterile agitation system, aeration arrangement, and PLC touch screen control for efficient fermentation operation.', '/uploads/machines/fermentation-reactor-1779771670.jpg', 'Industrial Fermentation Reactor', '', 1, 22, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Fermentation Reactor\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 80 kW\",\"AutomationGrade\":\"Automatic\",\"ReactorCapacity\":\"50 Litre To 50000 Litre\",\"ProcessingType\":\"Biological & Fermentation Processing\",\"ReactorType\":\"Stirred Fermentation Bioreactor\",\"Material\":\"S.S. 304 \\/ 316\",\"HeatingType\":\"Steam \\/ Electric Heating\",\"CoolingType\":\"Water \\/ Chilled Water Cooling Jacket\",\"AgitationSystem\":\"Sterile Motor Driven Agitator\",\"AerationSystem\":\"Air Sparger & Oxygen Supply System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"SterilizationType\":\"CIP \\/ SIP Sterilization System\",\"Application\":\"Biotechnology, Pharmaceuticals, Enzymes, Food & Beverage Processing\"},\"data\":[]}', '2026-05-26 05:01:10', '2026-05-26 05:01:10'),
(154, 'Jet Mill', 'jet-mill', 'Industrial Jet Mill designed for ultra fine micronizing and contamination-free grinding of powders using high velocity air jet technology.Machine is equipped with fluid energy grinding system, stainless steel construction, and PLC based control panel for efficient industrial operation', '/uploads/machines/jet-mill-1779771709.jpg', 'Industrial Jet Mill', '', 1, 13, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Jet Mill\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"10 to 150 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"GrindingCapacity\":\"5Kg To 5000Kg\\/hour\",\"GrindingType\":\"Micronizing Air Jet Grinding\",\"MillType\":\"Fluid Energy Jet Mill\",\"Material\":\"S.S. 304 \\/ 316\",\"OperatingPressure\":\"Compressed Air \\/ Nitrogen Based Grinding\",\"ParticleSize\":\"1 To 30 Micron\",\"ControlSystem\":\"PLC Controlled With Digital Control Panel\",\"GrindingEfficiency\":\"Ultra Fine & Contamination Free Grinding\",\"CoolingSystem\":\"Low Temperature Grinding Process\",\"Application\":\"Pharmaceuticals, Chemicals, Minerals, Pigments & Food Powder Products\"},\"data\":[]}', '2026-05-26 05:01:49', '2026-05-26 05:01:49'),
(155, 'Air Classifier Mill (ACM)', 'air-classifier-mill-acm', 'Industrial Air Classifier Mill (ACM) designed for fine and controlled grinding of powders with integrated air classification technology.Machine is equipped with high speed impact grinding system, dynamic air classifier, and PLC based control panel for efficient industrial operation.', '/uploads/machines/air-classifier-mill-acm-1779771740.jpg', 'Industrial Air Classifier Mill (ACM)', '', 1, 13, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Air Classifier Mill (ACM)\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"10 to 120 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"GrindingCapacity\":\"10Kg To 4000Kg\\/hour\",\"GrindingType\":\"Impact Grinding With Air Classification\",\"MillType\":\"Air Classifier Mill\",\"Material\":\"S.S. 304 \\/ 316\",\"ParticleSize\":\"20 To 150 Micron\",\"ClassifierSystem\":\"Integrated Dynamic Air Classifier\",\"DriveType\":\"High Speed Motor Driven System\",\"ControlSystem\":\"PLC Controlled With Digital Control Panel\",\"GrindingEfficiency\":\"Fine & Uniform Particle Size Grinding\",\"DustControl\":\"Closed Circuit Dust Free Grinding System\",\"Application\":\"Pharmaceuticals, Chemicals, Food Powder, Minerals & Cosmetic Products\"},\"data\":[]}', '2026-05-26 05:02:20', '2026-05-26 05:02:20'),
(156, 'Pin Mill', 'pin-mill', 'Industrial Pin Mill designed for high-speed fine grinding and pulverizing of powders and granule materials.\r\nMachine is equipped with pin disc grinding system, high speed rotor mechanism, and stainless steel construction for efficient industrial operation.', '/uploads/machines/pin-mill-1779773593.jpg', 'Industrial Pin Mill', '', 1, 13, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Pin Mill\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 75 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"GrindingCapacity\":\"10Kg To 3000Kg\\/hour\",\"GrindingType\":\"High Speed Impact Grinding\",\"MillType\":\"Pin Disc Grinding Mill\",\"Material\":\"S.S. 304 \\/ 316\",\"ParticleSize\":\"20 To 200 Micron\",\"DriveType\":\"High Speed Motor Driven System\",\"RotorSpeed\":\"3000 To 12000 RPM\",\"ControlSystem\":\"PLC Controlled \\/ Digital Control Panel\",\"GrindingEfficiency\":\"Fine & Uniform Powder Grinding\",\"CoolingSystem\":\"Optional Water Cooling Jacket\",\"Application\":\"Spices, Sugar, Chemicals, Food Powder & Pharmaceutical Products\"},\"data\":[]}', '2026-05-26 05:33:13', '2026-05-26 05:33:13'),
(157, 'Pulverizer', 'pulverizer', 'Industrial Pulverizer designed for efficient grinding and pulverizing of dry materials into fine powder form.\r\nMachine is equipped with high speed grinding system, cyclone separator, and dust collection arrangement for continuous industrial operation.', '/uploads/machines/pulverizer-1779797384.jpg', 'Industrial Pulverizer', '', 1, 13, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Pulverizer\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"3 to 100 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"GrindingCapacity\":\"10Kg To 5000Kg\\/hour\",\"GrindingType\":\"Impact & Hammer Grinding\",\"MillType\":\"Pulverizer Grinding Machine\",\"Material\":\"S.S. 304 \\/ 316 \\/ MS Body\",\"ParticleSize\":\"20 To 500 Micron\",\"DriveType\":\"High Speed Motor Driven System\",\"RotorSpeed\":\"2000 To 10000 RPM\",\"ControlSystem\":\"PLC Controlled \\/ Digital Control Panel\",\"GrindingEfficiency\":\"Fine & Uniform Powder Grinding\",\"DustControl\":\"Cyclone Separator & Dust Collector System\",\"Application\":\"Spices, Grains, Chemicals, Food Powder & Pharmaceutical Products\"},\"data\":[]}', '2026-05-26 12:09:44', '2026-05-26 12:09:44'),
(158, 'High-Shear Granulator', 'high-shear-granulator', 'Industrial High-Shear Granulator designed for rapid and uniform wet granulation of powders in industrial processing applications.Machine is equipped with impeller and chopper blade system, stainless steel construction, and PLC touch screen control for efficient granulation operation', '/uploads/machines/high-shear-granulator-1779797487.jpg', 'Industrial High-Shear Granulator', '', 1, 13, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial High-Shear Granulator\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 60 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"GranulationCapacity\":\"10Kg To 1000Kg\\/batch\",\"GranulationType\":\"High Shear Wet Granulation\",\"MachineType\":\"Rapid Mixer Granulator\",\"Material\":\"S.S. 304 \\/ 316\",\"MixingSystem\":\"Impeller & Chopper Blade System\",\"DriveType\":\"High Speed Motor Driven System\",\"SpeedRange\":\"Variable Speed Control\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"GranulationEfficiency\":\"Uniform & Fast Granule Formation\",\"DischargeType\":\"Pneumatic \\/ Manual Discharge\",\"Application\":\"Pharmaceuticals, Chemicals, Food Powder & Nutraceutical Products\"},\"data\":[]}', '2026-05-26 12:11:27', '2026-05-26 12:11:27'),
(159, 'Fluid Bed Granulator', 'fluid-bed-granulator', 'Industrial Fluid Bed Granulator designed for efficient mixing, granulation, and drying of powder materials in a single processing system.Machine is equipped with fluidized hot air system, stainless steel processing chamber, and PLC touch screen control for hygienic industrial operation.', '/uploads/machines/fluid-bed-granulator-1779797566.jpg', 'Industrial Fluid Bed Granulator', '', 1, 13, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Fluid Bed Granulator\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"8 to 75 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"GranulationCapacity\":\"5Kg To 1000Kg\\/batch\",\"GranulationType\":\"Fluidized Bed Granulation & Drying\",\"MachineType\":\"Fluid Bed Processor\",\"Material\":\"S.S. 304 \\/ 316\",\"AirFlowSystem\":\"Hot Air Fluidization System\",\"HeatingType\":\"Electric \\/ Steam Heating\",\"TemperatureRange\":\"40\\u00b0C To 120\\u00b0C\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"ProcessingFunction\":\"Mixing, Granulation & Drying\",\"FilterSystem\":\"Finger Bag \\/ Cartridge Filter System\",\"Application\":\"Pharmaceuticals, Chemicals, Food Powder & Nutraceutical Products\"},\"data\":[]}', '2026-05-26 12:12:46', '2026-05-26 12:12:46'),
(160, 'Extrusion-Spheronization Unit', 'extrusion-spheronization-unit', 'Industrial Extrusion-Spheronization Unit designed for continuous production of uniform spherical pellets and granules in industrial processing applications.Machine is equipped with extrusion mechanism, high speed spheronizer system, and PLC touch screen control for precise pellet formation operation.', '/uploads/machines/extrusion-spheronization-unit-1779878523.jpg', 'Industrial Extrusion-Spheronization Unit', '', 1, 13, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Extrusion-Spheronization Unit\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 50 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"ProductionCapacity\":\"5Kg To 500Kg\\/hour\",\"ProcessingType\":\"Extrusion & Pellet Spheronization\",\"MachineType\":\"Extruder With Spheronizer System\",\"Material\":\"S.S. 304 \\/ 316\",\"ExtrusionSystem\":\"Screw \\/ Radial Extrusion Mechanism\",\"SpheronizationSystem\":\"High Speed Friction Plate Spheronizer\",\"DriveType\":\"Variable Speed Motor Driven System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"PelletFormation\":\"Uniform Round Pellet Production\",\"Application\":\"Pharmaceuticals, Chemicals, Catalyst & Nutraceutical Pellet Processing\"},\"data\":[]}', '2026-05-27 10:42:03', '2026-05-27 10:42:03'),
(161, 'Oscillating Granulator', 'oscillating-granulator', 'Industrial Oscillating Granulator designed for efficient dry and wet granulation of powder materials into uniform granules.Machine is equipped with oscillating rotor mechanism, interchangeable mesh screen system, and stainless steel construction for hygienic industrial operation.', '/uploads/machines/oscillating-granulator-1779878556.jpg', 'Industrial Oscillating Granulator', '', 1, 13, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Oscillating Granulator\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"2 to 20 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"GranulationCapacity\":\"5Kg To 500Kg\\/hour\",\"GranulationType\":\"Dry & Wet Granulation\",\"MachineType\":\"Oscillating Granulator\",\"Material\":\"S.S. 304 \\/ 316\",\"ScreenType\":\"Interchangeable Mesh Screen\",\"DriveType\":\"Gear Motor Driven Oscillating Rotor\",\"RotorSpeed\":\"Variable Speed Control\",\"ControlSystem\":\"PLC Controlled \\/ Digital Control Panel\",\"GranulationEfficiency\":\"Uniform Granule Size Formation\",\"ConstructionType\":\"Compact Hygienic Design\",\"Application\":\"Pharmaceuticals, Chemicals, Food Powder & Nutraceutical Products\"},\"data\":[]}', '2026-05-27 10:42:36', '2026-05-27 10:42:36'),
(162, 'Filtration System', 'filtration-system', 'Industrial Filtration System designed for efficient removal of particles, impurities, and contaminants from liquids and slurry materials.Machine is equipped with advanced filter media system, pump based circulation arrangement, and PLC control panel for reliable industrial operation', '/uploads/machines/filtration-system-1779878593.jpg', 'Industrial Filtration System', '', 1, 13, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Filtration System\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"PowerConsumption\":\"1 to 25 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"FiltrationCapacity\":\"100 LPH To 50000 LPH\",\"FiltrationType\":\"Liquid & Slurry Filtration\",\"SystemType\":\"Pressure \\/ Vacuum Filtration System\",\"Material\":\"S.S. 304 \\/ 316 \\/ FRP\",\"FilterMedia\":\"Cartridge \\/ Bag \\/ Membrane \\/ Filter Cloth\",\"OperatingPressure\":\"1 Bar To 10 Bar\",\"DriveType\":\"Pump Based Filtration System\",\"ControlSystem\":\"PLC Controlled \\/ Digital Control Panel\",\"FiltrationEfficiency\":\"Fine Particle & Impurity Removal\",\"Application\":\"Water Treatment, Chemicals, Pharmaceuticals, Food & Beverage Processing\"},\"data\":[]}', '2026-05-27 10:43:13', '2026-05-27 10:43:13'),
(163, 'Centrifuge', 'centrifuge', 'Industrial Centrifuge designed for high-speed solid-liquid separation and clarification in industrial processing applications.Machine is equipped with high speed rotating system, stainless steel construction, and PLC touch screen control for efficient separation operation.', '/uploads/machines/centrifuge-1779878626.jpg', 'Industrial Centrifuge', '', 1, 13, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Centrifuge\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"3 to 75 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"ProcessingCapacity\":\"10 Litre To 20000 Litre\\/hour\",\"SeparationType\":\"Solid-Liquid Separation\",\"CentrifugeType\":\"Basket \\/ Decanter \\/ Tubular Centrifuge\",\"Material\":\"S.S. 304 \\/ 316\",\"DriveType\":\"High Speed Motor Driven System\",\"SpeedRange\":\"1000 To 15000 RPM\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"DischargeType\":\"Manual \\/ Automatic Discharge\",\"SeparationEfficiency\":\"High Speed Efficient Separation\",\"Application\":\"Chemicals, Pharmaceuticals, Food Processing, Dairy & Wastewater Treatment\"},\"data\":[]}', '2026-05-27 10:43:46', '2026-05-27 10:43:46'),
