(165, 'Rotary Vacuum Dryer', 'rotary-vacuum-dryer', 'Industrial Rotary Vacuum Dryer designed for low temperature and uniform drying of powders, granules, and heat sensitive materials under vacuum conditions.Machine is equipped with rotary cone vessel, vacuum system, and PLC touch screen control for efficient industrial drying operation.', '/uploads/machines/rotary-vacuum-dryer-1779878688.jpg', 'Industrial Rotary Vacuum Dryer', '', 1, 13, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Rotary Vacuum Dryer\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 50 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"DryingCapacity\":\"25Kg To 5000Kg\\/batch\",\"DryingMethod\":\"Rotary Vacuum Drying\",\"DryerType\":\"Rotary Cone Vacuum Dryer\",\"Material\":\"S.S. 304 \\/ 316\",\"HeatingType\":\"Steam \\/ Electric \\/ Thermic Fluid Heating\",\"VacuumSystem\":\"High Vacuum Pump System\",\"RotationSystem\":\"Gear Motor Driven Rotary System\",\"TemperatureRange\":\"40\\u00b0C To 200\\u00b0C\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"DryingEfficiency\":\"Uniform Low Temperature Moisture Removal\",\"Application\":\"Pharmaceuticals, Chemicals, Food Products & Heat Sensitive Materials\"},\"data\":[]}', '2026-05-27 10:44:48', '2026-05-27 10:44:48'),
(166, 'Distillation Unit', 'distillation-unit', 'Industrial Distillation Unit designed for efficient separation, purification, and recovery of liquid components in industrial processing applications.Machine is equipped with distillation column, heating and condensation system, and PLC touch screen control for reliable industrial operation.', '/uploads/machines/distillation-unit-1779878715.jpg', 'Industrial Distillation Unit', '', 1, 13, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Distillation Unit\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 100 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"ProcessingCapacity\":\"50 Litre To 50000 Litre\\/day\",\"ProcessingType\":\"Liquid Separation & Purification\",\"DistillationType\":\"Batch \\/ Continuous Distillation\",\"Material\":\"S.S. 304 \\/ 316 \\/ Glass Lined Steel\",\"HeatingType\":\"Steam \\/ Electric \\/ Thermic Fluid Heating\",\"CoolingType\":\"Water \\/ Chilled Water Condensation System\",\"ColumnType\":\"Packed \\/ Tray Distillation Column\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"SeparationEfficiency\":\"High Purity Liquid Recovery\",\"Application\":\"Chemicals, Solvents, Essential Oils, Pharmaceuticals & Food Processing\"},\"data\":[]}', '2026-05-27 10:45:15', '2026-05-27 10:45:15'),
(167, 'Evaporator', 'evaporator', 'Industrial Evaporator designed for efficient concentration, moisture removal, and solvent evaporation in industrial processing applications.Machine is equipped with advanced heating and condensation system, stainless steel construction, and PLC touch screen control for reliable operation.', '/uploads/machines/evaporator-1779878742.jpg', 'Industrial Evaporator', '', 1, 13, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Evaporator\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 120 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"ProcessingCapacity\":\"100 Litre To 100000 Litre\\/day\",\"ProcessingType\":\"Liquid Concentration & Solvent Evaporation\",\"EvaporatorType\":\"Single Effect \\/ Multiple Effect Evaporator\",\"Material\":\"S.S. 304 \\/ 316 \\/ Alloy Steel\",\"HeatingType\":\"Steam \\/ Electric Heating\",\"CoolingType\":\"Water \\/ Chilled Water Condensation System\",\"OperatingPressure\":\"Atmospheric \\/ Vacuum Operation\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"EvaporationEfficiency\":\"High Efficiency Moisture & Solvent Removal\",\"Application\":\"Chemicals, Pharmaceuticals, Food Processing, Dairy & Wastewater Treatment\"},\"data\":[]}', '2026-05-27 10:45:42', '2026-05-27 10:45:42'),
(168, 'Rotary Tablet Press', 'rotary-tablet-press', 'Industrial Rotary Tablet Press designed for high-speed and precise tablet compression in pharmaceutical and industrial production applications.Machine is equipped with multi station rotary turret system, stainless steel construction, and PLC touch screen control for continuous industrial operation.', '/uploads/machines/rotary-tablet-press-1779879016.jpg', 'Industrial Rotary Tablet Press', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Rotary Tablet Press\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"2 to 15 kW\",\"AutomationGrade\":\"Automatic\",\"ProductionCapacity\":\"10000 To 500000 Tablets\\/hour\",\"CompressionType\":\"Rotary Tablet Compression\",\"MachineType\":\"Multi Station Rotary Tablet Press\",\"Material\":\"S.S. 304 \\/ 316\",\"TurretStations\":\"16 To 75 Stations\",\"TabletShape\":\"Round \\/ Oval \\/ Customized Shape\",\"CompressionForce\":\"High Precision Compression System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"DriveType\":\"Servo \\/ Motor Driven System\",\"Application\":\"Pharmaceuticals, Nutraceuticals, Chemicals & Food Tablet Products\"},\"data\":[]}', '2026-05-27 10:46:11', '2026-05-27 10:50:16'),
(169, 'Single Punch Tablet Press', 'single-punch-tablet-press', 'Single Punch Tablet Press designed for precise and economical tablet compression in small-scale and laboratory production applications.Machine is equipped with single station compression system, adjustable pressure control, and robust construction for reliable operation.', '/uploads/machines/single-punch-tablet-press-1779878801.jpg', 'Single Punch Tablet Press', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Single Punch Tablet Press\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase\",\"PowerConsumption\":\"0.5 to 3 kW\",\"AutomationGrade\":\"Semi Automatic \\/ Automatic\",\"ProductionCapacity\":\"2000 To 6000 Tablets\\/hour\",\"CompressionType\":\"Single Punch Tablet Compression\",\"MachineType\":\"Single Station Tablet Press\",\"Material\":\"S.S. 304 \\/ Cast Iron Body\",\"TabletShape\":\"Round \\/ Oval \\/ Customized Shape\",\"TabletDiameter\":\"Up To 25 mm\",\"CompressionForce\":\"Adjustable Compression System\",\"ControlSystem\":\"Digital \\/ Manual Control Panel\",\"DriveType\":\"Motor Driven Flywheel System\",\"Application\":\"Pharmaceuticals, Nutraceuticals, Herbal & Laboratory Tablet Production\"},\"data\":[]}', '2026-05-27 10:46:41', '2026-05-27 10:46:41');
INSERT INTO `machine_machines` (`id`, `machine_name`, `slug`, `description`, `image_url`, `meta_title`, `meta_description`, `category_id`, `subcategory_id`, `specifications`, `created_at`, `updated_at`) VALUES
(170, 'Multi-Layer Tablet Press', 'multi-layer-tablet-press', 'Industrial Multi-Layer Tablet Press designed for high-speed production of double layer and triple layer tablets with precise compression control.Machine is equipped with multi-layer rotary compression system, independent layer control, and PLC touch screen interface for continuous industrial operation.', '/uploads/machines/multi-layer-tablet-press-1779943741.jpg', 'Industrial Multi-Layer Tablet Press', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Multi-Layer Tablet Press\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 25 kW\",\"AutomationGrade\":\"Automatic\",\"ProductionCapacity\":\"20000 To 400000 Tablets\\/hour\",\"CompressionType\":\"Multi-Layer Rotary Tablet Compression\",\"MachineType\":\"Double \\/ Triple Layer Tablet Press\",\"Material\":\"S.S. 304 \\/ 316\",\"TurretStations\":\"20 To 75 Stations\",\"TabletShape\":\"Round \\/ Oval \\/ Customized Shape\",\"LayerControl\":\"Independent Layer Weight & Compression Control\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"DriveType\":\"Servo \\/ Motor Driven System\",\"Application\":\"Pharmaceuticals, Nutraceuticals, Effervescent & Bilayer Tablet Products\"},\"data\":[]}', '2026-05-28 04:49:01', '2026-05-28 04:49:01'),
(171, 'Tablet Coating Machine', 'tablet-coating-machine', 'Industrial Tablet Coating Machine designed for uniform film and sugar coating of tablets in pharmaceutical and industrial production applications.Machine is equipped with perforated coating pan, automatic spray system, and PLC touch screen control for efficient coating operation.', '/uploads/machines/tablet-coating-machine-1779943784.jpg', 'Industrial Tablet Coating Machine', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Tablet Coating Machine\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"3 to 30 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"CoatingCapacity\":\"5Kg To 1000Kg\\/batch\",\"CoatingType\":\"Film \\/ Sugar Tablet Coating\",\"MachineType\":\"Perforated Pan Coating Machine\",\"Material\":\"S.S. 304 \\/ 316\",\"HeatingSystem\":\"Hot Air Blower System\",\"SpraySystem\":\"Automatic Spray Gun Coating System\",\"PanSpeed\":\"Variable Speed Pan Rotation\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"DryingSystem\":\"Integrated Hot Air Drying System\",\"Application\":\"Pharmaceuticals, Nutraceuticals, Herbal & Food Tablet Products\"},\"data\":[]}', '2026-05-28 04:49:44', '2026-05-28 04:49:44'),
(172, 'Tablet Deduster', 'tablet-deduster', 'Industrial Tablet Deduster designed for efficient removal of excess powder and dust from tablets during production process.Machine is equipped with vibratory dedusting system, stainless steel construction, and integrated dust extraction arrangement for hygienic industrial operation.', '/uploads/machines/tablet-deduster-1779943815.jpg', 'Industrial Tablet Deduster', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Tablet Deduster\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase\",\"PowerConsumption\":\"0.5 to 2 kW\",\"AutomationGrade\":\"Automatic\",\"ProcessingCapacity\":\"100000 To 1000000 Tablets\\/hour\",\"DedustingType\":\"Vibration Based Tablet Dedusting\",\"MachineType\":\"Spiral \\/ Elevating Tablet Deduster\",\"Material\":\"S.S. 304 \\/ 316\",\"OperationSystem\":\"Continuous Tablet Conveying & Dedusting\",\"DriveType\":\"Vibratory Motor Driven System\",\"DustRemoval\":\"Integrated Dust Extraction Port\",\"ControlSystem\":\"Digital Control Panel\",\"InstallationType\":\"Inline Tablet Production Integration\",\"Application\":\"Pharmaceuticals, Nutraceuticals & Tablet Manufacturing Industries\"},\"data\":[]}', '2026-05-28 04:50:15', '2026-05-28 04:50:15'),
(173, 'Tablet Counting Machine', 'tablet-counting-machine', 'Automatic Tablet Counting Machine designed for accurate and high-speed counting of tablets and capsules in bottle packaging applications.Machine is equipped with electronic sensor counting system, vibratory feeding arrangement, and PLC touch screen control for efficient industrial operation.', '/uploads/machines/tablet-counting-machine-1779943875.jpg', 'Automatic Tablet Counting Machine', '', 1, 13, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Tablet Counting Machine\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase\",\"PowerConsumption\":\"1 to 5 kW\",\"AutomationGrade\":\"Automatic\",\"CountingCapacity\":\"500 To 5000 Bottles\\/hour\",\"CountingType\":\"Electronic Tablet & Capsule Counting\",\"MachineType\":\"Multi Channel Tablet Counting Machine\",\"Material\":\"S.S. 304 \\/ 316\",\"CountingRange\":\"2 To 9999 Tablets\\/Capsules\",\"BottleType\":\"Plastic \\/ Glass Bottles\",\"SensorType\":\"Infrared \\/ Photoelectric Sensor System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"FeedingSystem\":\"Vibratory Feeding System\",\"Application\":\"Pharmaceuticals, Nutraceuticals, Capsules & Tablet Packaging Industries\"},\"data\":[]}', '2026-05-28 04:51:15', '2026-05-28 04:51:15'),
(174, 'Capsule Filling Machine', 'capsule-filling-machine', 'Automatic Capsule Filling Machine designed for accurate and high-speed filling of powder, granules, and pellets into hard gelatin capsules.Machine is equipped with automatic capsule orientation system, precision filling mechanism, and PLC touch screen control for continuous industrial operation.', '/uploads/machines/capsule-filling-machine-1779943902.jpg', 'Automatic Capsule Filling Machine', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Capsule Filling Machine\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"PowerConsumption\":\"2 to 10 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"ProductionCapacity\":\"12000 To 200000 Capsules\\/hour\",\"FillingType\":\"Powder \\/ Pellet \\/ Granule Capsule Filling\",\"MachineType\":\"Hard Gelatin Capsule Filling Machine\",\"Material\":\"S.S. 304 \\/ 316\",\"CapsuleSize\":\"000 To 5 Size Capsules\",\"FillingAccuracy\":\"+\\/-2 to 3%\",\"DriveType\":\"Servo \\/ Cam Driven System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"FeedingSystem\":\"Automatic Capsule Orientation & Filling System\",\"Application\":\"Pharmaceuticals, Nutraceuticals, Herbal & Healthcare Products\"},\"data\":[]}', '2026-05-28 04:51:42', '2026-05-28 04:51:42'),
(175, 'Soft Gelatin Capsule', 'soft-gelatin-capsule', 'Soft Gelatin Capsule Manufacturing Machine designed for high-speed production of softgel capsules with liquid and oil based filling applications.Machine is equipped with encapsulation system, gelatin cooling arrangement, and PLC touch screen control for continuous industrial operation.', '/uploads/machines/soft-gelatin-capsule-1779943935.jpg', 'Soft Gelatin Capsule Manufacturing Machine', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Soft Gelatin Capsule Manufacturing Machine\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 25 kW\",\"AutomationGrade\":\"Automatic\",\"ProductionCapacity\":\"10000 To 300000 Capsules\\/hour\",\"CapsuleType\":\"Soft Gelatin Capsule Production\",\"MachineType\":\"Softgel Encapsulation Machine\",\"Material\":\"S.S. 304 \\/ 316\",\"CapsuleShape\":\"Oval \\/ Round \\/ Oblong \\/ Customized Shape\",\"FillingType\":\"Oil \\/ Liquid \\/ Suspension Filling\",\"CoolingSystem\":\"Integrated Gelatin Cooling Drum System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"DriveType\":\"Servo \\/ Gear Driven Encapsulation System\",\"Application\":\"Pharmaceuticals, Nutraceuticals, Vitamin & Healthcare Products\"},\"data\":[]}', '2026-05-28 04:52:15', '2026-05-28 04:52:15'),
(176, 'Capsule Polishing Machine', 'capsule-polishing-machine', 'Automatic Capsule Polishing Machine designed for efficient cleaning and polishing of capsule surfaces during pharmaceutical production process.Machine is equipped with brush based polishing system, vacuum dust extraction arrangement, and stainless steel construction for hygienic industrial operation.', '/uploads/machines/capsule-polishing-machine-1779943965.jpg', 'Automatic Capsule Polishing Machine', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Capsule Polishing Machine\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase\",\"PowerConsumption\":\"0.5 to 2 kW\",\"AutomationGrade\":\"Automatic\",\"ProcessingCapacity\":\"50000 To 500000 Capsules\\/hour\",\"PolishingType\":\"Capsule Surface Cleaning & Polishing\",\"MachineType\":\"Brush Type Capsule Polisher\",\"Material\":\"S.S. 304 \\/ 316\",\"OperationSystem\":\"Continuous Capsule Feeding & Polishing\",\"DriveType\":\"Motor Driven Brush System\",\"DustRemoval\":\"Integrated Vacuum Dust Extraction System\",\"ControlSystem\":\"Digital Control Panel\",\"InstallationType\":\"Inline Capsule Production Integration\",\"Application\":\"Pharmaceuticals, Nutraceuticals & Healthcare Capsule Manufacturing\"},\"data\":[]}', '2026-05-28 04:52:45', '2026-05-28 04:52:45'),
(177, 'Liquid Manufacturing Vessel', 'liquid-manufacturing-vessel', 'Industrial Liquid Manufacturing Vessel designed for efficient mixing, heating, cooling, and processing of liquid machine_products in industrial applications.Machine is equipped with agitator system, hygienic stainless steel vessel, and PLC touch screen control for reliable manufacturing operation.', '/uploads/machines/liquid-manufacturing-vessel-1779944158.jpg', 'Industrial Liquid Manufacturing Vessel', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Liquid Manufacturing Vessel\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"3 to 50 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"VesselCapacity\":\"50 Litre To 20000 Litre\",\"ProcessingType\":\"Liquid Mixing & Manufacturing\",\"VesselType\":\"Jacketed \\/ Non Jacketed Manufacturing Vessel\",\"Material\":\"S.S. 304 \\/ 316\",\"HeatingType\":\"Steam \\/ Electric Heating\",\"CoolingType\":\"Water \\/ Chilled Water Cooling Jacket\",\"AgitationSystem\":\"Motor Driven Agitator System\",\"ConstructionType\":\"Cylindrical Hygienic Vessel Design\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"Application\":\"Pharmaceuticals, Cosmetics, Chemicals, Syrup & Food Liquid Products\"},\"data\":[]}', '2026-05-28 04:55:58', '2026-05-28 04:55:58'),
(178, 'Ampoule Filling & Sealing Machine', 'ampoule-filling-sealing-machine', 'Automatic Ampoule Filling & Sealing Machine designed for accurate filling and secure sealing of injectable liquid ampoules in pharmaceutical production applications.Machine is equipped with precision liquid filling system, flame sealing mechanism, and PLC touch screen control for continuous industrial operation.', '/uploads/machines/ampoule-filling-sealing-machine-1779944190.jpg', 'Automatic Ampoule Filling & Sealing Machine', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Ampoule Filling & Sealing Machine\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"PowerConsumption\":\"2 to 12 kW\",\"AutomationGrade\":\"Automatic\",\"ProductionCapacity\":\"2000 To 24000 Ampoules\\/hour\",\"FillingType\":\"Liquid Ampoule Filling & Flame Sealing\",\"MachineType\":\"Linear \\/ Rotary Ampoule Filling Machine\",\"Material\":\"S.S. 304 \\/ 316\",\"AmpouleSize\":\"1ml To 25ml\",\"FillingAccuracy\":\"+\\/-1%\",\"SealingType\":\"LPG \\/ Oxygen Flame Sealing\",\"DriveType\":\"Servo \\/ Pneumatic Driven System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"Application\":\"Pharmaceuticals, Injectable Liquids & Healthcare Products\"},\"data\":[]}', '2026-05-28 04:56:30', '2026-05-28 04:56:30'),
(179, 'Vial Washing Machine', 'vial-washing-machine', 'Automatic Vial Washing Machine designed for efficient internal and external cleaning of pharmaceutical vials before filling process.Machine is equipped with multi-stage washing system, air jet cleaning arrangement, and PLC touch screen control for hygienic industrial operation.', '/uploads/machines/vial-washing-machine-1780031956.jpg', 'Automatic Vial Washing Machine', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Vial Washing Machine\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"PowerConsumption\":\"2 to 10 kW\",\"AutomationGrade\":\"Automatic\",\"WashingCapacity\":\"2000 To 24000 Vials\\/hour\",\"WashingType\":\"Internal & External Vial Washing\",\"MachineType\":\"Rotary \\/ Linear Vial Washing Machine\",\"Material\":\"S.S. 304 \\/ 316\",\"VialSize\":\"2ml To 100ml\",\"WashingMedia\":\"Purified Water \\/ WFI \\/ Air Washing\",\"DriveType\":\"Servo \\/ Pneumatic Driven System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"DryingSystem\":\"Air Jet & Vacuum Cleaning System\",\"Application\":\"Pharmaceuticals, Injectable Products & Sterile Packaging Industries\"},\"data\":[]}', '2026-05-29 05:19:16', '2026-05-29 05:19:16'),
(180, 'Tunnel Sterilizer', 'tunnel-sterilizer', 'Industrial Tunnel Sterilizer designed for continuous dry heat sterilization and depyrogenation of pharmaceutical containers.Machine is equipped with HEPA filtered hot air circulation system, stainless steel conveyor arrangement, and PLC touch screen control for hygienic industrial operation.', '/uploads/machines/tunnel-sterilizer-1780032003.jpg', 'Industrial Tunnel Sterilizer', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Tunnel Sterilizer\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"10 to 60 kW\",\"AutomationGrade\":\"Automatic\",\"SterilizationCapacity\":\"2000 To 30000 Containers\\/hour\",\"SterilizationType\":\"Dry Heat Sterilization & Depyrogenation\",\"MachineType\":\"Continuous Tunnel Sterilizer\",\"Material\":\"S.S. 304 \\/ 316\",\"TemperatureRange\":\"150\\u00b0C To 350\\u00b0C\",\"HeatingSystem\":\"HEPA Filtered Hot Air Circulation\",\"ConveyorType\":\"SS Mesh Conveyor System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"AirFiltration\":\"HEPA Filter Based Sterile Air System\",\"Application\":\"Pharmaceutical Vials, Ampoules, Bottles & Sterile Packaging Industries\"},\"data\":[]}', '2026-05-29 05:20:03', '2026-05-29 05:20:03'),
(181, 'Freeze Dryer (Pharma)', 'freeze-dryer-pharma', 'Pharmaceutical Freeze Dryer designed for low temperature lyophilization and moisture removal of sterile and heat sensitive pharmaceutical machine_products.Machine is equipped with high vacuum system, shelf heating arrangement, and PLC touch screen control for precise pharmaceutical drying operation.', '/uploads/machines/freeze-dryer-pharma-1780032037.jpg', 'Pharmaceutical Freeze Dryer', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Pharmaceutical Freeze Dryer\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"10 to 80 kW\",\"AutomationGrade\":\"Automatic\",\"DryingCapacity\":\"5Kg To 2000Kg\\/batch\",\"DryingMethod\":\"Vacuum Freeze Drying Lyophilization\",\"MachineType\":\"Pharma Lyophilizer Freeze Dryer\",\"Material\":\"S.S. 304 \\/ 316\",\"CoolingTemperature\":\"-40\\u00b0C To -80\\u00b0C\",\"VacuumSystem\":\"High Vacuum Pump System\",\"HeatingSystem\":\"Shelf Heating System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"SterilizationType\":\"CIP \\/ SIP Compatible System\",\"Application\":\"Injectables, Vaccines, Biopharmaceuticals & Heat Sensitive Pharmaceutical Products\"},\"data\":[]}', '2026-05-29 05:20:37', '2026-05-29 05:20:37'),
(182, 'RABS System', 'rabs-system', 'Restricted Access Barrier System (RABS) designed for maintaining sterile and contamination-controlled environments in pharmaceutical manufacturing applications.System is equipped with HEPA filtered laminar airflow, glove port access arrangement, and PLC touch screen control for safe aseptic processing operation.', '/uploads/machines/rabs-system-1780032068.jpg', 'Restricted Access Barrier System (RABS)', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Restricted Access Barrier System (RABS)\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"PowerConsumption\":\"2 to 20 kW\",\"AutomationGrade\":\"Automatic\",\"SystemType\":\"Sterile Barrier Containment System\",\"ProtectionLevel\":\"ISO Class 5 \\/ Grade A Environment\",\"ConstructionType\":\"Closed Restricted Access Barrier System\",\"Material\":\"S.S. 304 \\/ 316 With Toughened Glass Panels\",\"AirFlowSystem\":\"HEPA Filtered Laminar Air Flow\",\"PressureControl\":\"Positive Pressure Sterile Environment\",\"AccessSystem\":\"Glove Ports & Interlocked Access Doors\",\"ControlSystem\":\"PLC Controlled With HMI Touch Screen\",\"SafetyFeatures\":\"Environmental Monitoring & Alarm System\",\"Application\":\"Pharmaceutical Aseptic Filling, Sterile Packaging & Biopharmaceutical Processing\"},\"data\":[]}', '2026-05-29 05:21:08', '2026-05-29 05:21:08'),
(183, 'Blister Packing Machine (Alu/PVC)', 'blister-packing-machine-alu-pvc', 'Automatic Blister Packing Machine designed for high-speed and hygienic blister packaging of tablets and capsules using Alu-Alu and Alu-PVC materials.Machine is equipped with automatic feeding system, thermoforming and sealing arrangement, and PLC touch screen control for continuous industrial operation.', '/uploads/machines/blister-packing-machine-alu-pvc-1780032102.jpg', 'Automatic Blister Packing Machine (Alu/PVC)', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Blister Packing Machine (Alu\\/PVC)\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"3 to 20 kW\",\"AutomationGrade\":\"Automatic\",\"ProductionCapacity\":\"10000 To 300000 Blisters\\/hour\",\"PackingType\":\"Alu-Alu \\/ Alu-PVC Blister Packaging\",\"MachineType\":\"Rotary \\/ Flat Plate Blister Packing Machine\",\"Material\":\"S.S. 304 \\/ 316\",\"FormingType\":\"Thermoforming & Cold Forming\",\"SealingType\":\"Heat Sealing System\",\"FeedingSystem\":\"Automatic Tablet \\/ Capsule Feeding System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"DriveType\":\"Servo Driven Indexing System\",\"Application\":\"Pharmaceutical Tablets, Capsules & Healthcare Packaging Industries\"},\"data\":[]}', '2026-05-29 05:21:42', '2026-05-29 05:21:42'),
(184, 'Strip Packing Machine', 'strip-packing-machine', 'Automatic Strip Packing Machine designed for high-speed and hygienic strip packaging of tablets and capsules in pharmaceutical production applications.Machine is equipped with automatic feeding system, heat sealing arrangement, and PLC touch screen control for continuous industrial operation.', '/uploads/machines/strip-packing-machine-1780032141.jpg', 'Automatic Strip Packing Machine', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Strip Packing Machine\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"2 to 15 kW\",\"AutomationGrade\":\"Automatic\",\"ProductionCapacity\":\"10000 To 250000 Tablets\\/hour\",\"PackingType\":\"Tablet & Capsule Strip Packaging\",\"MachineType\":\"Continuous Rotary Strip Packing Machine\",\"Material\":\"S.S. 304 \\/ 316\",\"PackagingMaterial\":\"Aluminium Foil \\/ Laminated Film\",\"SealingType\":\"Heat Sealing System\",\"FeedingSystem\":\"Automatic Tablet \\/ Capsule Feeding System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"DriveType\":\"Servo \\/ Motor Driven System\",\"Application\":\"Pharmaceutical Tablets, Capsules & Healthcare Packaging Industries\"},\"data\":[]}', '2026-05-29 05:22:21', '2026-05-29 05:22:21'),
(185, 'Ointment Manufacturing Plant', 'ointment-manufacturing-plant', 'Industrial Ointment Manufacturing Plant designed for hygienic production of ointments, creams, gels, and viscous pharmaceutical machine_products.Machine is equipped with vacuum homogenizing system, heating and cooling jacket arrangement, and PLC touch screen control for efficient industrial operation.', '/uploads/machines/ointment-manufacturing-plant-1780032179.jpg', 'Industrial Ointment Manufacturing Plant', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Ointment Manufacturing Plant\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"10 to 80 kW\",\"AutomationGrade\":\"Automatic\",\"ProductionCapacity\":\"50 Litre To 10000 Litre\\/batch\",\"ProcessingType\":\"Ointment, Cream & Gel Manufacturing\",\"PlantType\":\"Vacuum Homogenizing Manufacturing Plant\",\"Material\":\"S.S. 304 \\/ 316\",\"HeatingType\":\"Steam \\/ Electric Jacket Heating\",\"CoolingType\":\"Water \\/ Chilled Water Cooling Jacket\",\"MixingSystem\":\"High Speed Homogenizer & Agitator System\",\"VacuumSystem\":\"Vacuum Emulsifying System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"Application\":\"Pharmaceutical, Cosmetic, Cream, Gel & Ointment Manufacturing\"},\"data\":[]}', '2026-05-29 05:22:59', '2026-05-29 05:22:59'),
(186, 'Tube Filling Machine', 'tube-filling-machine', 'Automatic Tube Filling Machine designed for accurate filling and sealing of cream, gel, paste, and ointment machine_products in tubes.Machine is equipped with precision filling system, automatic sealing arrangement, and PLC touch screen control for hygienic industrial operation.', '/uploads/machines/tube-filling-machine-1780032208.jpg', 'Automatic Tube Filling Machine', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Automatic Tube Filling Machine\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"PowerConsumption\":\"2 to 12 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"ProductionCapacity\":\"1000 To 12000 Tubes\\/hour\",\"FillingType\":\"Cream, Gel, Paste & Ointment Tube Filling\",\"MachineType\":\"Tube Filling & Sealing Machine\",\"Material\":\"S.S. 304 \\/ 316\",\"TubeType\":\"Plastic \\/ Laminate \\/ Aluminium Tubes\",\"FillingRange\":\"5gm To 500gm\",\"SealingType\":\"Hot Air \\/ Ultrasonic \\/ Fold Sealing\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"DriveType\":\"Servo \\/ Pneumatic Driven System\",\"Application\":\"Pharmaceutical, Cosmetic, Food & Personal Care Products\"},\"data\":[]}', '2026-05-29 05:23:28', '2026-05-29 05:23:28'),
(187, 'Reverse Osmosis (RO) System', 'reverse-osmosis-ro-system', 'Industrial Reverse Osmosis (RO) System designed for high-efficiency purification and treatment of water using advanced membrane filtration technology.System is equipped with multi-stage filtration arrangement, high pressure pump system, and PLC touch screen control for reliable industrial operation.', '/uploads/machines/reverse-osmosis-ro-system-1780032239.jpg', 'Industrial Reverse Osmosis (RO) System', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Reverse Osmosis (RO) System\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"PowerConsumption\":\"2 to 100 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"ProcessingCapacity\":\"250 LPH To 100000 LPH\",\"PurificationType\":\"Reverse Osmosis Water Purification\",\"SystemType\":\"Single Pass \\/ Double Pass RO System\",\"Material\":\"S.S. 304 \\/ 316 \\/ FRP\",\"MembraneType\":\"High Efficiency RO Membrane\",\"FiltrationStages\":\"Multi Stage Water Filtration System\",\"OperatingPressure\":\"High Pressure Pump System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"WaterQuality\":\"Low TDS & Purified Water Output\",\"Application\":\"Drinking Water, Pharmaceuticals, Food Processing & Industrial Water Treatment\"},\"data\":[]}', '2026-05-29 05:23:59', '2026-05-29 05:23:59'),
(188, 'Multi-Effect Distillation (WFI) Unit', 'multi-effect-distillation-wfi-unit', 'Multi-Effect Distillation (WFI) Unit designed for production of pyrogen-free Water For Injection (WFI) in pharmaceutical and biotech industries.System is equipped with multiple effect distillation chambers, sanitary stainless steel construction, and PLC touch screen control for reliable sterile water generation.', '/uploads/machines/multi-effect-distillation-wfi-unit-1780032275.jpg', 'Multi-Effect Distillation (WFI) Unit', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Multi-Effect Distillation (WFI) Unit\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"10 to 120 kW\",\"AutomationGrade\":\"Automatic\",\"ProductionCapacity\":\"100 LPH To 10000 LPH\",\"PurificationType\":\"Water For Injection (WFI) Generation\",\"SystemType\":\"Multi-Effect Distillation Unit\",\"Material\":\"S.S. 316L\",\"HeatingType\":\"Pure Steam Heated Distillation System\",\"DistillationStages\":\"Multiple Effect Evaporation Chambers\",\"WaterQuality\":\"Pyrogen Free Sterile WFI Water\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"SterilizationType\":\"Sanitary & CIP\\/SIP Compatible Design\",\"Application\":\"Pharmaceutical, Biotech & Sterile Injectable Manufacturing Industries\"},\"data\":[]}', '2026-05-29 05:24:35', '2026-05-29 05:24:35'),
(189, 'ETO Sterilizer', 'eto-sterilizer', 'Industrial ETO Sterilizer designed for low temperature sterilization of heat sensitive medical and pharmaceutical machine_products using ethylene oxide gas technology.Machine is equipped with vacuum sterilization chamber, gas safety system, and PLC touch screen control for safe and reliable industrial operation.', '/uploads/machines/eto-sterilizer-1780032322.jpg', 'Industrial ETO Sterilizer', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial ETO Sterilizer\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 50 kW\",\"AutomationGrade\":\"Automatic\",\"SterilizationCapacity\":\"50 Litre To 20000 Litre\",\"SterilizationType\":\"Ethylene Oxide Gas Sterilization\",\"MachineType\":\"Vacuum ETO Sterilizer Chamber\",\"Material\":\"S.S. 304 \\/ 316\",\"OperatingTemperature\":\"30\\u00b0C To 60\\u00b0C\",\"GasType\":\"Ethylene Oxide (ETO) Sterilization Gas\",\"VacuumSystem\":\"High Vacuum Pump System\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"SafetyFeatures\":\"Gas Leak Detection & Safety Interlock System\",\"Application\":\"Medical Devices, Pharmaceuticals, Surgical Instruments & Healthcare Products\"},\"data\":[]}', '2026-05-29 05:25:22', '2026-05-29 05:25:22'),
(190, 'Laminar Air Flow (LAF) Unit', 'laminar-air-flow-laf-unit', 'Laminar Air Flow (LAF) Unit designed to provide a clean and contamination-free working environment through HEPA filtered unidirectional airflow.Unit is equipped with advanced filtration system, low noise blower arrangement, and hygienic construction for reliable cleanroom operation.', '/uploads/machines/laminar-air-flow-laf-unit-1780116542.jpg', 'Laminar Air Flow (LAF) Unit', '', 1, 15, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Laminar Air Flow (LAF) Unit\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"PowerConsumption\":\"0.5 to 5 kW\",\"AutomationGrade\":\"Automatic\",\"AirFlowType\":\"Horizontal \\/ Vertical Laminar Air Flow\",\"CleanlinessClass\":\"ISO Class 5 \\/ Class 100\",\"ConstructionType\":\"Cleanroom Laminar Air Flow Workstation\",\"Material\":\"S.S. 304 \\/ Powder Coated Steel\",\"FiltrationSystem\":\"HEPA Filter With Pre Filter\",\"AirVelocity\":\"0.3 To 0.5 m\\/s\",\"NoiseLevel\":\"< 65 dB\",\"LightingSystem\":\"LED Illumination System\",\"ControlSystem\":\"Digital Control Panel\",\"Application\":\"Pharmaceuticals, Biotechnology, Laboratories, Electronics & Sterile Processing Areas\"},\"data\":[]}', '2026-05-30 04:49:02', '2026-05-30 04:49:02'),
(191, 'Hammer Mill', 'hammer-mill', 'Industrial Hammer Mill designed for efficient crushing, grinding, and size reduction of various dry materials using high-speed impact technology.Machine is equipped with heavy-duty hammer system, robust grinding chamber, and PLC or digital control panel for reliable industrial operation.', '/uploads/machines/hammer-mill-1780118452.jpg', 'Industrial Hammer Mill', '', 1, 14, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Hammer Mill\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"3 to 100 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"GrindingCapacity\":\"50Kg To 10000Kg\\/hour\",\"GrindingType\":\"Impact Hammer Grinding\",\"MillType\":\"Hammer Mill Pulverizer\",\"Material\":\"S.S. 304 \\/ 316 \\/ MS Body\",\"HammerType\":\"Swinging \\/ Fixed Hammer System\",\"ParticleSize\":\"0.5mm To 10mm\",\"DriveType\":\"High Speed Motor Driven System\",\"RotorSpeed\":\"1500 To 6000 RPM\",\"ControlSystem\":\"PLC Controlled \\/ Digital Control Panel\",\"Application\":\"Grains, Spices, Animal Feed, Chemicals, Biomass & Food Processing\"},\"data\":[]}', '2026-05-30 05:20:52', '2026-05-30 05:20:52'),
(192, 'Ball Mill', 'ball-mill', 'Industrial Ball Mill designed for fine grinding, mixing, and size reduction of powders and solid materials through rotating grinding media technology.Machine is equipped with heavy-duty rotary drum, steel or ceramic grinding media, and PLC controlled operation for efficient industrial processing.', '/uploads/machines/ball-mill-1780118490.jpg', 'Industrial Ball Mill', '', 1, 14, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Ball Mill\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 200 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"GrindingCapacity\":\"50Kg To 20000Kg\\/hour\",\"GrindingType\":\"Ball Grinding & Size Reduction\",\"MillType\":\"Horizontal Ball Mill\",\"Material\":\"S.S. 304 \\/ 316 \\/ Alloy Steel\",\"GrindingMedia\":\"Steel Balls \\/ Ceramic Balls\",\"ParticleSize\":\"1 Micron To 500 Micron\",\"DriveType\":\"Gear Motor Driven Rotary System\",\"RotationSpeed\":\"Variable Speed Operation\",\"ControlSystem\":\"PLC Controlled With Digital Control Panel\",\"Application\":\"Minerals, Chemicals, Ceramics, Paint, Pharmaceutical & Food Processing\"},\"data\":[]}', '2026-05-30 05:21:30', '2026-05-30 05:21:30'),
(193, 'Plate Mill', 'plate-mill', 'Industrial Plate Mill designed for efficient grinding and milling of grains, spices, pulses, and other dry materials using rotating plate technology.Machine is equipped with precision grinding plates, robust motor drive system, and durable construction for reliable industrial operation.', '/uploads/machines/plate-mill-1780118527.jpg', 'Industrial Plate Mill', '', 1, 14, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Plate Mill\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"2 to 50 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"GrindingCapacity\":\"20Kg To 5000Kg\\/hour\",\"GrindingType\":\"Plate Grinding & Milling\",\"MillType\":\"Disc \\/ Plate Mill\",\"Material\":\"S.S. 304 \\/ 316 \\/ MS Body\",\"GrindingPlates\":\"Cast Iron \\/ Stainless Steel Plates\",\"ParticleSize\":\"0.2mm To 5mm\",\"DriveType\":\"Motor Driven Grinding System\",\"SpeedRange\":\"500 To 3000 RPM\",\"ControlSystem\":\"Digital Control Panel\",\"GrindingEfficiency\":\"Uniform Coarse To Fine Grinding\",\"Application\":\"Grains, Spices, Pulses, Food Products & Agricultural Processing\"},\"data\":[]}', '2026-05-30 05:22:07', '2026-05-30 05:22:07'),
(194, 'Colloid Mill', 'colloid-mill', 'Industrial Colloid Mill designed for fine wet grinding, emulsification, homogenization, and particle size reduction of liquid and semi-solid machine_products.Machine is equipped with high-speed rotor-stator system, adjustable grinding gap, and stainless steel construction for hygienic industrial operation.', '/uploads/machines/colloid-mill-1780118562.jpg', 'Industrial Colloid Mill', '', 1, 14, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Colloid Mill\"},\"specifications\":{\"Voltage\":\"220V AC Single Phase & 415V AC Three Phase\",\"PowerConsumption\":\"2 to 50 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"ProcessingCapacity\":\"50 LPH To 20000 LPH\",\"GrindingType\":\"Wet Grinding, Homogenizing & Emulsifying\",\"MillType\":\"Rotor-Stator Colloid Mill\",\"Material\":\"S.S. 304 \\/ 316\",\"ParticleSize\":\"1 To 50 Micron\",\"DriveType\":\"High Speed Motor Driven System\",\"RotorSpeed\":\"3000 To 15000 RPM\",\"GapAdjustment\":\"Adjustable Rotor-Stator Clearance\",\"ControlSystem\":\"PLC Controlled \\/ Digital Control Panel\",\"Application\":\"Peanut Butter, Sauces, Creams, Pharmaceuticals, Cosmetics & Food Processing\"},\"data\":[]}', '2026-05-30 05:22:42', '2026-05-30 05:22:42'),
(195, 'Jaw Crusher', 'jaw-crusher', 'Industrial Jaw Crusher designed for primary crushing of hard rocks, minerals, ores, and construction materials using compression crushing technology.Machine is equipped with heavy-duty jaw plates, robust frame construction, and efficient drive system for continuous industrial operation.', '/uploads/machines/jaw-crusher-1780118614.jpg', 'Industrial Jaw Crusher', '', 1, 14, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Jaw Crusher\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 250 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"CrushingCapacity\":\"1 TPH To 1000 TPH\",\"CrushingType\":\"Primary Compression Crushing\",\"CrusherType\":\"Single Toggle \\/ Double Toggle Jaw Crusher\",\"Material\":\"Heavy Duty M.S. Fabricated Body\",\"FeedSize\":\"Up To 1200 mm\",\"OutputSize\":\"10 mm To 300 mm\",\"DriveType\":\"Electric Motor Driven System\",\"JawMaterial\":\"Manganese Steel Jaw Plates\",\"ControlSystem\":\"PLC Controlled \\/ Digital Control Panel\",\"Application\":\"Mining, Quarrying, Minerals, Construction & Aggregate Processing\"},\"data\":[]}', '2026-05-30 05:23:34', '2026-05-30 05:23:34'),
(196, 'Roll Crusher', 'roll-crusher', 'Industrial Roll Crusher designed for controlled size reduction of minerals, coal, chemicals, and bulk materials using compression roll crushing technology.Machine is equipped with hardened alloy steel rolls, robust frame construction, and efficient drive system for reliable industrial operation.', '/uploads/machines/roll-crusher-1780118654.jpg', 'Industrial Roll Crusher', '', 1, 14, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Roll Crusher\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"3 to 150 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"CrushingCapacity\":\"1 TPH To 500 TPH\",\"CrushingType\":\"Compression Roll Crushing\",\"CrusherType\":\"Single Roll \\/ Double Roll Crusher\",\"Material\":\"Heavy Duty M.S. Fabricated Body\",\"FeedSize\":\"Up To 100 mm\",\"OutputSize\":\"1 mm To 50 mm\",\"RollMaterial\":\"Hardened Alloy Steel Rolls\",\"DriveType\":\"Gear Motor Driven System\",\"ControlSystem\":\"PLC Controlled \\/ Digital Control Panel\",\"Application\":\"Coal, Minerals, Chemicals, Fertilizers & Aggregate Processing\"},\"data\":[]}', '2026-05-30 05:24:14', '2026-05-30 05:24:14'),
(197, 'Pasteurizer (Plate/Tubular)', 'pasteurizer-plate-tubular', 'Industrial Pasteurizer (Plate/Tubular) designed for efficient thermal treatment and pasteurization of liquid food and beverage machine_products.Machine is equipped with advanced heat exchange system, controlled holding section, and PLC touch screen control for reliable industrial operation.', '/uploads/machines/pasteurizer-plate-tubular-1780118686.jpg', 'Industrial Pasteurizer (Plate/Tubular)', '', 1, 14, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Pasteurizer (Plate\\/Tubular)\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 100 kW\",\"AutomationGrade\":\"Automatic\",\"ProcessingCapacity\":\"100 LPH To 50000 LPH\",\"ProcessingType\":\"Pasteurization & Thermal Treatment\",\"PasteurizerType\":\"Plate Heat Exchanger \\/ Tubular Pasteurizer\",\"Material\":\"S.S. 304 \\/ 316\",\"HeatingType\":\"Steam \\/ Hot Water Heating System\",\"CoolingType\":\"Chilled Water \\/ Glycol Cooling System\",\"TemperatureRange\":\"60\\u00b0C To 95\\u00b0C\",\"HoldingSystem\":\"Controlled Holding Tube Section\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"Application\":\"Milk, Juice, Beverages, Dairy Products & Liquid Food Processing\"},\"data\":[]}', '2026-05-30 05:24:46', '2026-05-30 05:24:46'),
(198, 'UHT Processing Unit', 'uht-processing-unit', 'Industrial UHT Processing Unit designed for ultra-high temperature sterilization of liquid food and beverage machine_products while maintaining product quality and shelf life.Machine is equipped with advanced heating and cooling system, sterile processing arrangement, and PLC touch screen control for continuous industrial operation.', '/uploads/machines/uht-processing-unit-1780118714.jpg', 'Industrial UHT Processing Unit', '', 1, 14, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial UHT Processing Unit\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"10 to 150 kW\",\"AutomationGrade\":\"Automatic\",\"ProcessingCapacity\":\"500 LPH To 50000 LPH\",\"ProcessingType\":\"Ultra High Temperature Sterilization\",\"SystemType\":\"Direct \\/ Indirect UHT Processing System\",\"Material\":\"S.S. 304 \\/ 316L\",\"HeatingType\":\"Steam Injection \\/ Heat Exchanger Heating\",\"CoolingType\":\"Chilled Water \\/ Glycol Cooling System\",\"TemperatureRange\":\"135\\u00b0C To 150\\u00b0C\",\"HoldingTime\":\"2 To 10 Seconds\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"Application\":\"Milk, Dairy Products, Juices, Beverages & Liquid Food Processing\"},\"data\":[]}', '2026-05-30 05:25:14', '2026-05-30 05:25:14'),
(199, 'Autoclave (Food)', 'autoclave-food', 'Industrial Retort / Food Autoclave designed for thermal sterilization and shelf-life extension of packaged food and beverage machine_products.Machine is equipped with pressurized sterilization chamber, advanced h', '/uploads/machines/autoclave-food-1780118756.jpg', 'Industrial Retort / Food Autoclave', '', 1, 14, '{\"meta\":{\"brand\":\"SALVIN\",\"name\":\"Industrial Retort \\/ Food Autoclave\"},\"specifications\":{\"Voltage\":\"415V AC Three Phase\",\"PowerConsumption\":\"5 to 80 kW\",\"AutomationGrade\":\"Automatic \\/ Semi Automatic\",\"ProcessingCapacity\":\"50Kg To 10000Kg\\/batch\",\"ProcessingType\":\"Thermal Sterilization & Food Preservation\",\"MachineType\":\"Retort Sterilizer \\/ Food Autoclave\",\"Material\":\"S.S. 304 \\/ 316\",\"HeatingType\":\"Steam \\/ Hot Water Spray \\/ Water Immersion System\",\"CoolingType\":\"Water Cooling System\",\"OperatingPressure\":\"Pressurized Sterilization Chamber\",\"TemperatureRange\":\"100\\u00b0C To 135\\u00b0C\",\"ControlSystem\":\"PLC Controlled With Touch Screen\",\"Application\":\"Ready-To-Eat Foods, Canned Foods, Pouches, Pet Food & Beverage Products\"},\"data\":[]}', '2026-05-30 05:25:56', '2026-05-30 05:25:56'),
(200, 'Semi Automatic Induction Sealing Machine', 'semi-automatic-induction-sealing-machine', 'Semi Automatic Induction Sealing Machine is used for sealing aluminum foil liners on bottles and containers through electromagnetic induction technology. It provides leak-proof, tamper-proof and hygienic sealing for pharmaceutical, food, cosmetic and chemical machine_products.', '/uploads/machines/semi-automatic-induction-sealing-machine-1780913040.jpg', 'Semi Automatic Induction Sealing Machine Manufacturer', 'Semi Automatic Induction Sealing Machine for bottle and container sealing. Suitable for pharmaceutical, food, cosmetic and chemical industries.', 2, 8, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Semi Automatic\",\"Sealing Type\":\"Induction Sealing\",\"Power Supply\":\"220V AC, 50Hz\",\"Power Consumption\":\"1000W\",\"Sealing Diameter\":\"20mm - 120mm\",\"Sealing Speed\":\"10-30 Bottles\\/Min\",\"Cooling System\":\"Air Cooled\",\"Body Material\":\"Stainless Steel\"},\"data\":[]}', '2026-06-08 10:04:00', '2026-06-08 10:04:00'),
(201, 'Roller Conveyor Machine', 'roller-conveyor-machine', 'Roller Conveyor Machine is used for smooth transportation of bottles, cartons, boxes and industrial machine_products between different production stations. It improves workflow efficiency and reduces manual handling in packaging and manufacturing lines.', '/uploads/machines/roller-conveyor-machine-1780913959.jpg', 'Roller Conveyor Machine Manufacturer', 'Industrial Roller Conveyor Machine for product handling, packaging lines and factory automation applications. Durable stainless steel construction with smooth operation.', 2, 17, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Roller Conveyor\",\"Roller Material\":\"Stainless Steel\",\"Frame Material\":\"SS304\",\"Conveyor Length\":\"1000-6000 mm\",\"Conveyor Width\":\"300-1000 mm\",\"Load Capacity\":\"Up to 100 Kg\",\"Drive Type\":\"Motorized\",\"Speed\":\"Variable\",\"Power Supply\":\"220V \\/ 415V\",\"Application\":\"Material Handling\"},\"data\":[]}', '2026-06-08 10:19:19', '2026-06-08 10:19:19'),
(202, 'Octa Blender Machine', 'octa-blender-machine', 'Octa Blender Machine is widely used in pharmaceutical, food, chemical and nutraceutical industries for homogeneous blending of dry powders and granules. The octagonal shaped container provides efficient mixing with minimal particle size reduction and ensures uniform blending. The machine is manufactured in SS304/SS316 construction and designed for GMP compliant operations.', '/uploads/machines/octa-blender-machine-1780914947.jpg', 'Octa Blender Machine Manufacturer and Supplier', 'Industrial Octa Blender Machine for pharmaceutical, food and chemical industries. High efficiency powder blending system with SS304/SS316 construction and GMP compliant design.', 1, 15, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Octa Blender\",\"Capacity\":\"50 Ltr - 5000 Ltr\",\"Material\":\"SS304 \\/ SS316\",\"Mixing Type\":\"Dry Powder Blending\",\"Blender Shape\":\"Octagonal\",\"Drive Type\":\"Geared Motor\",\"Speed\":\"Variable\",\"Power Supply\":\"415V AC\",\"Discharge Type\":\"Butterfly Valve\",\"Application\":\"Pharmaceutical Powder Mixing\"},\"data\":[]}', '2026-06-08 10:35:47', '2026-06-08 10:35:47'),
(203, 'Reactor Vessel Machine', 'reactor-vessel-machine', 'Reactor Vessel Machine is widely used in pharmaceutical, chemical, food and cosmetic industries for mixing, blending, heating, cooling and chemical processing operations. The reactor is manufactured using high quality SS304/SS316 stainless steel and equipped with an agitator, gearbox, control panel and safety platform for efficient production processes.', '/uploads/machines/reactor-vessel-machine-1780916185.jpg', 'Reactor Vessel Machine Manufacturer and Supplier', 'Industrial Reactor Vessel Machine for pharmaceutical, chemical, cosmetic and food processing industries. Available in SS304 and SS316 construction with custom capacities.', 1, 22, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Reactor Vessel\",\"Capacity\":\"100 Ltr - 10000 Ltr\",\"Material\":\"SS304 \\/ SS316\",\"Reactor Type\":\"Jacketed Reactor\",\"Agitator Type\":\"Anchor \\/ Turbine\",\"Drive Type\":\"Geared Motor\",\"Heating System\":\"Steam \\/ Electric\",\"Cooling System\":\"Water Cooling\",\"Power Supply\":\"415V AC\",\"Application\":\"Chemical & Pharmaceutical Processing\"},\"data\":[]}', '2026-06-08 10:51:18', '2026-06-08 10:56:25'),
(204, 'Semi Automatic Round Bottle Labeling Machine', 'semi-automatic-round-bottle-labeling-machine', 'Semi Automatic Round Bottle Labeling Machine is designed for accurate and wrinkle-free labeling of round bottles, jars and containers. The machine ensures precise label placement with adjustable speed control and easy operation. It is widely used in pharmaceutical, food, cosmetic, chemical and beverage industries.', '/uploads/machines/semi-automatic-round-bottle-labeling-machine-1780916358.jpg', 'Semi Automatic Round Bottle Labeling Machine Manufacturer', 'Semi Automatic Round Bottle Labeling Machine for accurate sticker labeling on bottles, jars and containers. Suitable for pharmaceutical, food, cosmetic and chemical industries.', 2, 19, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Semi Automatic Labeling Machine\",\"Label Type\":\"Self Adhesive Sticker\",\"Container Type\":\"Round Bottle\",\"Production Speed\":\"20-40 Bottles\\/Min\",\"Label Accuracy\":\"\\u00b11 mm\",\"Label Roll Diameter\":\"Up to 300 mm\",\"Power Supply\":\"220V AC\",\"Control System\":\"Electronic Speed Control\",\"Body Material\":\"SS304 Stainless Steel\",\"Application\":\"Bottle Labeling\"},\"data\":[]}', '2026-06-08 10:59:18', '2026-06-08 10:59:18'),
(205, 'Paste Mixer Machine', 'paste-mixer-machine', 'Paste Mixer Machine is used for efficient mixing, blending and homogenizing of viscous materials such as creams, gels, pastes, ointments, adhesives, food machine_products and chemical compounds. The machine is equipped with a heavy-duty agitator, robust mixing vessel and user-friendly control panel to ensure uniform product consistency and high production efficiency.', '/uploads/machines/paste-mixer-machine-1780916548.jpg', 'Paste Mixer Machine Manufacturer and Supplier', 'Industrial Paste Mixer Machine for mixing creams, gels, ointments, adhesives and viscous machine_products. Available in SS304 and SS316 construction with multiple capacity options.', 1, 21, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Paste Mixer\",\"Capacity\":\"50 Ltr - 2000 Ltr\",\"Material\":\"SS304 \\/ SS316\",\"Mixing Type\":\"Paste & Viscous Material Mixing\",\"Agitator Type\":\"Anchor \\/ Paddle\",\"Drive Type\":\"Geared Motor\",\"Speed Control\":\"Variable Frequency Drive\",\"Power Supply\":\"415V AC\",\"Discharge Type\":\"Bottom Valve\",\"Application\":\"Paste, Cream & Gel Mixing\"},\"data\":[]}', '2026-06-08 11:02:28', '2026-06-08 11:02:28'),
(206, 'Blister Manual Sealing Machine', 'blister-manual-sealing-machine', 'Blister Manual Sealing Machine is designed for sealing blister packs used in pharmaceutical, cosmetic, food and consumer product packaging. The machine features a manually operated sealing mechanism with adjustable temperature control for reliable and uniform sealing. It is compact, easy to operate and suitable for small-scale production environments.', '/uploads/machines/blister-manual-sealing-machine-1780916793.jpg', 'Blister Manual Sealing Machine Manufacturer and Supplier', 'Manual Blister Sealing Machine for pharmaceutical, cosmetic and consumer product packaging. Compact design with adjustable temperature control for precise blister sealing.', 2, 10, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Manual Blister Sealing Machine\",\"Sealing Type\":\"Heat Sealing\",\"Operation\":\"Manual Lever Operated\",\"Temperature Range\":\"50\\u00b0C - 300\\u00b0C\",\"Sealing Area\":\"Customizable\",\"Power Supply\":\"220V AC\",\"Control System\":\"Temperature Controller\",\"Body Material\":\"SS304 Stainless Steel\",\"Production Capacity\":\"Small Batch Production\",\"Application\":\"Blister Pack Sealing\"},\"data\":[]}', '2026-06-08 11:06:33', '2026-06-08 11:06:33'),
(207, 'Plain Sifter Machine', 'plain-sifter-machine', 'Plain Sifter Machine is used for screening, grading and separation of powders, granules and dry materials in pharmaceutical, food, chemical and cosmetic industries. The machine provides uniform particle size distribution, high screening efficiency and dust-free operation. It is manufactured using SS304/SS316 stainless steel and designed according to GMP standards.', '/uploads/machines/plain-sifter-machine-1780917022.jpg', 'Plain Sifter Machine Manufacturer and Supplier', 'Industrial Plain Sifter Machine for pharmaceutical, food and chemical industries. High efficiency vibratory screening system with SS304/SS316 construction and GMP compliant design.', 1, 15, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Plain Sifter\",\"Capacity\":\"50 Kg\\/Hr - 2000 Kg\\/Hr\",\"Material\":\"SS304 \\/ SS316\",\"Screen Diameter\":\"20\\\" - 72\\\"\",\"Mesh Size\":\"As Required\",\"Operation\":\"Vibratory Screening\",\"Drive Type\":\"Vibratory Motor\",\"Power Supply\":\"415V AC\",\"Screening Efficiency\":\"High Precision\",\"Application\":\"Powder & Granule Screening\"},\"data\":[]}', '2026-06-08 11:10:22', '2026-06-08 11:10:22'),
(208, 'Liquid Gel Filling Machine', 'liquid-gel-filling-machine', 'Liquid Gel Filling Machine is designed for accurate filling of liquids, gels, creams, lotions, shampoos, syrups and other viscous machine_products into bottles, jars and containers. The machine ensures high filling accuracy, hygienic operation and efficient production for pharmaceutical, cosmetic, food and chemical industries.', '/uploads/machines/liquid-gel-filling-machine-1780918031.jpg', 'Liquid Gel Filling Machine Manufacturer and Supplier', 'Industrial Liquid Gel Filling Machine for filling liquids, gels, creams, lotions and syrups. High accuracy filling system with SS304/SS316 construction and PLC control.', 2, 17, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Liquid Gel Filling Machine\",\"Filling Range\":\"50 ml - 5000 ml\",\"Filling Heads\":\"2 - 12 Heads\",\"Filling Accuracy\":\"\\u00b11%\",\"Hopper Capacity\":\"50 Ltr - 500 Ltr\",\"Material\":\"SS304 \\/ SS316\",\"Conveyor Type\":\"Motorized Conveyor\",\"Control System\":\"PLC Control\",\"Power Supply\":\"415V AC\",\"Application\":\"Liquid & Gel Filling\"},\"data\":[]}', '2026-06-08 11:27:11', '2026-06-08 11:27:11');
INSERT INTO `machine_machines` (`id`, `machine_name`, `slug`, `description`, `image_url`, `meta_title`, `meta_description`, `category_id`, `subcategory_id`, `specifications`, `created_at`, `updated_at`) VALUES
(209, 'Flour Vibro Sifter Machine', 'flour-vibro-sifter-machine', 'Flour Vibro Sifter Machine is specially designed for screening, grading and separation of flour, powder and fine food materials. The machine uses high-frequency vibration technology to ensure efficient sieving, uniform particle size distribution and high production output. It is widely used in flour mills, food processing plants, spice industries and powder handling applications.', '/uploads/machines/flour-vibro-sifter-machine-1781004980.jpg', 'Flour Vibro Sifter Machine Manufacturer and Supplier', 'Industrial Flour Vibro Sifter Machine for flour mills and food processing industries. High efficiency vibratory screening system with SS304/SS316 construction and multi-deck screening technology.', 1, 14, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Flour Vibro Sifter\",\"Capacity\":\"100 Kg\\/Hr - 5000 Kg\\/Hr\",\"Material\":\"SS304 \\/ SS316\",\"Screen Layers\":\"1 - 4 Deck\",\"Mesh Size\":\"As Required\",\"Operation\":\"Vibratory Screening\",\"Drive Type\":\"Dual Vibratory Motor\",\"Power Supply\":\"415V AC\",\"Screening Efficiency\":\"95% - 99%\",\"Application\":\"Flour & Powder Screening\"},\"data\":[]}', '2026-06-09 11:36:20', '2026-06-09 11:36:20'),
(210, 'Tablet Counting Filling Machine', 'tablet-counting-filling-machine', 'Tablet Counting Filling Machine is designed for accurate counting and filling of tablets, capsules, softgels and similar machine_products into bottles and containers. The machine ensures high-speed operation, precise counting accuracy and reliable performance for pharmaceutical, nutraceutical and healthcare manufacturing industries.', '/uploads/machines/tablet-counting-filling-machine-1781005161.jpg', 'Tablet Counting Filling Machine Manufacturer and Supplier', 'Industrial Tablet Counting Filling Machine for pharmaceutical and nutraceutical industries. High-speed automatic counting and bottle filling system with PLC control and high accuracy.', 2, 17, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Tablet Counting Filling Machine\",\"Counting Range\":\"1 - 9999 Tablets\",\"Counting Accuracy\":\"99.9%\",\"Product Type\":\"Tablets & Capsules\",\"Hopper Capacity\":\"20 Ltr - 100 Ltr\",\"Filling Speed\":\"Up to 60 Bottles\\/Min\",\"Conveyor Type\":\"Motorized Conveyor\",\"Control System\":\"PLC & Touch Screen\",\"Power Supply\":\"220V \\/ 415V AC\",\"Application\":\"Pharmaceutical Bottle Filling\"},\"data\":[]}', '2026-06-09 11:39:21', '2026-06-09 11:39:21'),
(211, 'Tray Dryer Machine', 'tray-dryer-machine', 'Tray Dryer Machine is used for uniform drying of powders, granules, herbs, chemicals, food machine_products and pharmaceutical materials. The machine provides controlled hot air circulation for efficient moisture removal while maintaining product quality. It is widely used in pharmaceutical, food processing, chemical and herbal industries.', '/uploads/machines/tray-dryer-machine-1781005421.jpg', 'Tray Dryer Machine Manufacturer and Supplier', 'Industrial Tray Dryer Machine for pharmaceutical, food, chemical and herbal industries. High efficiency hot air drying system with SS304/SS316 construction and digital temperature control.', 1, 23, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Tray Dryer Machine\",\"Capacity\":\"12 - 192 Trays\",\"Material\":\"SS304 \\/ SS316\",\"Heating Type\":\"Electric \\/ Steam\",\"Temperature Range\":\"50\\u00b0C - 250\\u00b0C\",\"Air Circulation\":\"Forced Hot Air\",\"Control System\":\"Digital Temperature Controller\",\"Power Supply\":\"415V AC\",\"Drying Method\":\"Batch Type Drying\",\"Application\":\"Pharmaceutical & Food Drying\"},\"data\":[]}', '2026-06-09 11:43:41', '2026-06-09 11:43:41'),
(212, 'Conta Blender Machine', 'conta-blender-machine', 'Conta Blender Machine is designed for homogeneous blending of powders and granules in pharmaceutical, nutraceutical, food and chemical industries. The machine utilizes a removable IBC container system that eliminates manual material handling and ensures contamination-free processing. It provides efficient blending, easy loading/unloading and GMP compliant operation.', '/uploads/machines/conta-blender-machine-1781006069.jpg', 'Conta Blender Machine Manufacturer and Supplier', 'Industrial Conta Blender Machine for pharmaceutical and nutraceutical industries. High efficiency IBC bin blending system with SS304/SS316 construction, PLC control and GMP compliant design.', 1, 15, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Conta Blender\",\"Capacity\":\"100 Ltr - 3000 Ltr\",\"Material\":\"SS304 \\/ SS316\",\"Blender Type\":\"IBC Bin Blender\",\"Mixing Type\":\"Powder & Granule Blending\",\"Drive Type\":\"Geared Motor\",\"Control System\":\"PLC & HMI Touch Screen\",\"Rotation Speed\":\"Variable\",\"Power Supply\":\"415V AC\",\"Application\":\"Pharmaceutical Powder Mixing\"},\"data\":[]}', '2026-06-09 11:54:29', '2026-06-09 11:54:29'),
(213, 'Automatic Check Weigher Machine', 'automatic-check-weigher-machine', 'Automatic Check Weigher Machine is designed for online weight verification of packaged machine_products during production. The machine automatically checks product weight, rejects underweight or overweight machine_products and ensures quality control compliance. It is widely used in pharmaceutical, food, cosmetic and packaging industries.', '/uploads/machines/automatic-check-weigher-machine-1781006194.jpg', 'Automatic Check Weigher Machine Manufacturer and Supplier', 'Industrial Automatic Check Weigher Machine for accurate product weight inspection and quality control. High-speed conveyor based weighing system with PLC and touch screen operation.', 2, 17, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Automatic Check Weigher\",\"Weighing Range\":\"10 g - 50 Kg\",\"Accuracy\":\"\\u00b10.1 g\",\"Conveyor Type\":\"Motorized Conveyor\",\"Display Type\":\"Touch Screen HMI\",\"Rejection System\":\"Automatic Rejector\",\"Material\":\"SS304 Stainless Steel\",\"Control System\":\"PLC Control\",\"Power Supply\":\"220V \\/ 415V AC\",\"Application\":\"Product Weight Inspection\"},\"data\":[]}', '2026-06-09 11:56:34', '2026-06-09 11:56:34'),
(214, 'Fluid Bed Dryer (FBD) Machine', 'fluid-bed-dryer-fbd-machine', 'Fluid Bed Dryer (FBD) Machine is used for rapid and uniform drying of powders, granules and pharmaceutical machine_products using heated air. The machine ensures efficient moisture removal, reduced drying time and consistent product quality. It is widely used in pharmaceutical, chemical, food and nutraceutical manufacturing industries.', '/uploads/machines/fluid-bed-dryer-fbd-machine-1781006363.jpg', 'Fluid Bed Dryer Machine Manufacturer and Supplier', 'Industrial Fluid Bed Dryer (FBD) Machine for pharmaceutical, chemical and food industries. High-efficiency drying system with SS304/SS316 construction, PLC control and uniform drying performance.', 1, 23, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Fluid Bed Dryer (FBD)\",\"Capacity\":\"5 Kg - 500 Kg\",\"Material\":\"SS304 \\/ SS316\",\"Drying Method\":\"Fluidized Hot Air Drying\",\"Heating System\":\"Electric \\/ Steam\",\"Air Flow Type\":\"Controlled Hot Air\",\"Control System\":\"PLC \\/ HMI\",\"Operating Temperature\":\"40\\u00b0C - 120\\u00b0C\",\"Power Supply\":\"415V AC\",\"Application\":\"Powder & Granule Drying\"},\"data\":[]}', '2026-06-09 11:59:24', '2026-06-09 11:59:24'),
(215, 'Multi Mill Machine', 'multi-mill-machine', 'Multi Mill Machine is used for wet and dry granulation, pulverizing, shredding, sizing and milling of pharmaceutical, food, chemical and cosmetic materials. The machine provides uniform particle size reduction with high efficiency and minimal heat generation. It is widely used in pharmaceutical manufacturing plants and processing industries.', '/uploads/machines/multi-mill-machine-1781006480.jpg', 'Multi Mill Machine Manufacturer and Supplier', 'Industrial Multi Mill Machine for pharmaceutical, food and chemical industries. High efficiency wet and dry milling system with SS304/SS316 construction and GMP compliant design.', 1, 15, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Multi Mill\",\"Capacity\":\"25 Kg\\/Hr - 500 Kg\\/Hr\",\"Material\":\"SS304 \\/ SS316\",\"Milling Type\":\"Wet & Dry Milling\",\"Rotor Speed\":\"Up to 3000 RPM\",\"Screen Size\":\"Interchangeable\",\"Drive Type\":\"Electric Motor\",\"Control System\":\"Start\\/Stop Control\",\"Power Supply\":\"415V AC\",\"Application\":\"Granulation & Size Reduction\"},\"data\":[]}', '2026-06-09 12:01:20', '2026-06-09 12:01:20'),
(216, 'Planetary Mixer Machine', 'planetary-mixer-machine', 'Planetary Mixer Machine is used for mixing, kneading and blending creams, ointments, pastes, gels, dough, cosmetics and pharmaceutical machine_products. The planetary mixing action ensures uniform mixing, high efficiency and consistent product quality. It is widely used in pharmaceutical, food, cosmetic and chemical industries.', '/uploads/machines/planetary-mixer-machine-1781006609.jpg', 'Planetary Mixer Machine Manufacturer and Supplier', 'Industrial Planetary Mixer Machine for pharmaceutical, food, cosmetic and chemical industries. High-performance mixing system for creams, pastes, gels and dough with SS304/SS316 construction.', 1, 21, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Planetary Mixer\",\"Capacity\":\"10 Ltr - 500 Ltr\",\"Material\":\"SS304 \\/ SS316\",\"Mixing Type\":\"Planetary Mixing\",\"Bowl Type\":\"Removable Stainless Steel Bowl\",\"Speed Control\":\"Variable Speed\",\"Drive Type\":\"Geared Motor\",\"Control System\":\"Digital Control Panel\",\"Power Supply\":\"220V \\/ 415V AC\",\"Application\":\"Cream, Paste & Dough Mixing\"},\"data\":[]}', '2026-06-09 12:03:29', '2026-06-09 12:03:29'),
(217, 'Reactor Vessel Machine', 'reactor-vessel-machine-2', 'Reactor Vessel Machine is used for mixing, heating, cooling, reaction and processing of liquids, chemicals, pharmaceuticals, cosmetics and food machine_products. The machine is equipped with an agitator system, process piping, pressure gauges and PLC control panel for efficient and controlled production operations.', '/uploads/machines/reactor-vessel-machine-1781006783.jpg', 'Reactor Vessel Machine Manufacturer and Supplier', 'Industrial Reactor Vessel Machine for pharmaceutical, chemical, cosmetic and food industries. SS304/SS316 jacketed reactor with agitator, PLC control panel and high-efficiency processing system.', 1, 22, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Reactor Vessel\",\"Capacity\":\"100 Ltr - 10000 Ltr\",\"Material\":\"SS304 \\/ SS316\",\"Reactor Type\":\"Jacketed Reactor\",\"Agitator Type\":\"Anchor \\/ Turbine\",\"Heating System\":\"Steam \\/ Electric\",\"Cooling System\":\"Water Cooling\",\"Control System\":\"PLC & HMI\",\"Power Supply\":\"415V AC\",\"Application\":\"Chemical & Pharmaceutical Processing\"},\"data\":[]}', '2026-06-09 12:06:23', '2026-06-09 12:06:23'),
(218, 'Linear Bottle Capping Machine', 'linear-bottle-capping-machine', 'Linear Bottle Capping Machine is designed for automatic capping of bottles and containers in pharmaceutical, food, cosmetic and chemical industries. The machine features a continuous conveyor system, multiple capping heads and PLC-based control for high-speed and accurate cap tightening. It ensures consistent capping quality and efficient production line operation.', '/uploads/machines/linear-bottle-capping-machine-1781007132.jpg', 'Linear Bottle Capping Machine Manufacturer and Supplier', 'Industrial Linear Bottle Capping Machine for pharmaceutical, food, cosmetic and chemical industries. High-speed automatic bottle capping system with PLC control, multiple capping heads and stainless steel construction.', 2, 18, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Linear Bottle Capping Machine\",\"Capacity\":\"Up to 120 Bottles\\/Min\",\"Capping Heads\":\"4 - 8 Heads\",\"Bottle Type\":\"Round, Square & Flat Bottles\",\"Cap Type\":\"Screw Cap, ROPP Cap, Flip Top Cap\",\"Conveyor Type\":\"Motorized Conveyor\",\"Material\":\"SS304 \\/ SS316\",\"Control System\":\"PLC & Touch Screen HMI\",\"Power Supply\":\"415V AC\",\"Application\":\"Automatic Bottle Capping\"},\"data\":[]}', '2026-06-09 12:12:12', '2026-06-09 12:12:12'),
(219, 'Rapid Mixer Granulator (RMG) Machine', 'rapid-mixer-granulator-rmg-machine', 'Rapid Mixer Granulator (RMG) Machine is used for high-speed mixing and wet granulation of pharmaceutical powders. The machine combines mixing and granulation in a single vessel, ensuring uniform granule formation, reduced processing time and improved product consistency. It is widely used in pharmaceutical, nutraceutical and chemical manufacturing industries.', '/uploads/machines/rapid-mixer-granulator-rmg-machine-1781007333.jpg', 'Rapid Mixer Granulator Machine Manufacturer and Supplier', 'Industrial Rapid Mixer Granulator (RMG) Machine for pharmaceutical and nutraceutical industries. High-shear mixing and wet granulation system with PLC control, SS304/SS316 construction and GMP compliant design.', 1, 15, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Rapid Mixer Granulator (RMG)\",\"Capacity\":\"10 Ltr - 1200 Ltr\",\"Material\":\"SS304 \\/ SS316\",\"Mixing Type\":\"High Shear Mixing\",\"Granulation Type\":\"Wet Granulation\",\"Impeller Speed\":\"Variable Speed\",\"Chopper Speed\":\"High Speed Chopper\",\"Control System\":\"PLC & Touch Screen HMI\",\"Power Supply\":\"415V AC\",\"Application\":\"Pharmaceutical Granulation\"},\"data\":[]}', '2026-06-09 12:15:33', '2026-06-09 12:15:33'),
(220, 'Automatic Multihead Capping Machine', 'automatic-multihead-capping-machine', 'Automatic Multihead Capping Machine is designed for high-speed capping of bottles and containers in pharmaceutical, food, cosmetic and chemical industries. The machine features multiple capping heads, automatic bottle handling and PLC-based control for precise and consistent cap tightening. It is ideal for large-scale production lines requiring high output and reliable performance.', '/uploads/machines/automatic-multihead-capping-machine-1781081135.jpg', 'Automatic Multihead Capping Machine Manufacturer and Supplier', 'Industrial Automatic Multihead Capping Machine for pharmaceutical, food, cosmetic and chemical industries. High-speed bottle capping system with multiple capping heads, PLC control and stainless steel construction.', 2, 18, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Automatic Multihead Capping Machine\",\"Capacity\":\"Up to 200 Bottles\\/Min\",\"Capping Heads\":\"4 - 12 Heads\",\"Bottle Type\":\"Round, Square & Flat Bottles\",\"Cap Type\":\"Screw Cap, Flip Top Cap, ROPP Cap\",\"Conveyor Type\":\"Motorized Conveyor\",\"Material\":\"SS304 \\/ SS316\",\"Control System\":\"PLC & Touch Screen HMI\",\"Power Supply\":\"415V AC\",\"Application\":\"High Speed Bottle Capping\"},\"data\":[]}', '2026-06-10 08:45:35', '2026-06-10 08:45:35'),
(221, 'Fluid Bed Dryer (FBD) Machine', 'fluid-bed-dryer-fbd-machine-2', 'Fluid Bed Dryer (FBD) Machine is designed for fast and uniform drying of pharmaceutical granules, powders and bulk solids using controlled hot air fluidization technology. The machine provides efficient moisture removal, shorter drying cycles and consistent product quality. It is widely used in pharmaceutical, chemical, food and nutraceutical manufacturing facilities.', '/uploads/machines/fluid-bed-dryer-fbd-machine-1781081338.jpg', 'Fluid Bed Dryer Machine Manufacturer and Supplier', 'Industrial Fluid Bed Dryer (FBD) Machine for pharmaceutical, food and chemical industries. High-efficiency hot air drying system with SS304/SS316 construction, PLC control and GMP compliant design.', 1, 23, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Fluid Bed Dryer (FBD)\",\"Capacity\":\"30 Kg - 500 Kg\",\"Material\":\"SS304 \\/ SS316\",\"Drying Method\":\"Fluidized Hot Air Drying\",\"Heating Type\":\"Electric \\/ Steam\",\"Air Handling System\":\"Integrated Blower\",\"Operating Temperature\":\"40\\u00b0C - 120\\u00b0C\",\"Control System\":\"PLC & Touch Screen HMI\",\"Power Supply\":\"415V AC\",\"Application\":\"Pharmaceutical Granule Drying\"},\"data\":[]}', '2026-06-10 08:48:58', '2026-06-10 08:48:58'),
(222, 'Automatic Two Head Servo Filling Machine', 'automatic-two-head-servo-filling-machine', 'Automatic Two Head Servo Filling Machine is designed for precise filling of liquids, gels, creams, oils and viscous machine_products into bottles, jars and containers. The machine utilizes advanced servo-driven filling technology to ensure high accuracy, minimal product wastage and consistent filling performance. It is widely used in pharmaceutical, food, cosmetic and chemical industries.', '/uploads/machines/automatic-two-head-servo-filling-machine-1781081982.jpg', 'Automatic Two Head Servo Filling Machine Manufacturer and Supplier', 'Industrial Automatic Two Head Servo Filling Machine for liquid, gel, cream and oil filling applications. High-precision servo-driven filling system with PLC control, stainless steel construction and reliable production performance.', 2, 17, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Automatic Two Head Servo Filling Machine\",\"Capacity\":\"Up to 60 Bottles\\/Min\",\"Filling Heads\":\"2 Heads\",\"Filling Range\":\"50 ml - 5000 ml\",\"Filling Accuracy\":\"\\u00b10.5%\",\"Product Type\":\"Liquid, Gel, Cream & Oil\",\"Conveyor Type\":\"Motorized Conveyor\",\"Material\":\"SS304 \\/ SS316\",\"Control System\":\"PLC & Touch Screen HMI\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 08:59:42', '2026-06-10 08:59:42'),
(223, 'Automatic Jar Filling Machine', 'automatic-jar-filling-machine', 'Automatic Jar Filling Machine is designed for high-speed filling of jams, sauces, honey, pickles, creams, pastes and other semi-liquid machine_products into jars. The machine features multi-head filling nozzles, automatic jar indexing and PLC-based controls for accurate and hygienic filling operations. It is widely used in food, pharmaceutical, cosmetic and chemical industries.', '/uploads/machines/automatic-jar-filling-machine-1781082097.jpg', 'Automatic Jar Filling Machine Manufacturer and Supplier', 'Industrial Automatic Jar Filling Machine for jam, honey, sauce, cream and paste filling applications. Multi-head filling system with PLC control, stainless steel construction and high-speed production capability.', 2, 17, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Automatic Jar Filling Machine\",\"Capacity\":\"Up to 120 Jars\\/Min\",\"Filling Heads\":\"4 - 8 Heads\",\"Filling Range\":\"100 gm - 5000 gm\",\"Product Type\":\"Jam, Honey, Sauce, Cream & Paste\",\"Jar Type\":\"Glass & Plastic Jars\",\"Conveyor Type\":\"Motorized Conveyor\",\"Material\":\"SS304 \\/ SS316\",\"Control System\":\"PLC & Touch Screen HMI\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 09:01:37', '2026-06-10 09:01:37'),
(225, 'Automatic Shampoo Pouch Packing Machine', 'automatic-shampoo-pouch-packing-machine', 'Automatic Shampoo Pouch Packing Machine is designed for automatic filling and sealing of shampoo, conditioner, lotion, liquid soap and other viscous liquid machine_products into sachets and pouches. The machine integrates pouch forming, filling, sealing and cutting operations in a single compact unit, ensuring high-speed production, accurate filling and leak-proof packaging.', '/uploads/machines/automatic-shampoo-pouch-packing-machine-1781083142.jpg', 'Automatic Shampoo Pouch Packing Machine Manufacturer and Supplier', 'Industrial Automatic Shampoo Pouch Packing Machine for shampoo, lotion and liquid soap packaging. High-speed vertical form fill seal system with PLC control, stainless steel construction and precise pouch filling technology.', 2, 10, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Automatic Shampoo Pouch Packing Machine\",\"Capacity\":\"Up to 80 Pouches\\/Min\",\"Filling Range\":\"5 ml - 100 ml\",\"Product Type\":\"Shampoo, Lotion & Liquid Soap\",\"Packaging Type\":\"Center Seal \\/ Pillow Pouch\",\"Film Type\":\"Laminated Packaging Film\",\"Sealing Type\":\"Heat Sealing\",\"Material\":\"SS304 Stainless Steel\",\"Control System\":\"PLC & Touch Screen HMI\",\"Power Supply\":\"220V \\/ 415V AC\"},\"data\":[]}', '2026-06-10 09:19:02', '2026-06-10 09:19:02'),
(226, 'Automatic Granule Pouch Packing Machine', 'automatic-granule-pouch-packing-machine', 'Automatic Granule Pouch Packing Machine is designed for automatic weighing, filling and sealing of free-flowing granules such as rice, pulses, seeds, sugar, tea, coffee and spices. The machine integrates pouch forming, product dosing, sealing and cutting operations in a single compact unit, ensuring high-speed packaging and accurate weight control.', '/uploads/machines/automatic-granule-pouch-packing-machine-1781083344.jpg', 'Automatic Granule Pouch Packing Machine Manufacturer and Supplier', 'Industrial Automatic Granule Pouch Packing Machine for rice, pulses, seeds, sugar and free-flowing granules. High-speed VFFS packaging system with volumetric filling, PLC control and stainless steel construction.', 2, 10, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Automatic Granule Pouch Packing Machine\",\"Capacity\":\"Up to 70 Pouches\\/Min\",\"Filling Range\":\"10 gm - 1000 gm\",\"Product Type\":\"Rice, Pulses, Seeds, Sugar & Granules\",\"Packaging Type\":\"Center Seal \\/ Pillow Pouch\",\"Weighing System\":\"Volumetric Cup Filler\",\"Film Type\":\"Laminated Packaging Film\",\"Material\":\"SS304 Stainless Steel\",\"Control System\":\"PLC & Touch Screen HMI\",\"Power Supply\":\"220V \\/ 415V AC\"},\"data\":[]}', '2026-06-10 09:22:24', '2026-06-10 09:22:24'),
(227, 'Pharmaceutical Mixing Tank', 'pharmaceutical-mixing-tank', 'Pharmaceutical Mixing Tank is designed for efficient mixing, blending and homogenizing of liquid formulations in pharmaceutical, cosmetic, food and chemical industries. The machine features a stainless steel mixing vessel, top-mounted agitator system and precision control panel to ensure uniform product consistency and hygienic processing.', '/uploads/machines/pharmaceutical-mixing-tank-1781083923.jpg', 'Pharmaceutical Mixing Tank Manufacturer and Supplier', 'Industrial Pharmaceutical Mixing Tank with SS304/SS316 construction, agitator mixing system and digital controls. Suitable for pharmaceutical, cosmetic, food and chemical liquid processing applications.', 1, 21, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Pharmaceutical Mixing Tank\",\"Capacity\":\"100 L - 5000 L\",\"Material\":\"SS304 \\/ SS316\",\"Mixing Type\":\"Agitator Mixing\",\"Agitator Speed\":\"Variable Speed\",\"Vessel Type\":\"Cylindrical Mixing Tank\",\"Heating System\":\"Optional Steam \\/ Electric\",\"Control System\":\"Digital Control Panel\",\"Power Supply\":\"415V AC\",\"Application\":\"Liquid & Syrup Mixing\"},\"data\":[]}', '2026-06-10 09:32:03', '2026-06-10 09:32:03'),
(228, 'Double Shifter Machine', 'double-shifter-machine', 'Double Shifter Machine is designed for grading, sieving and separation of flour, spices, powders, granules and food ingredients. The machine utilizes a double-deck vibrating screen system to achieve high screening efficiency, uniform particle size distribution and continuous production. It is widely used in food, pharmaceutical, chemical and processing industries.', '/uploads/machines/double-shifter-machine-1781084305.jpg', 'Double Shifter Machine Manufacturer and Supplier', 'Industrial Double Shifter Machine for flour, powder and granule screening applications. High-efficiency double deck vibratory sieving system with SS304/SS316 construction and continuous operation capability.', 1, 14, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Double Shifter Machine\",\"Capacity\":\"100 Kg\\/Hr - 3000 Kg\\/Hr\",\"Screening Decks\":\"Double Deck\",\"Screen Type\":\"Vibratory Sieve Screen\",\"Material\":\"SS304 \\/ SS316\",\"Drive System\":\"Vibratory Motor\",\"Mesh Size\":\"Customizable\",\"Operation\":\"Continuous Screening\",\"Power Supply\":\"415V AC\",\"Application\":\"Flour, Powder & Granule Screening\"},\"data\":[]}', '2026-06-10 09:38:25', '2026-06-10 09:38:25'),
(229, 'Vertical Stainless Steel Tank', 'vertical-stainless-steel-tank', 'Vertical Stainless Steel Tank is designed for storage, mixing and processing of liquids, syrups, chemicals and pharmaceutical formulations. The tank is manufactured from high-quality SS304/SS316 stainless steel and offers hygienic operation, corrosion resistance and long service life. It is widely used in pharmaceutical, food, cosmetic and chemical industries.', '/uploads/machines/vertical-stainless-steel-tank-1781084676.jpg', 'Vertical Stainless Steel Tank Manufacturer and Supplier', 'Industrial Vertical Stainless Steel Tank for pharmaceutical, food, cosmetic and chemical industries. Available in SS304/SS316 construction with optional agitator, insulation and hygienic processing design.', 1, 15, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Vertical Stainless Steel Tank\",\"Capacity\":\"100 L - 10000 L\",\"Material\":\"SS304 \\/ SS316\",\"Tank Orientation\":\"Vertical\",\"Vessel Type\":\"Cylindrical Storage Tank\",\"Surface Finish\":\"Mirror \\/ Matt Finish\",\"Insulation\":\"Optional\",\"Mixing System\":\"Optional Agitator\",\"Power Supply\":\"415V AC (If Agitator Installed)\",\"Application\":\"Liquid Storage & Processing\"},\"data\":[]}', '2026-06-10 09:44:36', '2026-06-10 09:44:36'),
(230, 'Double Side Labeling Machine', 'double-side-labeling-machine', 'Double Side Labeling Machine is designed for automatic application of front and back labels on flat, oval and rectangular bottles. The machine features dual labeling heads, synchronized conveyor movement and precision bottle alignment mechanisms to ensure accurate label placement at high production speeds. It is widely used in pharmaceutical, food, cosmetic and chemical industries.', '/uploads/machines/double-side-labeling-machine-1781085295.jpg', 'Double Side Labeling Machine Manufacturer and Supplier', 'Industrial Double Side Labeling Machine for front and back labeling of flat, oval and rectangular bottles. High-speed dual label applicator with PLC control, SS304 construction and precision label placement.', 2, 19, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Double Side Labeling Machine\",\"Capacity\":\"Up to 200 Bottles\\/Min\",\"Labeling Heads\":\"Dual Side\",\"Bottle Type\":\"Flat, Oval & Rectangular Bottles\",\"Label Accuracy\":\"\\u00b11 mm\",\"Conveyor Type\":\"Motorized Conveyor\",\"Label Roll Diameter\":\"Up to 400 mm\",\"Material\":\"SS304 Stainless Steel\",\"Control System\":\"PLC & Touch Screen HMI\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 09:54:55', '2026-06-10 09:54:55'),
(231, 'Automatic Aerosol Filling Machine', 'automatic-aerosol-filling-machine', 'Automatic Aerosol Filling Machine is designed for high-speed filling, valve placement and crimping of aerosol cans used in deodorants, air fresheners, spray paints, lubricants and pharmaceutical sprays. The machine integrates product filling, valve feeding and sealing operations in a single automated system, ensuring safe, accurate and efficient production.', '/uploads/machines/automatic-aerosol-filling-machine-1781086056.jpg', 'Automatic Aerosol Filling Machine Manufacturer and Supplier', 'Industrial Automatic Aerosol Filling Machine for deodorant, spray paint, air freshener and pharmaceutical aerosol packaging. High-speed filling, valve crimping and sealing system with PLC control and stainless steel construction.', 2, 17, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Automatic Aerosol Filling Machine\",\"Capacity\":\"Up to 120 Cans\\/Min\",\"Filling Heads\":\"4 - 12 Heads\",\"Container Type\":\"Aerosol Cans\",\"Filling Range\":\"50 ml - 1000 ml\",\"Valve Type\":\"Standard Aerosol Valve\",\"Conveyor Type\":\"Motorized Conveyor\",\"Material\":\"SS304 \\/ SS316\",\"Control System\":\"PLC & Touch Screen HMI\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 10:07:36', '2026-06-10 10:07:36'),
(232, 'Automatic Checkweigher Machine', 'automatic-checkweigher-machine', 'Automatic Checkweigher Machine is designed for high-speed dynamic weight inspection of bottles, jars, cartons, pouches and containers moving on a conveyor. The machine automatically checks product weight and identifies underweight or overweight machine_products to maintain quality standards and regulatory compliance. It is widely used in pharmaceutical, food, beverage and cosmetic manufacturing industries.', '/uploads/machines/automatic-checkweigher-machine-1781086898.jpg', 'Automatic Checkweigher Machine Manufacturer and Supplier', 'Industrial Automatic Checkweigher Machine for dynamic weight inspection of bottles, jars, cartons and pouches. High-speed conveyor weighing system with automatic rejection and touch screen control.', 2, 24, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Automatic Checkweigher Machine\",\"Capacity\":\"Up to 250 Products\\/Min\",\"Product Type\":\"Bottles, Jars, Cartons, Pouches\",\"Weighing Range\":\"10 g \\u2013 5000 g\",\"Accuracy\":\"\\u00b10.1 g\",\"Conveyor Type\":\"Dynamic Conveyor\",\"Rejection System\":\"Pneumatic Rejector\",\"Material\":\"SS304 Stainless Steel\",\"Control System\":\"PLC & Touch Screen HMI\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 10:21:38', '2026-06-10 10:21:38'),
(233, 'Tray Dryer Tablet Machine', 'tray-dryer-tablet-machine', 'Tray Dryer Tablet Machine is used for drying pharmaceutical tablets, granules, powders, herbal machine_products and chemical materials through controlled hot air circulation. The machine consists of an insulated stainless steel chamber fitted with multiple removable trays, ensuring uniform drying and moisture removal. It is widely used in pharmaceutical, food and chemical processing industries.', '/uploads/machines/tray-dryer-tablet-machine-1781087678.jpg', 'Tray Dryer Tablet Machine Manufacturer and Supplier', 'Industrial Tray Dryer Tablet Machine for pharmaceutical tablets, granules and powders. Multi-tray stainless steel drying system with controlled hot air circulation and uniform drying performance.', 1, 13, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Tray Dryer Tablet Machine\",\"Capacity\":\"12 \\u2013 96 Trays\",\"Heating Type\":\"Electric \\/ Steam\",\"Temperature Range\":\"Ambient to 150\\u00b0C\",\"Air Circulation\":\"Forced Hot Air\",\"Tray Material\":\"SS304 Stainless Steel\",\"Chamber Type\":\"Insulated Drying Chamber\",\"Control System\":\"Digital Temperature Controller\",\"Material\":\"SS304 \\/ SS316 Stainless Steel\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 10:34:38', '2026-06-10 10:34:38'),
(234, 'High Speed Tablet Press Machine', 'high-speed-tablet-press-machine', 'High Speed Tablet Press Machine is designed for continuous compression of pharmaceutical powders and granules into tablets at high production speeds. The machine features a rotary turret system, precision compression mechanism and advanced control panel for consistent tablet weight, thickness and hardness. It is widely used in pharmaceutical, nutraceutical and chemical manufacturing industries.', '/uploads/machines/high-speed-tablet-press-machine-1781088070.jpg', 'High Speed Tablet Press Machine Manufacturer and Supplier', 'Industrial High Speed Tablet Press Machine for pharmaceutical tablet production. Rotary compression system with high output capacity, precise tablet formation and advanced PLC control.', 1, NULL, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"High Speed Tablet Press Machine\",\"Output Capacity\":\"Up to 300,000 Tablets\\/Hour\",\"Number of Stations\":\"27 \\u2013 75 Stations\",\"Tablet Diameter\":\"Up to 25 mm\",\"Compression Type\":\"Rotary Compression\",\"Main Motor Power\":\"5 \\u2013 15 HP\",\"Control System\":\"PLC & Touch Screen HMI\",\"Material\":\"SS304 \\/ SS316 Stainless Steel\",\"Application\":\"Tablet Manufacturing\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 10:41:10', '2026-06-10 10:41:10'),
(235, 'Shrink Wrapping Machine', 'shrink-wrapping-machine', 'Shrink Wrapping Machine is designed for wrapping bottles, cartons, cans and multipack machine_products with shrink film using controlled heat technology. The machine passes machine_products through a heated shrink tunnel where the film tightly conforms to the product shape, providing secure packaging, product protection and attractive presentation. It is widely used in beverage, pharmaceutical, food and consumer goods industries.', '/uploads/machines/shrink-wrapping-machine-1781088262.jpg', 'Shrink Wrapping Machine Manufacturer and Supplier', 'Industrial Shrink Wrapping Machine for bottles, cartons and multipack machine_products. High-performance heat shrink tunnel with conveyor system for secure and attractive packaging.', 2, 8, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Shrink Wrapping Machine\",\"Capacity\":\"Up to 30 Packs\\/Min\",\"Packaging Type\":\"Shrink Film Packaging\",\"Product Type\":\"Bottles, Cans, Cartons\",\"Tunnel Type\":\"Heat Shrink Tunnel\",\"Conveyor Type\":\"Motorized Roller Conveyor\",\"Film Material\":\"PVC \\/ POF \\/ PE Film\",\"Material\":\"SS304 & Mild Steel\",\"Control System\":\"Digital Temperature Controller\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 10:44:22', '2026-06-10 10:44:22'),
(236, 'Automatic Sticker Labeling Machine', 'automatic-sticker-labeling-machine', 'Automatic Sticker Labeling Machine is designed for precise application of self-adhesive labels on bottles, jars, containers and packaging machine_products. The machine features an automatic label dispensing system, synchronized conveyor, bottle guiding mechanism and PLC-based controls to ensure accurate label placement at high production speeds. It is widely used in pharmaceutical, food, beverage and cosmetic industries.', '/uploads/machines/automatic-sticker-labeling-machine-1781088534.jpg', 'Automatic Sticker Labeling Machine Manufacturer and Supplier', 'High-speed Automatic Sticker Labeling Machine for bottles, jars and containers. Accurate self-adhesive label application with PLC control and stainless steel construction.', 2, 19, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Automatic Sticker Labeling Machine\",\"Capacity\":\"Up to 200 Bottles\\/Min\",\"Label Type\":\"Self Adhesive Sticker Labels\",\"Application\":\"Bottles, Jars & Containers\",\"Conveyor Type\":\"SS Slat Conveyor\",\"Label Roll Diameter\":\"Up to 400 mm\",\"Accuracy\":\"\\u00b11 mm\",\"Control System\":\"PLC with Touch Screen HMI\",\"Material\":\"SS304 Construction\",\"Power Supply\":\"230V \\/ 415V AC\"},\"data\":[]}', '2026-06-10 10:48:54', '2026-06-10 10:48:54'),
(237, 'Pallet Stretch Wrapping Machine', 'pallet-stretch-wrapping-machine', 'Pallet Stretch Wrapping Machine is designed for securely wrapping palletized machine_products with stretch film to ensure load stability during storage and transportation. The machine uses a rotating turntable and automatic film carriage system to apply uniform film tension around the pallet. It is widely used in logistics, warehousing, beverage, pharmaceutical and manufacturing industries for safe and efficient pallet packaging.', '/uploads/machines/pallet-stretch-wrapping-machine-1781089551.jpg', 'Pallet Stretch Wrapping Machine Manufacturer and Supplier', 'Industrial Pallet Stretch Wrapping Machine with automatic film carriage and rotating turntable for secure pallet packaging, load stabilization and transportation safety.', 2, 8, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Pallet Stretch Wrapping Machine\",\"Capacity\":\"Up to 35 Pallets\\/Hour\",\"Wrapping Type\":\"Stretch Film Wrapping\",\"Turntable Diameter\":\"1500 mm\",\"Max Pallet Height\":\"2200 mm\",\"Film Carriage Type\":\"Powered Pre-Stretch\",\"Film Width\":\"500 mm\",\"Control System\":\"PLC with Touch Screen HMI\",\"Material\":\"Heavy Duty Steel Construction\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 11:05:51', '2026-06-10 11:05:51'),
(238, 'Carton Sealing Machine', 'carton-sealing-machine', 'Automatic carton sealing machine designed for sealing corrugated boxes using adhesive tape. The machine features a roller conveyor system for smooth box movement and an adjustable taping head for consistent top and bottom carton sealing. Suitable for packaging lines in pharmaceutical, food, FMCG, and logistics industries.', '/uploads/machines/carton-sealing-machine-1781089982.jpg', 'Carton Sealing Machine Manufacturer and Supplier', 'Industrial Carton Sealing Machine with automatic top and bottom tape sealing system, motorized conveyor, adjustable guides, and PLC controls for efficient carton packaging operations.', 2, 8, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Carton Sealing Machine\",\"Capacity\":\"Up to 25 Cartons\\/Minute\",\"Sealing Type\":\"Top & Bottom Tape Sealing\",\"Carton Size Range\":\"Adjustable\",\"Conveyor Type\":\"Motorized Roller Conveyor\",\"Tape Width\":\"48 mm \\u2013 72 mm\",\"Control System\":\"PLC Control Panel\",\"Material\":\"SS304 & Heavy Duty Steel\",\"Power Supply\":\"415V AC\",\"Application\":\"Corrugated Box Packaging\"},\"data\":[]}', '2026-06-10 11:13:02', '2026-06-10 11:13:02'),
(239, 'Shrink Wrapping Machine', 'shrink-wrapping-machine-2', 'Shrink Wrapping Machine is designed for automatic wrapping and bundling of bottles, cans, cartons, and packaged machine_products using heat shrink film. The machine automatically groups machine_products, wraps them with shrink film, and passes them through a heat sealing and shrinking process to create secure multipacks. It is widely used in beverage, pharmaceutical, food processing, FMCG, and packaging industries for efficient secondary packaging and transportation protection.', '/uploads/machines/shrink-wrapping-machine-1781090115.jpg', 'Shrink Wrapping Machine Manufacturer and Supplier', 'Industrial Shrink Wrapping Machine with automatic film wrapping system, conveyorized operation, and PLC controls for bottle, carton, and multipack packaging applications.', 2, 8, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Shrink Wrapping Machine\",\"Capacity\":\"Up to 20 Packs\\/Minute\",\"Wrapping Type\":\"Heat Shrink Film Wrapping\",\"Product Handling\":\"Automatic Grouping System\",\"Film Type\":\"PE \\/ POF Shrink Film\",\"Conveyor Type\":\"Motorized Belt Conveyor\",\"Control System\":\"PLC with Touch Screen HMI\",\"Material\":\"SS304 & Heavy Duty Steel\",\"Power Supply\":\"415V AC\",\"Application\":\"Bottle & Multipack Packaging\"},\"data\":[]}', '2026-06-10 11:15:15', '2026-06-10 11:15:15'),
(240, 'Automatic Carton Packing Machine', 'automatic-carton-packing-machine', 'Automatic Carton Packing Machine is designed for automatic loading and packing of bottles, containers, pouches, and machine_products into corrugated cartons. The machine features a conveyorized carton handling system, automatic product insertion mechanism, and PLC-based control system for high-speed packaging operations. It is widely used in pharmaceutical, food processing, beverage, FMCG, and manufacturing industries for efficient secondary packaging and carton loading applications.', '/uploads/machines/automatic-carton-packing-machine-1781090469.jpg', 'Automatic Carton Packing Machine Manufacturer and Supplier', 'Industrial Automatic Carton Packing Machine with carton magazine feeder, servo pick and place system, conveyorized operation, and PLC controls for high-speed secondary packaging applications.', 2, 8, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Automatic Carton Packing Machine\",\"Capacity\":\"Up to 15 Cartons\\/Minute\",\"Packing Type\":\"Automatic Carton Loading\",\"Carton Feeding\":\"Automatic Magazine Feeding\",\"Conveyor Type\":\"Motorized Belt Conveyor\",\"Product Handling\":\"Servo Controlled Pick & Place\",\"Control System\":\"PLC with Touch Screen HMI\",\"Material\":\"SS304 & Heavy Duty Steel\",\"Power Supply\":\"415V AC\",\"Application\":\"Secondary Packaging\"},\"data\":[]}', '2026-06-10 11:21:09', '2026-06-10 11:21:09'),
(241, 'Automatic Carton Erector Machine', 'automatic-carton-erector-machine', 'Automatic Carton Erector Machine is designed for automatic forming, opening, and erecting corrugated cartons for packaging lines. The machine automatically picks flat carton blanks from the magazine, forms the carton shape, folds the bottom flaps, and prepares cartons for product loading. It is widely used in pharmaceutical, food processing, beverage, FMCG, logistics, and manufacturing industries for high-speed secondary packaging operations.', '/uploads/machines/automatic-carton-erector-machine-1781090748.jpg', 'Automatic Carton Erector Machine Manufacturer and Supplier', 'Industrial Automatic Carton Erector Machine with automatic carton forming, flap folding, conveyorized operation, and PLC controls for high-speed secondary packaging and carton preparation applications.', 2, 8, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Automatic Carton Erector Machine\",\"Capacity\":\"Up to 18 Cartons\\/Minute\",\"Carton Feeding\":\"Automatic Magazine Loading\",\"Carton Type\":\"Corrugated Cartons\",\"Forming System\":\"Automatic Carton Opening & Folding\",\"Conveyor Type\":\"Motorized Roller Conveyor\",\"Control System\":\"PLC with Touch Screen HMI\",\"Material\":\"SS304 & Heavy Duty Steel\",\"Power Supply\":\"415V AC\",\"Application\":\"Secondary Packaging Line\"},\"data\":[]}', '2026-06-10 11:25:48', '2026-06-10 11:25:48'),
(242, 'Robotic Palletizer Machine', 'robotic-palletizer-machine', 'Robotic Palletizer Machine is designed for automatic stacking and palletizing of cartons, cases, bags, and packaged machine_products onto pallets using a high-speed industrial robotic arm. The machine features an intelligent pick-and-place system, vacuum gripper, conveyorized product handling, and PLC-based control system for efficient end-of-line packaging operations. It is widely used in pharmaceutical, food processing, beverage, FMCG, logistics, and manufacturing industries for automated pallet loading and warehouse preparation.', '/uploads/machines/robotic-palletizer-machine-1781091108.jpg', 'Robotic Palletizer Machine Manufacturer and Supplier', 'Industrial Robotic Palletizer Machine with 6-axis robotic arm, vacuum gripper system, conveyorized carton handling, and PLC controls for high-speed automated palletizing and end-of-line packaging operations.', 2, 8, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Robotic Palletizer Machine\",\"Capacity\":\"Up to 1200 Cases\\/Hour\",\"Palletizing Type\":\"Automatic Robotic Palletizing\",\"Robot Type\":\"6-Axis Industrial Robot\",\"Gripper Type\":\"Vacuum Gripper System\",\"Product Handling\":\"Cartons, Cases & Boxes\",\"Conveyor Type\":\"Motorized Roller Conveyor\",\"Control System\":\"PLC with Touch Screen HMI\",\"Material\":\"Heavy Duty Steel Construction\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 11:31:48', '2026-06-10 11:31:48'),
(243, 'Automatic Thermoforming Packaging Machine', 'automatic-thermoforming-packaging-machine', 'Automatic Thermoforming Packaging Machine is designed for forming, filling, vacuum sealing, and packaging machine_products in thermoformed trays using flexible or rigid packaging films. The machine automatically forms product cavities, loads machine_products, applies top film sealing, and delivers finished packs through an integrated conveyor system. It is widely used in food processing, pharmaceutical, medical device, meat, dairy, and industrial packaging applications for hygienic and high-speed packaging operations.', '/uploads/machines/automatic-thermoforming-packaging-machine-1781091600.jpg', 'Automatic Thermoforming Packaging Machine Manufacturer and Supplier', 'Industrial Automatic Thermoforming Packaging Machine with vacuum sealing, tray forming, heat sealing, and PLC controls for food, pharmaceutical, medical, and industrial packaging applications.', 2, 10, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Automatic Thermoforming Packaging Machine\",\"Capacity\":\"Up to 20 Cycles\\/Minute\",\"Packaging Type\":\"Vacuum & Thermoforming Packaging\",\"Film Type\":\"Flexible \\/ Rigid Film\",\"Sealing System\":\"Heat Sealing\",\"Forming Depth\":\"Up to 120 mm\",\"Conveyor Type\":\"Automatic Indexing Conveyor\",\"Control System\":\"PLC with Touch Screen HMI\",\"Material\":\"SS304 Stainless Steel\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 11:40:00', '2026-06-10 11:40:00'),
(244, 'Sigma Mixer Machine', 'sigma-mixer-machine', 'Sigma Mixer Machine is specially designed for intensive mixing, kneading, and homogenizing high-viscosity materials such as adhesives, sealants, rubber compounds, pharmaceuticals, cosmetics, food pastes, and chemical machine_products. The machine utilizes twin sigma-shaped blades that rotate at different speeds to ensure uniform mixing and efficient product consistency. Its heavy-duty construction and advanced control system make it ideal for pharmaceutical, food, cosmetic, and chemical processing industries.', '/uploads/machines/sigma-mixer-machine-1781092631.jpg', 'Sigma Mixer Machine Manufacturer and Supplier', 'Industrial Sigma Mixer Machine with twin sigma blades for intensive kneading, blending, and homogenizing high-viscosity materials in pharmaceutical, chemical, cosmetic, food, and industrial processing applications.', 1, 15, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Sigma Mixer Machine\",\"Capacity\":\"50 \\u2013 1000 Liters\",\"Mixing Type\":\"Heavy Duty Kneading & Mixing\",\"Blade Type\":\"Twin Sigma Blades\",\"Working Volume\":\"Up to 80% of Vessel Capacity\",\"Discharge System\":\"Bottom Valve \\/ Hydraulic Tilting\",\"Speed Control\":\"Variable Frequency Drive (VFD)\",\"Control System\":\"PLC \\/ Digital Control Panel\",\"Material\":\"SS304 \\/ SS316 Stainless Steel\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 11:57:11', '2026-06-10 11:57:11'),
(245, 'Multi Effect Evaporator', 'multi-effect-evaporator', 'Multi Effect Evaporator (MEE) is designed for efficient concentration and evaporation of liquids by utilizing multiple evaporation stages to reduce steam consumption and improve energy efficiency. The system consists of interconnected evaporator vessels, condensers, feed tanks, circulation pumps, and automated control systems. It is widely used in pharmaceutical, chemical, food processing, dairy, wastewater treatment, and industrial manufacturing applications for concentrating solutions and recovering valuable machine_products.', '/uploads/machines/multi-effect-evaporator-1781093341.jpg', 'Multi Effect Evaporator Manufacturer and Supplier', 'Industrial Multi Effect Evaporator system with multiple evaporation stages, condenser, feed tank, and PLC controls for pharmaceutical, chemical, food processing, wastewater treatment, and liquid concentration applications.', 1, 15, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Multi Effect Evaporator\",\"Capacity\":\"500 \\u2013 20,000 LPH\",\"Number of Effects\":\"3 to 7 Effects\",\"Evaporation Type\":\"Falling Film \\/ Forced Circulation\",\"Steam Consumption\":\"Energy Efficient Multi-Stage Design\",\"Condenser Type\":\"Surface Condenser\",\"Control System\":\"PLC with Touch Screen HMI\",\"Material\":\"SS304 \\/ SS316 Stainless Steel\",\"Application\":\"Liquid Concentration & Solvent Recovery\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 12:09:01', '2026-06-10 12:09:01'),
(246, 'Ribbon Blender Machine', 'ribbon-blender-machine', 'Ribbon Blender Machine is designed for homogeneous mixing and blending of powders, granules, spices, chemicals, pharmaceutical ingredients, food machine_products, and dry materials. The machine utilizes specially designed inner and outer ribbon agitators that provide efficient radial and axial mixing for consistent product quality. It is widely used in pharmaceutical, food processing, chemical, cosmetic, and nutraceutical industries for high-performance batch blending applications.', '/uploads/machines/ribbon-blender-machine-1781093473.jpg', 'Ribbon Blender Machine Manufacturer and Supplier', 'Industrial Ribbon Blender Machine with double helical ribbon agitator for uniform mixing of powders, granules, spices, chemicals, pharmaceutical ingredients, and food machine_products. Ideal for high-efficiency batch blending applications.', 1, 13, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Ribbon Blender Machine\",\"Capacity\":\"100 \\u2013 5000 Liters\",\"Mixing Type\":\"Horizontal Ribbon Blending\",\"Agitator Type\":\"Double Helical Ribbon\",\"Batch Type\":\"Batch Mixing\",\"Discharge System\":\"Bottom Center Valve\",\"Mixing Speed\":\"Variable Speed Drive\",\"Control System\":\"PLC \\/ Digital Control Panel\",\"Material\":\"SS304 \\/ SS316 Stainless Steel\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 12:11:13', '2026-06-10 12:11:13');
INSERT INTO `machine_machines` (`id`, `machine_name`, `slug`, `description`, `image_url`, `meta_title`, `meta_description`, `category_id`, `subcategory_id`, `specifications`, `created_at`, `updated_at`) VALUES
(247, 'Homogenizer Mixing Tank', 'homogenizer-mixing-tank', 'Homogenizer Mixing Tank is designed for high-shear mixing, homogenizing, emulsifying, and blending of liquids, creams, lotions, suspensions, and viscous machine_products. The integrated high-speed homogenizer ensures uniform particle size distribution and excellent product consistency. It is widely used in pharmaceutical, cosmetic, food processing, chemical, and personal care industries for producing stable and homogeneous formulations.', '/uploads/machines/homogenizer-mixing-tank-1781093850.jpg', 'Homogenizer Mixing Tank Manufacturer and Supplier', 'Industrial Homogenizer Mixing Tank with high-shear homogenizer, variable speed control, and stainless steel construction for pharmaceutical, cosmetic, food processing, and chemical manufacturing applications.', 1, 13, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Homogenizer Mixing Tank\",\"Capacity\":\"100 \\u2013 5000 Liters\",\"Mixing Type\":\"Homogenizing & Emulsifying\",\"Homogenizer Type\":\"High Shear Bottom \\/ Top Mounted\",\"Agitator Type\":\"Anchor & Homogenizer Combination\",\"Operating Speed\":\"Variable Speed Control\",\"Discharge System\":\"Bottom Outlet Valve\",\"Control System\":\"PLC \\/ Digital Control Panel\",\"Material\":\"SS304 \\/ SS316 Stainless Steel\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 12:17:30', '2026-06-10 12:17:30'),
(248, 'Vacuum Tray Dryer', 'vacuum-tray-dryer', 'Vacuum Tray Dryer is designed for low-temperature drying of heat-sensitive pharmaceutical, chemical, food, and herbal machine_products under vacuum conditions. The machine utilizes heated trays inside a sealed vacuum chamber to remove moisture efficiently while preserving product quality, color, and active ingredients. It is widely used in pharmaceutical manufacturing, chemical processing, food dehydration, and research laboratories for uniform and controlled drying applications.', '/uploads/machines/vacuum-tray-dryer-1781094184.jpg', 'Vacuum Tray Dryer Manufacturer and Supplier', 'Industrial Vacuum Tray Dryer with stainless steel vacuum chamber, multiple drying trays, PLC control system, and efficient low-temperature drying technology for pharmaceutical, chemical, food processing, and herbal applications.', 1, 13, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Vacuum Tray Dryer\",\"Capacity\":\"24 \\u2013 192 Trays\",\"Drying Method\":\"Vacuum Drying\",\"Chamber Type\":\"Horizontal Vacuum Chamber\",\"Heating System\":\"Steam \\/ Hot Water Heating\",\"Operating Vacuum\":\"Up to 760 mmHg\",\"Tray Material\":\"SS304 \\/ SS316 Stainless Steel\",\"Control System\":\"PLC with Touch Screen HMI\",\"Application\":\"Pharmaceutical, Chemical & Food Products\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 12:20:46', '2026-06-10 12:23:04'),
(249, 'Falling Film Evaporator', 'falling-film-evaporator', 'Falling Film Evaporator is designed for efficient concentration of heat-sensitive liquids through continuous evaporation under controlled temperature conditions. The system allows the liquid to flow as a thin film along heated tubes, ensuring rapid heat transfer, reduced residence time, and superior product quality. It is widely used in pharmaceutical, food processing, dairy, chemical, and beverage industries for concentration, solvent recovery, and evaporation applications.', '/uploads/machines/falling-film-evaporator-1781094854.jpg', 'Falling Film Evaporator Manufacturer and Supplier', 'Industrial Falling Film Evaporator with high-efficiency heat transfer technology for liquid concentration, solvent recovery, and evaporation processes in pharmaceutical, dairy, food processing, beverage, and chemical industries.', 1, 13, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Falling Film Evaporator\",\"Capacity\":\"100 \\u2013 10,000 LPH\",\"Evaporation Type\":\"Falling Film Evaporation\",\"Heating Method\":\"Steam Heated\",\"Operating Mode\":\"Continuous Process\",\"Product Contact Material\":\"SS316 Stainless Steel\",\"Condenser Type\":\"Integrated Condensing System\",\"Control System\":\"PLC with Touch Screen HMI\",\"Application\":\"Liquid Concentration & Solvent Recovery\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 12:34:14', '2026-06-10 12:34:14'),
(250, 'Fluid Bed Processor (FBP)', 'fluid-bed-processor-fbp', 'Fluid Bed Processor (FBP) is designed for drying, granulation, coating, and agglomeration of pharmaceutical powders and granules using controlled fluidization technology. The system utilizes heated air to suspend and process materials uniformly, ensuring efficient moisture removal and consistent product quality. It is widely used in pharmaceutical, nutraceutical, food processing, and chemical industries for high-performance batch processing applications.', '/uploads/machines/fluid-bed-processor-fbp-1781094947.jpg', 'Fluid Bed Processor Manufacturer and Supplier', 'Industrial Fluid Bed Processor with advanced drying, granulation, and coating technology for pharmaceutical, nutraceutical, food processing, and chemical manufacturing applications. High-efficiency stainless steel processing equipment.', 1, 13, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Fluid Bed Processor\",\"Capacity\":\"5 \\u2013 500 Kg\\/Batch\",\"Processing Type\":\"Drying, Granulation & Coating\",\"Container Type\":\"Fluidized Product Bowl\",\"Heating System\":\"Electric \\/ Steam Heating\",\"Filter System\":\"Finger Bag Filter Assembly\",\"Air Flow Control\":\"Variable Air Volume Control\",\"Control System\":\"PLC with Touch Screen HMI\",\"Material\":\"SS304 \\/ SS316 Stainless Steel\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 12:35:47', '2026-06-10 12:35:47'),
(251, 'Spice Powder Packing Machine', 'spice-powder-packing-machine', 'Spice Powder Packing Machine is designed for accurate filling and packaging of spice powders such as chili powder, turmeric powder, coriander powder, cumin powder, and blended seasonings. The machine utilizes an auger filling system combined with vertical form fill seal (VFFS) technology to ensure precise dosing, leak-proof sealing, and high-speed pouch production. It is widely used in food processing, spice manufacturing, seasoning production, and packaging industries.', '/uploads/machines/spice-powder-packing-machine-1781095361.jpg', 'Spice Powder Packing Machine Manufacturer and Supplier', 'Industrial Spice Powder Packing Machine with auger filling system and VFFS technology for accurate packaging of chili powder, turmeric powder, coriander powder, seasoning blends, and other powdered food machine_products.', 2, 10, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Spice Powder Packing Machine\",\"Capacity\":\"Up to 60 Pouches\\/Minute\",\"Filling System\":\"Auger Screw Filling\",\"Packaging Type\":\"Center Seal \\/ Three Side Seal Pouch\",\"Product Type\":\"Spice & Powder Products\",\"Pouch Size Range\":\"10g \\u2013 1000g\",\"Sealing Type\":\"Heat Sealing\",\"Control System\":\"PLC with Touch Screen HMI\",\"Material\":\"SS304 Stainless Steel\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 12:42:41', '2026-06-10 12:42:41'),
(252, 'Coffee Powder Packing Machine', 'coffee-powder-packing-machine', 'Coffee Powder Packing Machine is designed for accurate filling and packaging of coffee powder, instant coffee, premix coffee, and beverage powders into sealed pouches. The machine utilizes an auger filling system combined with vertical form fill seal (VFFS) technology to ensure precise dosing, hygienic packaging, and high-speed production. It is widely used in coffee processing plants, beverage industries, food manufacturing units, and contract packaging facilities.', '/uploads/machines/coffee-powder-packing-machine-1781095659.jpg', 'Coffee Powder Packing Machine Manufacturer and Supplier', 'Industrial Coffee Powder Packing Machine with auger filling system and VFFS technology for accurate packaging of coffee powder, instant coffee, premixes, and beverage powders in hygienic sealed pouches.', 2, 10, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Coffee Powder Packing Machine\",\"Capacity\":\"Up to 60 Pouches\\/Minute\",\"Filling System\":\"Auger Screw Filling\",\"Packaging Type\":\"Center Seal \\/ Three Side Seal Pouch\",\"Product Type\":\"Coffee Powder & Beverage Premixes\",\"Pouch Size Range\":\"10g \\u2013 1000g\",\"Sealing Type\":\"Heat Sealing\",\"Control System\":\"PLC with Touch Screen HMI\",\"Material\":\"SS304 Stainless Steel\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 12:47:39', '2026-06-10 12:47:39'),
(253, 'Flour Packing Machine', 'flour-packing-machine', 'Flour Packing Machine is designed for accurate weighing, filling, and packaging of wheat flour, atta, maida, besan, rice flour, and other powdered food machine_products into pouches and bags. The machine utilizes an auger filling system with automatic pouch forming, filling, and sealing technology to ensure precise dosing, minimal product wastage, and high-speed production. It is widely used in flour mills, food processing plants, grain processing industries, and commercial packaging facilities.', '/uploads/machines/flour-packing-machine-1781095948.jpg', 'Flour Packing Machine Manufacturer and Supplier', 'Industrial Flour Packing Machine with automatic auger filling and pouch sealing system for accurate packaging of atta, maida, besan, rice flour, and other powder machine_products in various bag sizes.', 2, 8, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Flour Packing Machine\",\"Capacity\":\"Up to 40 Bags\\/Minute\",\"Filling System\":\"Auger Screw Filling\",\"Packaging Type\":\"Pillow Pouch \\/ Gusset Bag\",\"Product Type\":\"Flour & Powder Products\",\"Filling Range\":\"500g \\u2013 10kg\",\"Sealing Type\":\"Heat Sealing\",\"Control System\":\"PLC with Touch Screen HMI\",\"Material\":\"SS304 Stainless Steel\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 12:52:28', '2026-06-10 12:52:28'),
(254, 'Net Weigh Filling Machine', 'net-weigh-filling-machine', 'Net Weigh Filling Machine is designed for accurate weighing and filling of granular, powder, and free-flowing machine_products into bags and pouches. The machine uses an advanced load cell-based net weighing system to ensure precise weight control before product discharge into the package. It is widely used in food processing, agriculture, chemical, fertilizer, rice, grain, flour, and industrial packaging applications where high accuracy and productivity are required.', '/uploads/machines/net-weigh-filling-machine-1781096247.jpg', 'Net Weigh Filling Machine Manufacturer and Supplier', 'Industrial Net Weigh Filling Machine with load cell based weighing system for accurate filling of powder, granules, grains, rice, flour, fertilizer and free-flowing machine_products into bags and pouches.', 2, 10, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Net Weigh Filling Machine\",\"Capacity\":\"Up to 20 Bags\\/Minute\",\"Filling System\":\"Load Cell Based Net Weighing\",\"Product Type\":\"Powder, Granules & Free Flowing Products\",\"Weighing Range\":\"1kg \\u2013 50kg\",\"Accuracy\":\"\\u00b10.2%\",\"Bag Type\":\"Open Mouth Bags & Pouches\",\"Control System\":\"PLC with Touch Screen HMI\",\"Material\":\"SS304 Stainless Steel\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 12:57:27', '2026-06-10 12:57:27'),
(255, 'Cup Filling & Sealing Machine', 'cup-filling-sealing-machine', 'Cup Filling & Sealing Machine is designed for automatic filling and sealing of cups containing yogurt, curd, dairy machine_products, sauces, jams, jelly, beverages, and semi-liquid machine_products. The machine utilizes a rotary indexing system with precise volumetric filling and heat sealing technology to ensure hygienic packaging, leak-proof sealing, and high production efficiency. It is widely used in dairy, food processing, beverage, and pharmaceutical industries.', '/uploads/machines/cup-filling-sealing-machine-1781097604.jpg', 'Cup Filling & Sealing Machine', '', 2, 8, '{\"meta\":[],\"specifications\":{\"Machine Type\":\"Cup Filling & Sealing Machine\",\"Capacity\":\"Up to 80 Cups\\/Minute\",\"Filling System\":\"Volumetric Piston Filling\",\"Packaging Type\":\"Preformed Cups\",\"Cup Size Range\":\"50 ml \\u2013 1000 ml\",\"Sealing Type\":\"Heat Seal Foil Sealing\",\"Indexing System\":\"Rotary Automatic Indexing\",\"Control System\":\"PLC with Touch Screen HMI\",\"Material\":\"SS304 Stainless Steel\",\"Power Supply\":\"415V AC\"},\"data\":[]}', '2026-06-10 13:20:04', '2026-06-10 13:20:04');
